 USE SGEV60_V164;
-- 1
 CREATE OR REPLACE VIEW  VIEW_ACTECOXCLI AS 
SELECT  ACT_CODIGO AS ACC_CODIGO,              IF(CLI_ACTIVI<>"",COUNT(*),0) AS ACC_CANTID              FROM 
  DPACTIVIDAD_E              LEFT JOIN DPCLIENTES  ON ACT_CODIGO=CLI_ACTIVI OR CLI_ACTIVI IS NULL             
 GROUP BY  ACT_CODIGO,ACT_DESCRI
;

-- 2
 CREATE OR REPLACE VIEW  VIEW_DPACTIVOS_CTA AS 
SELECT  CIC_CTAMOD AS ATV_CTAMOD, ATV_CODIGO, ATV_DESCRI,COUNT(*) AS ATV_CANTID   FROM 
 DPACTIVOS  LEFT JOIN DPACTIVOS_CTA ON CIC_CODIGO=ATV_CODIGO 
 GROUP BY CIC_CTAMOD,ATV_CODIGO 
 ORDER BY CIC_CTAMOD,ATV_CODIGO;

-- 3
 CREATE OR REPLACE VIEW  VIEW_ACTIVOSXACTFIN AS 
SELECT       DEP_CODACT     AS AAF_CODACT,      MIN(DEP_FECHA) AS AAF_DESDE ,      MAX(DEP_FECHA) AS AAF_HASTA ,     
 SUM(DEP_MONTO) AS AAF_MONTO ,      COUNT(*)       AS AAF_CANTID      FROM 
 DPDEPRECIAACT                 WHERE DEP_DEPFIN=0 OR DEP_DEPFIN IS NULL     
 GROUP BY DEP_CODACT     
 ORDER BY DEP_CODACT
;

-- 4
 CREATE OR REPLACE VIEW  VIEW_ACTIVOSSINCTA AS 
SELECT   ATV_CODIGO AS ASC_CODIGO  FROM 
 DPACTIVOS  LEFT JOIN DPACTIVOS_CTA ON CIC_CODIGO=ATV_CODIGO  WHERE ATV_ESTADO="A" AND ATV_DEPRE="D" AND CIC_CODIGO IS NULL
;

-- 5
 CREATE OR REPLACE VIEW  VIEW_DPASIENTOSAAC AS 
SELECT   MOC_CODSUC AS AAC_CODSUC,  CBT_NUMEJE AS AAC_NUMEJE,  MOC_CUENTA AS AAC_CUENTA,  IF(MOC_ACTUAL="N",SUM(MOC_MONTO),0) AS AAC_PORACT,  IF(MOC_ACTUAL="S",SUM(MOC_MONTO),0) AS AAC_MTOACT,  IF(MOC_ACTUAL="F",SUM(MOC_MONTO),0) AS AAC_MTOFIN,  IF(MOC_ACTUAL="X",SUM(MOC_MONTO),0) AS AAC_MTOFIS,  IF(MOC_ACTUAL="A",SUM(MOC_MONTO),0) AS AAC_MTOAUD  FROM 
 DPASIENTOS 
 INNER JOIN DPCBTE ON MOC_CODSUC=CBT_CODSUC AND MOC_ACTUAL=CBT_ACTUAL AND MOC_FECHA=CBT_FECHA AND MOC_NUMCBT=CBT_NUMERO                                       
 GROUP BY MOC_CODSUC,CBT_NUMEJE,MOC_CUENTA 
 ORDER BY MOC_CODSUC,CBT_NUMEJE,MOC_CUENTA
;

-- 6
 CREATE OR REPLACE VIEW  VIEW_ACUMULADOS AS 
SELECT           REC_CODSUC AS ACU_CODSUC,          REC_CODTRA AS ACU_CODTRA,          HIS_CODCON AS ACU_CODCON,                MIN(FCH_DESDE)  AS ACU_DESDE,           MAX(FCH_HASTA)  AS ACU_HASTA,               
 SUM(HIS_MONTO)  AS ACU_MONTO,         
 SUM(HIS_VARIAC) AS ACU_VARIAC          FROM 
 NMHISTORICO                      
 INNER JOIN NMRECIBOS ON REC_CODSUC=HIS_CODSUC AND REC_NUMERO=HIS_NUMREC                      
 INNER JOIN NMFECHAS  ON FCH_CODSUC=REC_CODSUC AND FCH_NUMERO=REC_NUMFCH               
 INNER JOIN NMCONCEPTOS ON HIS_CODCON=CON_CODIGO              WHERE CON_RECACU=1                    
 GROUP BY REC_CODSUC,REC_CODTRA,HIS_CODCON         
 ORDER BY REC_CODSUC,REC_CODTRA,HIS_CODCON
;

-- 7
 CREATE OR REPLACE VIEW  VIEW_DPDOCPRONUMPAG AS 
SELECT     DOC_CODSUC,    DOC_PAGNUM,   
 SUM(DOC_NETO*DOC_ACT) AS DOC_NETO,  COUNT(*) AS DOC_CANTID     FROM 
 DPDOCPRO   
 INNER JOIN DPCBTEPAGO ON PAG_CODSUC=DOC_CODSUC AND PAG_NUMERO=DOC_PAGNUM AND DOC_TIPTRA="P"   
 GROUP BY DOC_CODSUC,DOC_PAGNUM   
 ORDER BY DOC_CODSUC,DOC_PAGNUM
;

-- 8
 CREATE OR REPLACE VIEW  VIEW_DPCTAAXI_ANUAL AS 
SELECT  EJE_CODSUC AS AME_CODSUC,  MOC_CTAMOD AS AME_CTAMOD,  MOC_CUENTA AS AME_CUENTA,  date_add(EJE_DESDE, INTERVAL -1 DAY) AS FCH_FCHANT,  EJE_DESDE  AS AME_EJEINI,  EJE_HASTA  AS AME_EJEFIN, 
 SUM(IF(MOC_FECHA< EJE_DESDE,MOC_MONTO,0)) AS AME_MTOINI, 
 SUM(IF(MOC_FECHA<=EJE_HASTA,MOC_MONTO,0)) AS AME_MTOFIN,  HMN_VALOR AS AME_VALCAM,  IPC_ANO,  IPC_MES,  IPC_TASA,  IPC_INPC  FROM 
  dpejercicios 
 INNER JOIN dpasientos       ON EJE_CODSUC=MOC_CODSUC AND MOC_ACTUAL="S" 
 INNER JOIN dpcta            ON MOC_CTAMOD=CTA_CODMOD AND MOC_CUENTA=CTA_CODIGO AND (CTA_PROPIE="Moneda Extranjera" OR CTA_PROPIE="Patrimonio" OR CTA_PROPIE="Monetarias") LEFT  JOIN dphismon         ON date_add(EJE_DESDE, INTERVAL -1 DAY)=HMN_FECHA AND HMN_CODIGO="DBC"  LEFT JOIN ADMCONFIG51.dpipc ON YEAR(EJE_DESDE)=IPC_ANO AND MONTH(EJE_DESDE)=IPC_MES 
 GROUP BY EJE_CODSUC,EJE_DESDE,EJE_HASTA,MOC_CTAMOD,MOC_CUENTA ;

-- 9
 CREATE OR REPLACE VIEW  VIEW_ARCANUAL AS 
SELECT    DOC_CODSUC       AS ARC_CODSUC,  EJE_NUMERO       AS ARC_ANO,     DOC_CODIGO       AS ARC_CODIGO, 
 SUM(RXP_MTOBAS)  AS ARC_MTOBAS, 
 SUM(RXP_MTORET)  AS ARC_MTORET,  COUNT(*)         AS ARC_CANTID   FROM 
 DPDOCPROISLR 
 INNER JOIN DPDOCPRO ON RXP_CODSUC=DOC_CODSUC AND RXP_DOCTIP=DOC_TIPDOC AND RXP_CODSUC=DOC_CODSUC AND RXP_CODIGO=DOC_CODIGO  AND RXP_DOCNUM=DOC_NUMERO AND DOC_TIPTRA="D" 
 INNER JOIN dpejercicios ON DOC_FECHA>=EJE_DESDE AND DOC_FECHA<=EJE_HASTA  WHERE DOC_ACT=1 
 GROUP BY DOC_CODSUC, EJE_NUMERO,DOC_CODIGO 
 ORDER BY DOC_CODSUC, EJE_NUMERO,DOC_CODIGO;

-- 10
 CREATE OR REPLACE VIEW  VIEW_ARCANUALYMENSUAL AS 
SELECT       DOC_CODSUC       AS ARC_CODSUC,      YEAR(DOC_FECHA)  AS ARC_ANO,      MONTH(DOC_FECHA) AS ARC_MES,      DOC_CODIGO       AS ARC_CODIGO,     
 SUM(RXP_MTOBAS)  AS ARC_MTOBAS,      
 SUM(RXP_MTORET)  AS ARC_MTORET,       COUNT(*)         AS ARC_CANTID      FROM 
 DPDOCPROISLR     
 INNER JOIN DPDOCPRO ON RXP_CODSUC=DOC_CODSUC AND RXP_DOCTIP=DOC_TIPDOC AND RXP_CODSUC=DOC_CODSUC AND RXP_CODIGO=DOC_CODIGO  AND RXP_DOCNUM=DOC_NUMERO AND DOC_TIPTRA="D"  AND DOC_ACT=1     
 GROUP BY DOC_CODSUC, YEAR(DOC_FECHA),MONTH(DOC_FECHA),DOC_CODIGO      
 ORDER BY DOC_CODSUC, YEAR(DOC_FECHA),MONTH(DOC_FECHA),DOC_CODIGO
;

-- 11
 CREATE OR REPLACE VIEW  VIEW_ACTIVOSMOC AS 
SELECT         CBT_CODSUC AS CAC_CODSUC,      CBT_NUMEJE AS CAC_NUMEJE,        CIC_CODINT AS CAC_CODINT,        MOC_CUENTA AS CAC_CODCTA,        CTA_DESCRI AS CAC_DESCRI,       
 SUM(IF(MOC_ACTUAL="N",MOC_MONTO,0)) AS CAC_MTODIF,       
 SUM(IF(MOC_ACTUAL="S",MOC_MONTO,0)) AS CAC_MTOACT,       
 SUM(IF(MOC_ACTUAL="A",MOC_MONTO,0)) AS CAC_MTOAUD,       
 SUM(IF(MOC_ACTUAL="X",MOC_MONTO,0)) AS CAC_MTOFIS,       
 SUM(IF(MOC_ACTUAL="F",MOC_MONTO,0)) AS CAC_MTOFIN        FROM 
 DPASIENTOS       
 INNER JOIN DPCTA          ON MOC_CTAMOD=CTA_CODMOD AND MOC_CUENTA=CTA_CODIGO       
 INNER JOIN DPACTIVOS_CTA  ON CIC_CTAMOD=CTA_CODMOD AND CIC_CUENTA=CTA_CODIGO       
 INNER JOIN DPCBTE         ON MOC_CODSUC=CBT_CODSUC AND MOC_ACTUAL=CBT_ACTUAL AND MOC_FECHA=CBT_FECHA AND MOC_NUMCBT=CBT_NUMERO       
 GROUP BY CBT_CODSUC,CBT_NUMEJE,CIC_CODINT
;

-- 12
 CREATE OR REPLACE VIEW  VIEW_ASIENTOORGCOM AS 
SELECT                 MOC_CODSUC,MOC_TIPO,MOC_CODAUX,MOC_DOCUME,MOC_FECHA,MOC_NUMCBT,MOC_ACTUAL,MOC_TIPTRA,MOC_DOCPAG,               
 SUM(IF(MOC_MONTO>0,MOC_MONTO,NULL))    AS MOC_DEBE,               
 SUM(IF(MOC_MONTO<0,MOC_MONTO*-1,NULL)) AS MOC_HABER,          COUNT(*) AS MOC_CANTID ,      MOC_ITEM,MOC_CUENTA                FROM 
 DPASIENTOS     
 INNER JOIN DPTIPDOCPRO ON TDC_TIPO=MOC_TIPO             WHERE MOC_ORIGEN="COM"               
 GROUP BY MOC_CODSUC,MOC_TIPO,MOC_CODAUX,MOC_DOCUME,MOC_FECHA,MOC_NUMCBT,MOC_DOCPAG,MOC_ACTUAL,MOC_TIPTRA           
 ORDER BY MOC_CODSUC,MOC_TIPO,MOC_CODAUX,MOC_DOCUME,MOC_FECHA,MOC_NUMCBT,MOC_DOCPAG,MOC_ACTUAL,MOC_TIPTRA
;

-- 13
 CREATE OR REPLACE VIEW  VIEW_ASIENTOSDOCCLI AS 
SELECT    MOC_CODSUC,         MOC_NUMCBT,          MOC_ACTUAL,          MOC_FECHA ,          MOC_TIPO  ,          MOC_DOCUME,          MOC_TIPTRA,          MOC_ORIGEN          FROM 
 DPASIENTOS          WHERE          MOC_ORIGEN="VTA" AND          MOC_TIPTRA="D"         
 ORDER BY MOC_CODSUC,MOC_TIPO,MOC_DOCUME
;

-- 14
 CREATE OR REPLACE VIEW  VIEW_ASIENTOORGBCO AS 
SELECT             MOC_CODSUC,MOC_TIPO,MOC_CODAUX,MOC_DOCUME,MOC_FECHA,MOC_NUMCBT,MOC_ACTUAL,MOC_TIPTRA,MOC_DOCPAG,           
 SUM(IF(MOC_MONTO>0,MOC_MONTO,NULL))    AS MOC_DEBE,           
 SUM(IF(MOC_MONTO<0,MOC_MONTO*-1,NULL)) AS MOC_HABER,      COUNT(*) AS MOC_CANTID,    MOC_ITEM,MOC_CUENTA   FROM 
 DPASIENTOS             WHERE MOC_ORIGEN="BCO"           
 GROUP BY MOC_CODSUC,MOC_TIPO,MOC_CODAUX,MOC_DOCUME,MOC_FECHA,MOC_NUMCBT,MOC_DOCPAG,MOC_ACTUAL,MOC_TIPTRA       
 ORDER BY MOC_CODSUC,MOC_TIPO,MOC_CODAUX,MOC_DOCUME,MOC_FECHA,MOC_NUMCBT,MOC_DOCPAG,MOC_ACTUAL,MOC_TIPTRA
;

-- 15
 CREATE OR REPLACE VIEW  VIEW_ASIENTOSORGCOM AS 
SELECT                   MOC_CODSUC,MOC_TIPO,MOC_CODAUX,MOC_DOCUME,MOC_FECHA,MOC_NUMCBT,MOC_ACTUAL,MOC_TIPTRA,MOC_DOCPAG,                 
 SUM(IF(MOC_MONTO>0,MOC_MONTO,NULL))    AS MOC_DEBE,                 
 SUM(IF(MOC_MONTO<0,MOC_MONTO*-1,NULL)) AS MOC_HABER,            COUNT(*) AS MOC_CANTID,        MOC_ITEM,MOC_CUENTA                  FROM 
 DPASIENTOS                   WHERE MOC_ORIGEN="COM"                 
 GROUP BY MOC_CODSUC,MOC_TIPO,MOC_CODAUX,MOC_DOCUME,MOC_FECHA,MOC_NUMCBT,MOC_DOCPAG,MOC_ACTUAL,MOC_TIPTRA             
 ORDER BY MOC_CODSUC,MOC_TIPO,MOC_CODAUX,MOC_DOCUME,MOC_FECHA,MOC_NUMCBT,MOC_DOCPAG,MOC_ACTUAL,MOC_TIPTRA
;

-- 16
 CREATE OR REPLACE VIEW  VIEW_ASIENTOSORGINV AS 
SELECT                   MOC_CODSUC,    MOC_TIPO,    MOC_CODAUX,    MOC_DOCUME,    MOC_FECHA,    MOC_NUMCBT,    MOC_ACTUAL,MOC_TIPTRA,MOC_DOCPAG,                 
 SUM(IF(MOC_MONTO>0,MOC_MONTO,NULL))    AS MOC_DEBE,                 
 SUM(IF(MOC_MONTO<0,MOC_MONTO*-1,NULL)) AS MOC_HABER,            COUNT(*) AS MOC_CANTID,        MOC_ITEM,    MOC_CUENTA                  FROM 
 DPASIENTOS                   WHERE MOC_ORIGEN="INV"                 
 GROUP BY MOC_CODSUC,MOC_TIPO,MOC_CODAUX,MOC_DOCUME,MOC_FECHA,MOC_NUMCBT,MOC_DOCPAG,MOC_ACTUAL,MOC_TIPTRA             
 ORDER BY MOC_CODSUC,MOC_TIPO,MOC_CODAUX,MOC_DOCUME,MOC_FECHA,MOC_NUMCBT,MOC_DOCPAG,MOC_ACTUAL,MOC_TIPTRA
;

-- 17
 CREATE OR REPLACE VIEW  VIEW_ASIENTOORGVTA AS 
SELECT                 MOC_CODSUC,  MOC_TIPO,  MOC_CODAUX,  MOC_DOCUME,  MOC_FECHA,  MOC_NUMCBT,  MOC_ACTUAL,MOC_TIPTRA,MOC_DOCPAG,               
 SUM(IF(MOC_MONTO>0,MOC_MONTO,NULL))    AS MOC_DEBE,               
 SUM(IF(MOC_MONTO<0,MOC_MONTO*-1,NULL)) AS MOC_HABER,          COUNT(*) AS MOC_CANTID,      MOC_ITEM,  MOC_CUENTA                FROM 
 DPASIENTOS                 WHERE MOC_ORIGEN="VTA"               
 GROUP BY MOC_CODSUC,MOC_TIPO,MOC_CODAUX,MOC_DOCUME,MOC_FECHA,MOC_NUMCBT,MOC_DOCPAG,MOC_ACTUAL,MOC_TIPTRA           
 ORDER BY MOC_CODSUC,MOC_TIPO,MOC_CODAUX,MOC_DOCUME,MOC_FECHA,MOC_NUMCBT,MOC_DOCPAG,MOC_ACTUAL,MOC_TIPTRA
;

-- 18
 CREATE OR REPLACE VIEW  VIEW_ASIENTOS_TI AS 
SELECT              EJE_NUMERO AS BTI_NUMEJE,              EJE_CODSUC AS BTI_CODSUC,              EJE_CBTTRA AS BTI_NUMCBT,              MOC_CTAMOD AS BTI_CTAMOD,              MOC_ITEM   AS BTI_ITEM,              MOC_CUENTA AS BTI_CUENTA,          CTA_DESCRI AS BTI_DESCRI,    MOC_MONTO  AS RTI_MONTO              FROM 
 DPEJERCICIOS             
 INNER JOIN DPASIENTOS ON EJE_CODSUC=MOC_CODSUC AND EJE_CBTTRA=MOC_NUMCBT AND MOC_TIPO="BI" AND MOC_ACTUAL="S"           
 INNER JOIN DPCTA      ON MOC_CTAMOD=CTA_CODMOD AND MOC_CUENTA=CTA_CODIGO            WHERE EJE_CBTTRA<>""              
 GROUP BY EJE_CODSUC,EJE_CBTTRA,MOC_CTAMOD,MOC_ITEM
;

-- 19
 CREATE OR REPLACE VIEW  VIEW_ASIENTOSDEPHIS AS 
SELECT         MOC_CODSUC AS ADA_CODSUC,        MOC_ACTUAL AS ADA_ACTUAL,        MOC_FECHA  AS ADA_FECHA,        MOC_NUMCBT AS ADA_NUMCBT,        MOC_NUMPAR AS ADA_NUMPAR        FROM 
 DPDEPRECIAACT       
 INNER JOIN DPASIENTOS ON DEP_CODSUC=MOC_CODSUC AND DEP_COMPRO=MOC_NUMCBT AND DEP_FECHA=MOC_FECHA AND DEP_NUMPAR=MOC_NUMPAR       
 INNER JOIN DPCTA      ON MOC_CTAMOD=CTA_CODMOD AND MOC_CUENTA=CTA_CODIGO        WHERE MOC_ACTUAL="S" OR MOC_ACTUAL="N"       
 GROUP BY MOC_CODSUC,MOC_FECHA,MOC_NUMCBT,MOC_NUMPAR       
 ORDER BY MOC_CODSUC,MOC_FECHA,MOC_NUMCBT,MOC_NUMPAR
;

-- 20
 CREATE OR REPLACE VIEW  VIEW_ASIENTOSHFX AS 
SELECT     MOC_CODSUC AS HFX_CODSUC,    MOC_CTAMOD AS HFX_CTAMOD,    MOC_CUENTA AS HFX_CUENTA,    MOC_FECHA  AS HFX_FECHA ,    MOC_NUMCBT AS HFX_NUMCBT,   
 SUM(IF(MOC_ACTUAL="S",MOC_MONTO,0)) AS HFX_MTOHIS,   
 SUM(IF(MOC_ACTUAL="F",MOC_MONTO,0)) AS HFX_MTOFIS,   
 SUM(IF(MOC_ACTUAL="X",MOC_MONTO,0)) AS HFX_MTOFIN    FROM 
 DPASIENTOS   
 INNER JOIN DPCTA ON CTA_CODMOD=MOC_CTAMOD AND CTA_CODIGO=MOC_CUENTA     WHERE (MOC_ACTUAL="S" OR MOC_ACTUAL="F" OR MOC_ACTUAL="X")    
 GROUP BY MOC_CODSUC,MOC_CTAMOD,MOC_CUENTA,MOC_FECHA,MOC_NUMCBT   
 ORDER BY MOC_CODSUC,MOC_CTAMOD,MOC_CUENTA,MOC_FECHA,MOC_NUMCBT
;

-- 21
 CREATE OR REPLACE VIEW  VIEW_ASIENTOSORGPAG AS 
SELECT                    MOC_CODSUC,                    MOC_ORIGEN,                    MOC_DOCPAG,               MOC_ACTUAL,             
 SUM(MOC_MONTO) AS MOC_MONTO,         
 SUM(IF(MOC_MONTO>0,MOC_MONTO,0)) AS MOC_DEBE,         
 SUM(IF(MOC_MONTO<0,MOC_MONTO*-1,0)) AS MOC_HABER,      COUNT(*) AS MOC_COUNT      FROM 
 dpasientos                    WHERE MOC_ORIGEN="COM"                  
 GROUP BY MOC_CODSUC,MOC_ORIGEN,MOC_DOCPAG,MOC_ACTUAL             
 ORDER BY MOC_CODSUC,MOC_ORIGEN,MOC_DOCPAG,MOC_ACTUAL
;

-- 22
 CREATE OR REPLACE VIEW  VIEW_ASIENTOSORGREC AS 
SELECT                      MOC_CODSUC,                      MOC_ORIGEN,                      MOC_DOCPAG,                 MOC_ACTUAL,               
 SUM(MOC_MONTO) AS MOC_MONTO,           
 SUM(IF(MOC_MONTO>0,MOC_MONTO,0)) AS MOC_DEBE,           
 SUM(IF(MOC_MONTO<0,MOC_MONTO*-1,0)) AS MOC_HABER,        COUNT(*) AS MOC_COUNT        FROM 
 dpasientos                      WHERE MOC_ORIGEN="VTA"                    
 GROUP BY MOC_CODSUC,MOC_ORIGEN,MOC_DOCPAG,MOC_ACTUAL               
 ORDER BY MOC_CODSUC,MOC_ORIGEN,MOC_DOCPAG,MOC_ACTUAL
;

-- 23
 CREATE OR REPLACE VIEW  VIEW_ASIENTOSXCODINT AS 
SELECT AST_CODINT AS AIN_CODINT, COUNT(*)   AS AIN_CANTID,
 SUM(IF(MOC_CUENTA="Indefinida",1,0)) AS AIN_CANIND  FROM 
 DPASIENTOS 
 INNER JOIN DPASIENTOSTIP    ON MOC_ORIGEN=AST_APLORG AND MOC_TIPO=AST_TIPDOC AND MOC_TIPTRA=AST_TIPTRA AND MOC_TIPASI=AST_TIPO 
 GROUP BY AST_CODINT;

-- 24
 CREATE OR REPLACE VIEW  VIEW_DPEVENTOS AS 
SELECT    MOV_CODCTA AS EVE_CODCTA,                  MOV_FECHA  AS EVE_FECHA                   FROM 
    DPMOVINV                  WHERE MOV_TIPDOC="EVE" AND MOV_TIPO="C" AND MOV_LISTA="S"         
 GROUP BY MOV_CODIGO,MOV_CODCTA
;

-- 25
 CREATE OR REPLACE VIEW  VIEW_DPAUXILIAR AS 
SELECT MOC_ORIGEN AS AUX_ORIGEN,MOC_CODAUX AS AUX_CODAUX,  CASE   WHEN MOC_ORIGEN="VTA" AND LENGTH(MOC_CODAUX)<=10 THEN CLI_NOMBRE   WHEN MOC_ORIGEN="COM" AND LENGTH(MOC_CODAUX)<=10 THEN PRO_NOMBRE   WHEN MOC_ORIGEN="ACT" THEN ATV_DESCRI   WHEN (MOC_ORIGEN="COM" OR MOC_ORIGEN="VTA" OR MOC_ORIGEN="TRA" OR MOC_ORIGEN="BCO") AND LENGTH(MOC_CODAUX)>10 THEN BAN_NOMBRE   WHEN MOC_ORIGEN="INV" THEN INV_DESCRI  ELSE    SPACE(200)  END  AS AUX_NOMBRE,  MIN(MOC_FECHA) AS AUX_DESDE,  MAX(MOC_FECHA) AS AUX_HASTA,  COUNT(*)  AS AUX_CANTID  FROM 
 dpasientos  LEFT JOIN dpclientes  ON MOC_ORIGEN="VTA" AND MOC_CODAUX=CLI_CODIGO  LEFT JOIN dpproveedor ON MOC_ORIGEN="COM" AND MOC_CODAUX=PRO_CODIGO  LEFT JOIN dpactivos   ON MOC_ORIGEN="ACT" AND MOC_CODAUX=ATV_CODIGO  LEFT JOIN DPCTABANCO  ON (MOC_ORIGEN="BCO" OR MOC_ORIGEN="TRA" OR MOC_ORIGEN="VTA" OR MOC_ORIGEN="COM") AND MOC_CODAUX=BCO_CTABAN AND LENGTH(MOC_CODAUX)>10  LEFT JOIN dpbancos    ON BAN_CODIGO=BCO_CODIGO  LEFT JOIN dpinv       ON MOC_ORIGEN="INV" AND MOC_CODAUX=INV_CODIGO  WHERE MOC_CODAUX<>""  
 GROUP BY MOC_ORIGEN,MOC_CODAUX;

-- 26
 CREATE OR REPLACE VIEW  VIEW_DOCCLIDOCYPAG AS 
SELECT                                                 DOC_CODSUC AS CXD_CODSUC,                                                DOC_TIPDOC AS CXD_TIPDOC,                                                DOC_NUMERO AS CXD_NUMERO,                                               DOC_CODIGO AS CXD_CODIGO,                                    MAX(DOC_FCHVEN)       AS CXD_FCHMAX,                                    DOC_FECHA             AS CXD_FECHA,                                 
 SUM(DOC_NETO*DOC_CXC) AS CXD_NETO,               
 SUM(IF(DOC_TIPTRA="D",DOC_NETO,0))   AS CXD_MTODOC,                                               
 SUM(IF(DOC_TIPTRA="P",DOC_NETO,0))   AS CXD_MTOPAG,    AVG(IF(DOC_TIPTRA="D",DOC_VALCAM,0)) AS CXD_VALCAM                                                FROM 
 DPDOCCLI                                                WHERE DOC_CXC<>0 AND DOC_ACT=1                                               
 GROUP BY DOC_CODSUC,DOC_TIPDOC,DOC_NUMERO                                      
 ORDER BY DOC_CODSUC,DOC_TIPDOC,DOC_NUMERO
;

-- 27
 CREATE OR REPLACE VIEW  VIEW_CAJACXC AS 
SELECT                             CAJ_CODSUC AS CCC_CODSUC,                            CAJ_CODCAJ AS CCC_CODCAJ,                            CLI_RIF    AS CCC_RIF,                            CAJ_TIPO   AS CCC_TIPO  ,                            CAJ_NUMERO AS CCC_NUMERO,                           
 SUM(CAJ_MONTO*CAJ_DEBCRE) AS CCC_MONTO                            FROM 
 DPCAJAMOV                           
 INNER JOIN DPCAJAINST   ON DPCAJAMOV.CAJ_TIPO=ICJ_CODIGO AND ICJ_REQNUM=1 AND ICJ_INGRES=1 AND ICJ_EGRESO=1                           
 INNER JOIN DPRECIBOSCLI ON CAJ_CODSUC=REC_CODSUC AND CAJ_DOCASO=REC_NUMERO AND REC_ACT=1                          
 INNER JOIN DPCLIENTES   ON REC_CODIGO=CLI_CODIGO                            WHERE CAJ_ORIGEN="REC" AND CAJ_NUMERO<>"" AND CAJ_ACT=1                           
 GROUP BY CAJ_CODSUC,CAJ_CODCAJ,CLI_RIF,CAJ_TIPO,CAJ_NUMERO                           
 ORDER BY CAJ_CODSUC,CAJ_CODCAJ,CLI_RIF,CAJ_TIPO,CAJ_NUMERO
;

-- 28
 CREATE OR REPLACE VIEW  VIEW_DPDIARIO_BIMEST AS 
SELECT DIA_ANO AS FCH_ANO,DIA_BIMEST AS FCH_BIMEST,MIN(DIA_FECHA) AS FCH_DESDE,MAX(DIA_FECHA) AS FCH_HASTA   FROM 
   DPDIARIO               
 GROUP BY DIA_ANO,DIA_BIMEST               
 ORDER BY DIA_ANO,DIA_BIMEST
;

-- 29
 CREATE OR REPLACE VIEW  VIEW_CALMOVINV AS 
SELECT                    MOV_FECHA  AS CMI_FCHMOV,                   DIA_FECHA  AS CMI_FCHDIA,                   MOV_CODPER AS CMI_CODIGO,                   DAYOFWEEK(DIA_FECHA) AS CMI_DOW,                   MIH_CLASIF AS CMI_CLASIF,                                          MOV_HORA   AS CMI_HORA,                   IF(CLI_CODIGO IS NULL,MOV_CODPER,CLI_NOMBRE)                    AS CMI_CODPER                                                     FROM 
       DPDIARIO                                                      LEFT JOIN DPMOVINV_TIN ON DIA_FECHA = MOV_FECHA AND MOV_INVACT=1 AND (MOV_TIPDOC = "INT" OR MOV_TIPDOC = "ORS" )                                      LEFT JOIN DPMOVINVHORA ON DIA_FECHA = MIH_FECHA AND (MIH_TIPDOC = "ORS" OR MIH_TIPDOC = "INT" )                                               LEFT JOIN DPPERSONAL ON MOV_CODPER = PER_CODIGO AND PER_SEMANA = 1                             LEFT JOIN DPCLIENTES ON MOV_CODCTA = CLI_CODIGO                     WHERE MOV_CODIGO IS NOT NULL                                     
 ORDER BY MOV_CODPER,MOV_FECHA
;

-- 30
 CREATE OR REPLACE VIEW  VIEW_DPDIARIO_CUATRI AS 
SELECT DIA_ANO AS FCH_ANO,DIA_CUATRI AS FCH_CUATRI,MIN(DIA_FECHA) AS FCH_DESDE,MAX(DIA_FECHA) AS FCH_HASTA   FROM 
   DPDIARIO             
 GROUP BY DIA_ANO,DIA_CUATRI             
 ORDER BY DIA_ANO,DIA_CUATRI
;

-- 31
 CREATE OR REPLACE VIEW  VIEW_DPDIARIO_FECHA AS 
SELECT DIA_ANO AS FCH_ANO,DIA_FECHA AS FCH_DESDE,DIA_FECHA AS FCH_HASTA   FROM 
   DPDIARIO       
 GROUP BY DIA_FECHA       
 ORDER BY DIA_FECHA
;

-- 32
 CREATE OR REPLACE VIEW  VIEW_DPDIARIO_EJERC AS 
SELECT DIA_ANO AS FCH_ANO,EJE_DESDE AS FCH_DESDE,EJE_HASTA AS FCH_HASTA   FROM 
   DPEJERCICIOS       
 INNER JOIN DPDIARIO ON DIA_FECHA=EJE_DESDE       
 GROUP BY EJE_DESDE       
 ORDER BY EJE_DESDE
;

-- 33
 CREATE OR REPLACE VIEW  VIEW_DPDIARIO_SEMANA AS 
SELECT DIA_ANO AS FCH_ANO,DIA_SEMANA AS FCH_SEMANA,MIN(DIA_FECHA) AS FCH_DESDE,MAX(DIA_FECHA) AS FCH_HASTA   FROM 
   DPDIARIO         
 GROUP BY DIA_ANO,DIA_SEMANA         
 ORDER BY DIA_ANO,DIA_SEMANA
;

-- 34
 CREATE OR REPLACE VIEW  VIEW_DPDIARIO_SEMEST AS 
SELECT DIA_ANO AS FCH_ANO,DIA_SEMEST AS FCH_SEMEST,MIN(DIA_FECHA) AS FCH_DESDE,MAX(DIA_FECHA) AS FCH_HASTA   FROM 
   DPDIARIO                   
 GROUP BY DIA_ANO,DIA_SEMEST                   
 ORDER BY DIA_ANO,DIA_SEMEST
;

-- 35
 CREATE OR REPLACE VIEW  VIEW_DPDIARIO_TRIMES AS 
SELECT DIA_ANO AS FCH_ANO,DIA_TRIMES AS FCH_TRIMES,MIN(DIA_FECHA) AS FCH_DESDE,MAX(DIA_FECHA) AS FCH_HASTA   FROM 
   DPDIARIO                   
 GROUP BY DIA_ANO,DIA_TRIMES                   
 ORDER BY DIA_ANO,DIA_TRIMES
;

-- 36
 CREATE OR REPLACE VIEW  VIEW_DPCALF30 AS 
SELECT PLP_FECHA  AS F30_FECHA, PLP_FCHDEC AS F30_FCHDEC   FROM 
 dpdocproprog  WHERE PLP_TIPDOC="F30" 
 GROUP BY PLP_FECHA,PLP_FCHDEC 
 ORDER BY PLP_FECHA;

-- 37
 CREATE OR REPLACE VIEW  VIEW_UNDMEDCXINV AS 
SELECT     IME_UNDMED AS PXU_UNDMED,    COUNT(*)   AS PXU_CANTID    FROM 
 DPINVMED   
 GROUP BY IME_UNDMED
;

-- 38
 CREATE OR REPLACE VIEW  VIEW_DPCBTCANT AS 
SELECT    CBT_CODSUC AS CCE_CODSUC,    CBT_NUMEJE AS CCE_NUMEJE,    COUNT(*)   AS CCE_CUANTOS     FROM 
  DPCBTE   
 GROUP BY CBT_CODSUC,CBT_NUMEJE   
 ORDER BY CBT_CODSUC,CBT_NUMEJE
;

-- 39
 CREATE OR REPLACE VIEW  VIEW_DPSERIEFISCALDOC AS 
SELECT DOC_CODSUC AS CDS_CODSUC, DOC_SERFIS      AS CDS_LETRA,         MIN(DOC_FECHA ) AS CDS_DESDE,     MAX(DOC_FECHA ) AS CDS_HASTA,     CAST(MAX(DOC_GIRNUM) AS UNSIGNED) AS CDS_ZETA ,     COUNT(*)        AS CDS_CANTID     FROM 
 DPDOCCLI  
 INNER JOIN DPTIPDOCCLI   ON DOC_TIPDOC=TDC_TIPO AND TDC_LIBVTA=1  LEFT  JOIN DPSERIEFISCAL ON DOC_SERFIS=SFI_LETRA 
 GROUP BY DOC_CODSUC,DOC_SERFIS 
 ORDER BY DOC_CODSUC,DOC_SERFIS;

-- 40
 CREATE OR REPLACE VIEW  VIEW_DPINV_MAR_GRU AS 
SELECT INV_CODMAR AS MYG_CODMAR,INV_GRUPO  AS MYG_CODGRU, COUNT(*)  AS MYG_CANTID  FROM 
 dpinv 
 GROUP BY INV_CODMAR,INV_GRUPO;

-- 41
 CREATE OR REPLACE VIEW  VIEW_DPINV_GRU_MAR AS 
SELECT INV_CODMAR AS GYM_CODMAR,INV_GRUPO  AS GYM_CODGRU, COUNT(*)  AS GYM_CANTID  FROM 
 dpinv 
 GROUP BY INV_CODMAR,INV_GRUPO;

-- 42
 CREATE OR REPLACE VIEW  VIEW_PROCATCANT AS 
SELECT     CPP_CODIGO     AS CRP_CODIGO,  MIN(CPP_FECHA) AS CRP_FCHMIN,      MAX(CPP_FECHA) AS CRP_FCHMAX,    COUNT(*)       AS CRP_CANTID    FROM 
 DPPROVCATPRECIO   
 GROUP BY CPP_CODIGO
;

-- 43
 CREATE OR REPLACE VIEW  VIEW_DPCLIENTEXSUC AS 
SELECT SDC_CODCLI,COUNT(*) AS SDC_CANTID FROM 
 dpclientessuc
 GROUP BY SDC_CODCLI
 ORDER BY SDC_CODCLI;

-- 44
 CREATE OR REPLACE VIEW  VIEW_UBICACFISXALM AS 
SELECT     UBI_CODSUC AS UXA_CODSUC,      UBI_CODALM AS UXA_CODALM,      COUNT(*)   AS UXA_CANTID      FROM 
 DPUBICACFIS      LEFT JOIN DPALMACEN ON ALM_CODIGO=UBI_CODALM     
 GROUP BY UBI_CODSUC,UBI_CODALM     
 ORDER BY UBI_CODSUC,UBI_CODALM
;

-- 45
 CREATE OR REPLACE VIEW  VIEW_CLICATRANGODIAS AS 
SELECT         DOC_CODSUC      AS CAT_CODSUC,        DOC_TIPDOC      AS CAT_TIPDOC,        DOC_CODIGO      AS CAT_CODIGO,        MAX(DOC_FECHA)  AS CAT_MAXFCH,       
 SUM(DOC_BASNET*DOC_CXC) AS CAT_MTOBAS        FROM 
 DPDOCCLI        WHERE DOC_CXC<>0 AND DOC_ACT=1 AND DOC_TIPTRA="D"       
 GROUP BY DOC_CODSUC,DOC_TIPDOC,DOC_CODIGO       
 ORDER BY DOC_CODSUC,DOC_TIPDOC,DOC_CODIGO
;

-- 46
 CREATE OR REPLACE VIEW  VIEW_CATEGORIA AS 
SELECT GRU_CODIGO AS id, GRU_DESCRI AS categoria FROM 
 dpgru
 ORDER BY GRU_CODIGO;

-- 47
 CREATE OR REPLACE VIEW  VIEW_CLICATSUMVTA AS 
SELECT    DOC_CODSUC AS CTV_CODSUC,   DOC_CODIGO AS CTV_CODIGO,   SUM(DOC_BASNET*DOC_CXC) AS  CTV_MONTO    FROM  DPDOCCLI    WHERE LEFT(DATE_SUB(NOW(), INTERVAL 60  DAY) ,10)>=DOC_FECHA AND DOC_TIPTRA="D" AND DOC_ACT=1 AND DOC_CXC<>0    GROUP BY DOC_CODSUC,DOC_CODIGO    ORDER BY DOC_CODSUC,DOC_CODIGO;

-- 48
 CREATE OR REPLACE VIEW  VIEW_DPCBTEPAGOPRODOC AS 
SELECT           DOC_CODSUC,      DOC_PAGNUM,         
 SUM(DOC_NETO*IF(DOC_TIPDOC="ANT" AND DOC_TIPTRA="D",1,DOC_CXP*-1)) AS DOC_NETO                FROM 
 DPDOCPRO         
 INNER JOIN DPCBTEPAGO  ON DOC_CODSUC=PAG_CODSUC AND DOC_PAGNUM=PAG_NUMERO      WHERE ((DOC_TIPDOC="ANT" AND DOC_TIPTRA="D") OR (DOC_TIPTRA="P")) AND DOC_ACT=1        
 GROUP BY DOC_CODSUC,DOC_PAGNUM     
 ORDER BY DOC_CODSUC,DOC_PAGNUM
;

-- 49
 CREATE OR REPLACE VIEW  VIEW_ESTORGCLIXPRO AS 
SELECT     EPC_CODPRO AS EOR_CODPRO,    COUNT(*) AS EOR_CANCLI    FROM 
    dpestructorgprocli    WHERE EPC_ACTIVO=1   
 GROUP BY EPC_CODPRO
;

-- 50
 CREATE OR REPLACE VIEW  VIEW_CLIENTES AS 
SELECT CLI_CODIGO AS id,CLI_RIF  AS documento,CLI_NOMBRE AS nombre,CLI_EMAIL  AS email,CLI_TEL1   AS Telefono, CONCAT(CLI_DIR1,CLI_DIR2,CLI_DIR3) AS direccion, "0000-00-00" AS fecha_nacimiento, 0 AS compras, "0000-00-00" AS ultima_compra,"0000-00-00" AS fecha FROM 
 dpclientes;

-- 51
 CREATE OR REPLACE VIEW  VIEW_TABMONXCLI AS 
SELECT CLI_CODMON,COUNT(*) FROM 
 dpclientes
 GROUP BY CLI_CODMON
 ORDER BY CLI_CODMON;

-- 52
 CREATE OR REPLACE VIEW  VIEW_RESCLIXSUC AS 
SELECT     RXS_CLAVE   AS RXC_CODIGO,    RXS_CODSUC  AS RXC_CODSUC    FROM 
 DPTABXSUC       WHERE RXS_TABLA ="DPCLIENTES"  AND RXS_CLAVE<>"" AND RXS_SELECT=1     
 ORDER BY RXS_CLAVE
;

-- 53
 CREATE OR REPLACE VIEW  VIEW_DPCODINTEGRA AS 
SELECT  CIN_CODIGO,  CIC_CUENTA AS CIN_CODCTA, CIN_ABREVI,  CIN_ASIABR ,  CIC_CTAMOD AS CIN_CTAMOD FROM 
 dpcodintegra  LEFT JOIN DPCODINTEGRA_CTA         ON CIN_CODIGO=CIC_CODIGO 
 ORDER BY CIC_CODIGO,CIN_CTAMOD
;

-- 54
 CREATE OR REPLACE VIEW  VIEW_DPDOCPROCTACOM AS 
SELECT     DOC_CODSUC AS CDC_CODSUC,    DOC_PAGNUM AS CDC_PAGNUM,    LEFT(GROUP_CONCAT(CONCAT(CCD_TIPDOC,",",CCD_NUMERO,",",CCD_DESCRI)),400) AS CDC_COMENT    FROM 
 DPDOCPRO   
 INNER JOIN DPDOCPROCTA ON CCD_CODSUC=DOC_CODSUC AND CCD_TIPDOC=DOC_TIPDOC AND CCD_CODIGO=DOC_CODIGO AND CCD_NUMERO=DOC_NUMERO AND CCD_TIPTRA="D"    WHERE DOC_ACT=1 AND DOC_TIPTRA="P"   
 GROUP BY DOC_CODSUC,DOC_PAGNUM   
 ORDER BY DOC_CODSUC,DOC_PAGNUM
;

-- 55
 CREATE OR REPLACE VIEW  VIEW_INVCOMPO AS 
SELECT           CPT_CODIGO AS INC_CODIGO,     
 SUM(CPT_CANTID*INV_COSFOB) AS INC_COSFOB,         COUNT(*)   AS INC_CANTID          FROM 
 DPCOMPONENTES      
 INNER JOIN DPINV ON CPT_COMPON=INV_CODIGO       
 GROUP BY CPT_CODIGO
;

-- 56
 CREATE OR REPLACE VIEW  VIEW_DPCBTEDIA AS 
SELECT CBT_CODSUC,CBT_FECHA,CBT_ACTUAL,COUNT(*) AS CBT_CANT  FROM 
  DPCBTE 
 GROUP BY CBT_CODSUC,CBT_FECHA,CBT_ACTUAL 
 ORDER BY CBT_CODSUC,CBT_FECHA,CBT_ACTUAL;

-- 57
 CREATE OR REPLACE VIEW  VIEW_DPCBTESLD AS 
SELECT  MOC_CODSUC     AS CBT_CODSUC, MOC_ACTUAL     AS CBT_ACTUAL, MOC_NUMCBT     AS CBT_NUMERO, MOC_FECHA      AS CBT_FECHA ,
 SUM(MOC_MONTO) AS CBT_SALDO , COUNT(*)       AS CBT_CANTID FROM 
 dpasientos  WHERE MOC_ACTUAL="S" OR MOC_ACTUAL="C" OR MOC_ACTUAL="F" OR MOC_ACTUAL="A" 
 GROUP BY MOC_CODSUC,MOC_ACTUAL,MOC_NUMCBT,MOC_FECHA  HAVING CBT_SALDO<>0 
 ORDER BY MOC_CODSUC,MOC_ACTUAL,MOC_NUMCBT,MOC_FECHA;

-- 58
 CREATE OR REPLACE VIEW  VIEW_DPORGCBTE AS 
SELECT  CBT_ORGPLA AS OPC_REGPLA, CBT_CODSUC AS OPC_CODSUC,  CBT_NUMERO AS OPC_NUMERO,  CBT_FECHA  AS OPC_FECHA,   CBT_ACTUAL AS OPC_ACTUAL   FROM 
 dpcbte  WHERE CBT_ORGPLA IS NOT NULL AND CBT_ORGPLA<>"";

-- 59
 CREATE OR REPLACE VIEW  VIEW_DPCBTEORG AS 
SELECT CBT_ACTUAL AS CBO_ACTUAL, CBT_CODSUC AS CBO_CODSUC,  CBT_NUMERO AS CBO_NUMERO,  CBT_FECHA  AS CBO_FECHA,   CBT_PERIOD AS CBO_PERIOD,  CONCAT(CBT_COMEN1," ",CBT_COMEN2) AS CBO_DESCRI,CBT_DEFCBT AS CBO_DEFCBT,CBT_FCHINI AS CBO_FCHINI,CBT_FCHFIN AS CBO_FCHFIN  FROM 
 dpcbte  WHERE CBT_PERIOD<>"Indefinida" 
 ORDER BY CBT_CODSUC,CBT_ACTUAL,CBT_NUMERO,CBT_FECHA
;

-- 60
 CREATE OR REPLACE VIEW  VIEW_DPCBTNUMPAR AS 
SELECT   MOC_CODSUC AS CNP_CODSUC, MOC_ACTUAL AS CNP_ACTUAL, MOC_NUMCBT AS CNP_NUMCBT, MOC_FECHA  AS CNP_FECHA ,
 SUM(IF(MOC_MONTO>0,MOC_MONTO,0))    AS CNP_DEBE ,
 SUM(IF(MOC_MONTO<0,MOC_MONTO*-1,0)) AS CNP_HABER,
 SUM(MOC_MONTO)                      AS CNP_MONTO, MOC_NUMPAR AS CNP_NUMPAR, COUNT(*)   AS CNP_CANTID  FROM 
 dpasientos 
 GROUP BY MOC_CODSUC,MOC_ACTUAL,MOC_NUMCBT,MOC_FECHA,MOC_NUMPAR 
 ORDER BY MOC_CODSUC,MOC_ACTUAL,MOC_NUMCBT,MOC_FECHA;

-- 61
 CREATE OR REPLACE VIEW  VIEW_COMPOINV AS 
SELECT       CPT_COMPON AS CIN_CODIGO,      CPT_CANTID*INV_COSFOB AS CIN_COSFOB,  COUNT(*)   AS CIN_CANTID  FROM 
 DPCOMPONENTES     
 INNER JOIN DPINV ON CPT_CODIGO=INV_CODIGO 
 GROUP BY CPT_COMPON
;

-- 62
 CREATE OR REPLACE VIEW  VIEW_MOVINVSERVANT AS 
SELECT      MOV_CODSUC, MOV_TIPDOC, MOV_DOCUME,
 SUM(IF(MOV_FCHVEN<MOV_FECHA              ,MOV_TOTAL,0)) AS MOV_TOTATR, 
 SUM(IF(MONTH(MOV_FCHVEN)=MONTH(MOV_FECHA),MOV_TOTAL,0)) AS MOV_TOTACT, 
 SUM(IF(MOV_FCHVEN>MOV_FECHA              ,MOV_TOTAL,0)) AS MOV_TOTANT, 
 SUM(MOV_TOTAL)                                          AS MOV_TOTAL  FROM 
 DPMOVINV 
 INNER JOIN dptipdoccli ON MOV_TIPDOC=TDC_TIPO AND TDC_CONTAB=1  WHERE MOV_APLORG="V" AND MOV_INVACT=1  
 GROUP BY MOV_CODSUC,MOV_TIPDOC,MOV_DOCUME 
 ORDER BY MOV_CODSUC,MOV_TIPDOC,MOV_DOCUME;

-- 63
 CREATE OR REPLACE VIEW  VIEW_CONCILDOCCOM AS 
SELECT   MOC_CODSUC AS ADC_CODSUC, MOC_TIPO   AS ADC_TIPDOC, MOC_CODAUX AS ADC_CODPRO, MOC_DOCUME AS ADC_DOCUME, MOC_ACTUAL AS ADC_ACTUAL, MOC_FECHA  AS ADC_FECHA, 
 SUM(IF(MOC_MONTO>0,MOC_MONTO*1,0)) AS ADC_DEBE,  
 SUM(IF(MOC_MONTO<0,MOC_MONTO*-1,0)) AS ADC_HABER  FROM 
 DPASIENTOS  WHERE    MOC_ORIGEN="COM" AND MOC_TIPTRA="D" 
 GROUP BY MOC_CODSUC,MOC_TIPO,MOC_CODAUX,MOC_DOCUME,MOC_FECHA 
 ORDER BY MOC_CODSUC,MOC_TIPO,MOC_CODAUX,MOC_DOCUME;

-- 64
 CREATE OR REPLACE VIEW  VIEW_INVCOSDIVMAX AS 
SELECT       MOV_CODSUC                      AS CDY_CODSUC,                    MOV_CODCTA                      AS CDY_CODPRO,                        MOV_CODIGO                      AS CDY_CODIGO,                        MAX(CONCAT(MOV_FECHA,MOV_HORA)) AS CDY_FCHHOR,                MAX(MOV_FECHA)                  AS CDY_FECHA,                        MOV_COSTO                       AS CDY_COSTO,                         MAX(MOV_COSTO/HMN_VALOR)        AS CDY_COSDIV,                        (MOV_CANTID * MOV_CONTAB * ( MOV_COSTO * IF(MOV_CONTAB=1, (100-MOV_DESCUE)/100 , 1 ))) AS CDY_TOTAL ,                         HMN_VALOR                       AS CDY_VALDIV                        FROM 
 DPMOVINV                         
 INNER JOIN DPHISMON ON HMN_CODIGO="USD" AND HMN_FECHA=MOV_FECHA                          WHERE MOV_APLORG="C" AND MOV_INVACT=1  AND MOV_CONTAB=1 AND HMN_VALOR>0                       
 GROUP BY MOV_CODSUC,MOV_CODCTA,MOV_CODIGO                       
 ORDER BY MOV_CODSUC,MOV_CODCTA,MOV_CODIGO,MOV_COSTO/HMN_VALOR
;

-- 65
 CREATE OR REPLACE VIEW  VIEW_INVCOSDIVMIN AS 
SELECT     MOV_CODSUC                       AS CDX_CODSUC,                       MOV_CODCTA                      AS CDX_CODPRO,                         MOV_CODIGO                      AS CDX_CODIGO,                         MIN(CONCAT(MOV_FECHA,MOV_HORA)) AS CDX_FCHHOR,               MIN(MOV_FECHA)                  AS CDX_FECHA,                         MOV_COSTO                       AS CDX_COSTO,                          MIN(MOV_COSTO/HMN_VALOR)         AS CDX_COSDIV,                        (MOV_CANTID * MOV_CONTAB * ( MOV_COSTO * IF(MOV_CONTAB=1, (100-MOV_DESCUE)/100 , 1 ))) AS CDX_TOTAL ,                          HMN_VALOR                       AS CDX_VALDIV                         FROM 
 DPMOVINV                          
 INNER JOIN DPHISMON ON HMN_CODIGO="USD" AND HMN_FECHA=MOV_FECHA                           WHERE MOV_APLORG="C" AND MOV_INVACT=1  AND MOV_CONTAB=1 AND HMN_VALOR>0                        
 GROUP BY MOV_CODSUC,MOV_CODCTA,MOV_CODIGO                        
 ORDER BY MOV_CODSUC,MOV_CODCTA,MOV_CODIGO,MOV_COSTO/HMN_VALOR                    DESC
;

-- 66
 CREATE OR REPLACE VIEW  VIEW_CAJACXP AS 
SELECT                                     CAJ_CODSUC AS CCP_CODSUC,                                    CAJ_CODCAJ AS CCP_CODCAJ,                                    PRO_RIF    AS CCP_RIF,                                    CAJ_TIPO   AS CCP_TIPO,                                    CAJ_NUMERO AS CCP_NUMERO,                                   
 SUM(CAJ_MONTO*CAJ_DEBCRE) AS CCP_MONTO                                    FROM 
 DPCAJAMOV                                   
 INNER JOIN DPCAJAINST   ON DPCAJAMOV.CAJ_TIPO=ICJ_CODIGO AND ICJ_REQNUM=1 AND ICJ_INGRES=1 AND ICJ_EGRESO=1                                   
 INNER JOIN DPCBTEPAGO   ON CAJ_CODSUC=PAG_CODSUC AND CAJ_DOCASO=PAG_NUMERO AND PAG_ACT=1                                  
 INNER JOIN DPPROVEEDOR  ON PAG_CODIGO=PRO_CODIGO                                    WHERE CAJ_ORIGEN="PAG" AND CAJ_NUMERO<>"" AND CAJ_ACT=1                                   
 GROUP BY CAJ_CODSUC,CAJ_CODCAJ,PRO_RIF,CAJ_TIPO,CAJ_NUMERO                                   
 ORDER BY CAJ_CODSUC,CAJ_CODCAJ,PRO_RIF,CAJ_TIPO,CAJ_NUMERO
;

-- 67
 CREATE OR REPLACE VIEW  VIEW_ACTCTA_ACT AS 
SELECT CIC_CTAMOD AS ACT_CTAMOD,CIC_CODIGO AS ACT_CODACT,CIC_CUENTA AS ACT_CTAACT FROM 
 DPACTIVOS_CTA  WHERE CIC_CODINT="CTAACT";

-- 68
 CREATE OR REPLACE VIEW  VIEW_ACTCTA_ACU AS 
SELECT CIC_CTAMOD AS ACT_CTAMOD,CIC_CODIGO AS ACT_CODACT,CIC_CUENTA AS ACT_CTAACU FROM 
 DPACTIVOS_CTA  WHERE CIC_CODINT="CTAACU";

-- 69
 CREATE OR REPLACE VIEW  VIEW_ACTCTA_DEP AS 
SELECT CIC_CTAMOD AS ACT_CTAMOD,CIC_CODIGO AS ACT_CODACT,CIC_CUENTA AS ACT_CTADEP FROM 
 DPACTIVOS_CTA  WHERE CIC_CODINT="CTADEP";

-- 70
 CREATE OR REPLACE VIEW  VIEW_ACTCTA_REV AS 
SELECT CIC_CTAMOD AS ACT_CTAMOD,CIC_CODIGO AS ACT_CODACT,CIC_CUENTA AS ACT_CTAREV FROM 
 DPACTIVOS_CTA  WHERE CIC_CODINT="CTAREV";

-- 71
 CREATE OR REPLACE VIEW  VIEW_DPIVATIPCTACOM AS 
SELECT  CIC_CODIGO AS TCC_CODIGO, CIC_CUENTA AS TCC_CTACRE, CTA_DESCRI AS TCC_DESCRI, CIC_CTAMOD AS TCC_CTAMOD  FROM 
 DPIVATIP_CTA  LEFT JOIN dpcta ON CIC_CTAMOD=CTA_CODMOD AND CIC_CUENTA=CTA_CODIGO  WHERE CIC_CODINT="CTACOM" 
 GROUP BY CIC_CODIGO 
 ORDER BY CIC_CODIGO;

-- 72
 CREATE OR REPLACE VIEW  VIEW_DPIVATIPCTAVTA AS 
SELECT  CIC_CODIGO AS TCD_CODIGO, CIC_CUENTA AS TCD_CTADEB, CTA_DESCRI AS TCD_DESCRI, CIC_CTAMOD AS TCD_CTAMOD  FROM 
 DPIVATIP_CTA  LEFT JOIN dpcta ON CIC_CTAMOD=CTA_CODMOD AND CIC_CUENTA=CTA_CODIGO  WHERE CIC_CODINT="CTAVTA" 
 GROUP BY CIC_CODIGO 
 ORDER BY CIC_CODIGO;

-- 73
 CREATE OR REPLACE VIEW  VIEW_DPCTAINVTRA AS 
SELECT   CIC_CUENTA AS CCT_CUENTA,  CTA_DESCRI AS CCT_DESCRI  FROM 
 DPINVTRAN_CTA  
 INNER JOIN DPCTA ON CIC_CUENTA=CTA_CODIGO 
 ORDER BY CIC_CUENTA
;

-- 74
 CREATE OR REPLACE VIEW  VIEW_DPCTAEEFF AS 
SELECT    CTA_CODMOD AS CTE_CODMOD,    CTA_CODIGO AS CTE_CUENTA  FROM 
 DPCTA   
 INNER JOIN DPCTAUSO ON LEFT(CTA_CODIGO,1)=CUT_CODIGO    WHERE LEFT(CUT_CODUSO,1)="E" AND    LEFT(CTA_CODIGO,LENGTH(CUT_CODIGO))=CUT_CODIGO
 ORDER BY CTA_CODMOD,CTA_CODIGO
;

-- 75
 CREATE OR REPLACE VIEW  VIEW_DPCTABANCO AS 
SELECT BCO_CODIGO AS CBC_CODIGO, COUNT(*)   AS CBC_CUANTOS FROM 
  dpctabanco
 GROUP BY BCO_CODIGO;

-- 76
 CREATE OR REPLACE VIEW  VIEW_DPCTAAXI AS 
SELECT MOC_CODSUC AS CTA_CODSUC,MOC_CTAMOD AS CTA_CODMOD, MOC_CUENTA AS CTA_CODIGO,CTA_DESCRI,CTA_PROPIE FROM 
 dpasientos 
 INNER JOIN dpcta ON MOC_CTAMOD=CTA_CODMOD AND MOC_CUENTA=CTA_CODIGO  AND (CTA_PROPIE="Moneda Extranjera" OR CTA_PROPIE="Patrimonio" OR CTA_PROPIE="Monetarias")
 GROUP BY MOC_CTAMOD,MOC_CUENTA;

-- 77
 CREATE OR REPLACE VIEW  VIEW_DPPROVEEDORCTA AS 
SELECT   CIC_CODIGO AS PRO_CODIGO,  CIC_CUENTA AS PRO_CUENTA,  CIC_CTAMOD AS PRO_CTAMOD  FROM 
 DPPROVEEDOR_CTA
;

-- 78
 CREATE OR REPLACE VIEW  VIEW_DPCLIENTESCTA AS 
SELECT       CIC_CODIGO AS CLI_CODIGO,      CIC_CUENTA AS CLI_CUENTA,      CIC_CTAMOD AS CLI_CTAMOD      FROM 
 DPCLIENTES_CTA
;

-- 79
 CREATE OR REPLACE VIEW  VIEW_NMCONCEPTOSCTA_DEB AS 
SELECT  CIC_CUENTA AS CDB_CUENTA,  CIC_CTAMOD AS CDB_CTAMOD,  CTA_DESCRI AS CDB_DESCRI   FROM 
 NMCONCEPTOS_CTA 
 INNER JOIN dpcta ON CIC_CUENTA=CTA_CODIGO AND CTA_CODMOD=CIC_CTAMOD  WHERE CIC_CODINT="CUENTA";

-- 80
 CREATE OR REPLACE VIEW  VIEW_NMCONCEPTOSCTA_HAB AS 
SELECT  CIC_CUENTA AS CCR_CUENTA,  CIC_CTAMOD AS CCR_CTAMOD,  CTA_DESCRI AS CCR_DESCRI   FROM 
 NMCONCEPTOS_CTA 
 INNER JOIN dpcta ON CIC_CUENTA=CTA_CODIGO AND CTA_CODMOD=CIC_CTAMOD  WHERE CIC_CODINT="CTACON";

-- 81
 CREATE OR REPLACE VIEW  VIEW_DPCLIENTECTA_CANT AS 
SELECT         CXC_CODMOD,        CXC_TIPDOC,          COUNT(*) AS CXC_CUANTOS          FROM 
 DPCLIENTECTA         
 GROUP BY CXC_CODMOD,CXC_TIPDOC
;

-- 82
 CREATE OR REPLACE VIEW  VIEW_DPCTARESULTADO AS 
SELECT            CTA_CODMOD AS CTR_CODMOD,            CTA_CODIGO AS CTR_CUENTA          FROM 
 DPCTA           
 INNER JOIN DPCTAUSO ON LEFT(CTA_CODIGO,1)=CUT_CODIGO            WHERE LEFT(CUT_CODUSO,1)="R" AND LEFT(CTA_CODIGO,LENGTH(CUT_CODIGO))=CUT_CODIGO           
 ORDER BY CTA_CODMOD,CTA_CODIGO
;

-- 83
 CREATE OR REPLACE VIEW  VIEW_EPED_CXC AS 
SELECT  DOC_TIPDOC as tipodoc,                        CLI_CODIGO as codigo,                        	DOC_NUMERO AS documento,                       	CLI_CODIGO as codcliente,                      	DOC_FECHA as emision,                      	dpdoccli.DOC_FCHVEN as vence,                             
 SUM(DOC_BASNET*DOC_CXC) AS CXC_BASNET,                                                	SUM(DOC_MTOIVA*DOC_CXC) AS totimpuest,                                                	SUM(DOC_CXC*DOC_NETO)   AS totalfinal,                      	IF(DOC_TIPTRA="P",SUM(DOC_NETO),0) AS totpagos,                      	DOC_CODVEN AS vendedor		                      FROM 
 DPDOCCLI                     
 INNER JOIN DPCLIENTES ON DOC_CODIGO=CLI_CODIGO             
 INNER JOIN DPVENDEDOR ON CLI_CODVEN=VEN_CODIGO AND VEN_EMANAG=1                                               WHERE DOC_ACT=1 AND DOC_CXC<>0                
 GROUP BY DOC_CODIGO,CLI_NOMBRE                                                 HAVING totalfinal<>0         
 ORDER BY vendedor
;

-- 84
 CREATE OR REPLACE VIEW  VIEW_CXCCLIXSUC AS 
SELECT                 DOC_CODSUC AS CXC_CODSUC,                DOC_CODIGO AS CXC_CODIGO,                                            CLI_NOMBRE AS CXC_NOMBRE,                                           
 SUM(DOC_BASNET*DOC_CXC) AS CXC_BASNET,                                           
 SUM(DOC_MTOIVA*DOC_CXC) AS CXC_MTOIVA,                                           
 SUM(DOC_CXC*DOC_NETO)   AS CXC_NETO                                     FROM 
  DPCLISLD  
 INNER JOIN DPDOCCLI   ON DOC_CODSUC=SLD_CODSUC AND DOC_CODIGO=SLD_CODIGO                                          
 INNER JOIN DPCLIENTES ON DOC_CODIGO=CLI_CODIGO                                             WHERE DOC_ACT=1 AND DOC_CXC<>0                                           
 GROUP BY DOC_CODSUC,DOC_CODIGO,CLI_NOMBRE                                             HAVING
 SUM(DOC_CXC*DOC_NETO)<>0           
 ORDER BY DOC_CODSUC,DOC_CODIGO,CLI_NOMBRE
;

-- 85
 CREATE OR REPLACE VIEW  VIEW_CXCXCLI AS 
SELECT   SLD_CODIGO AS CXC_CODIGO,                                    CLI_NOMBRE AS CXC_NOMBRE, 
 SUM(SLD_SALDO) AS CXC_NETO  FROM 
 DPCLISLD       
 INNER JOIN DPCLIENTES ON CLI_CODIGO=SLD_CODIGO       WHERE SLD_SALDO<>0    
 GROUP BY SLD_CODIGO       ;

-- 86
 CREATE OR REPLACE VIEW  VIEW_DPDOCPROCXP AS 
SELECT DOC_CODSUC AS CXP_CODSUC,                 DOC_TIPDOC AS CXP_TIPDOC,                 DOC_CODIGO AS CXP_CODIGO,                 DOC_NUMERO AS CXP_NUMERO,                 IF(DOC_TIPTRA="D",SUM(DOC_NETO*DOC_CXP  ) ,0) AS CXP_DEBE,             IF(DOC_TIPTRA="P",SUM(DOC_NETO*DOC_CXP*-1),0) AS CXP_HABER,            
 SUM(DOC_NETO*DOC_CXP  ) AS CXP_SALDO       FROM 
  DPDOCPRO            WHERE DOC_CXP<>0 AND DOC_ACT=1              
 GROUP BY DOC_CODSUC,DOC_TIPDOC,DOC_CODIGO,DOC_NUMERO          HAVING
 SUM(DOC_NETO*DOC_CXP)<>0         
 ORDER BY DOC_CODSUC,DOC_TIPDOC,DOC_CODIGO,DOC_NUMERO
;

-- 87
 CREATE OR REPLACE VIEW  VIEW_DOCCLICXCDIV AS 
SELECT DOC_CODSUC AS CXD_CODSUC,DOC_TIPDOC AS CXD_TIPDOC,DOC_NUMERO AS CXD_NUMERO,  DOC_CODIGO AS CXD_CODIGO,  MAX(DOC_FCHVEN) AS CXD_FCHMAX, MIN(DOC_FECHA)  AS CXD_FECHA, 
 SUM(ROUND((DOC_NETO+IF(DOC_TIPTRA="D",DOC_MTOCOM,0))/DOC_VALCAM,2)*DOC_CXC) AS CXD_CXCDIV, 
 SUM(IF(DOC_TIPTRA="D",DOC_NETO,0)) AS CXD_MTODOC,
 SUM(DOC_NETO*DOC_CXC) AS CXD_NETO,
 SUM(IF(DOC_TIPTRA="P",DOC_NETO,0)) AS CXD_MTOPAG, 
 SUM(IF(DOC_TIPTRA="P",ROUND((DOC_NETO+DOC_MTOCOM)/DOC_VALCAM,2),0)) AS CXD_PAGDIV,  COUNT(*) AS CXD_CANDOC, 
 SUM(DOC_NETO*DOC_CXC) AS CXD_SALDO  FROM 
 dpdoccli  WHERE DOC_CXC<>0 AND DOC_ACT=1 AND DOC_VALCAM>=1 
 GROUP BY DOC_CODSUC,DOC_TIPDOC,DOC_NUMERO  HAVING CXD_CXCDIV<>0 
 ORDER BY DOC_CODSUC,DOC_TIPDOC,DOC_NUMERO;

-- 88
 CREATE OR REPLACE VIEW  VIEW_DOCCLICXC AS 
SELECT DOC_CODSUC AS CXD_CODSUC,DOC_TIPDOC AS CXD_TIPDOC,DOC_NUMERO AS CXD_NUMERO,  DOC_CODIGO AS CXD_CODIGO,  MAX(DOC_FCHVEN) AS CXD_FCHMAX, MIN(DOC_FECHA)  AS CXD_FECHA, 
 SUM(ROUND((DOC_NETO+IF(DOC_TIPTRA="D",DOC_MTOCOM,0))/DOC_VALCAM,2)*DOC_CXC) AS CXD_CXCDIV, 
 SUM(IF(DOC_TIPTRA="D",DOC_NETO,0)) AS CXD_MTODOC,
 SUM(DOC_NETO*DOC_CXC) AS CXD_NETO,
 SUM(IF(DOC_TIPTRA="P",DOC_NETO,0)) AS CXD_MTOPAG, 
 SUM(IF(DOC_TIPTRA="P",ROUND((DOC_NETO+DOC_MTOCOM)/DOC_VALCAM,2),0)) AS CXD_PAGDIV, 
 SUM(DOC_NETO*DOC_CXC) AS CXD_SALDO  FROM 
 dpdoccli  WHERE DOC_CXC<>0 AND DOC_ACT=1 AND DOC_VALCAM>=1 
 GROUP BY DOC_CODSUC,DOC_TIPDOC,DOC_NUMERO  HAVING
 SUM(DOC_NETO*DOC_CXC)<>0 
 ORDER BY DOC_CODSUC,DOC_TIPDOC,DOC_NUMERO;

-- 89
 CREATE OR REPLACE VIEW  VIEW_DOCPROCXPDIV AS 
SELECT   DOC_CODSUC AS CXD_CODSUC,  DOC_TIPDOC AS CXD_TIPDOC,  DOC_NUMERO AS CXD_NUMERO,  DOC_CODIGO AS CXD_CODIGO,  MAX(DOC_FCHVEN) AS CXD_FCHMAX, MIN(DOC_FECHA)  AS CXD_FECHA, 
 SUM(ROUND((DOC_NETO+IF(DOC_TIPTRA="D",DOC_MTOCOM,0))/DOC_VALCAM,2)*DOC_CXP) AS CXD_CXPDIV, 
 SUM(IF(DOC_TIPTRA="D",DOC_NETO,0)) AS CXD_MTODOC,
 SUM(DOC_NETO*DOC_CXP) AS CXD_NETO, 
 SUM(IF(DOC_TIPTRA="P",DOC_NETO,0)) AS CXD_MTOPAG,
 SUM(IF(DOC_TIPTRA="P",ROUND((DOC_NETO+DOC_MTOCOM)/DOC_VALCAM,2),0)) AS CXD_PAGDIV  FROM 
 dpdocpro  WHERE DOC_CXP<>0 AND DOC_ACT=1 AND DOC_VALCAM>1 
 GROUP BY DOC_CODSUC,DOC_TIPDOC,DOC_CODIGO,DOC_NUMERO   HAVING CXD_CXPDIV<>0 
 ORDER BY DOC_CODSUC,DOC_TIPDOC,DOC_CODIGO,DOC_NUMERO;

-- 90
 CREATE OR REPLACE VIEW  VIEW_DOCPROCXP AS 
SELECT   DOC_CODSUC AS CXD_CODSUC, DOC_TIPDOC AS CXD_TIPDOC, DOC_NUMERO AS CXD_NUMERO, DOC_CODIGO AS CXD_CODIGO, MAX(DOC_FCHVEN) AS CXD_FCHMAX, DOC_FECHA       AS CXD_FECHA, 
 SUM(DOC_NETO*DOC_CXP) AS CXD_NETO,
 SUM(IF(DOC_TIPTRA="D",DOC_NETO,0)) AS CXD_MTODOC,
 SUM(IF(DOC_TIPTRA="P",DOC_NETO,0)) AS CXD_MTOPAG,
 SUM(ROUND((DOC_NETO+IF(DOC_TIPTRA="D",DOC_MTOCOM,0))/DOC_VALCAM,2)*DOC_CXP) AS CXD_CXPDIV, 
 SUM(DOC_NETO*DOC_CXP) AS CXD_SALDO  FROM 
 DPDOCPRO  WHERE DOC_CXP<>0 AND DOC_ACT=1 
 GROUP BY DOC_CODSUC,DOC_TIPDOC,DOC_CODIGO,DOC_NUMERO  HAVING
 SUM(DOC_NETO*DOC_CXP)<>0 
 ORDER BY DOC_CODSUC,DOC_TIPDOC,DOC_CODIGO,DOC_NUMERO;

-- 91
 CREATE OR REPLACE VIEW  VIEW_DPDPTOINVCTA_ATC AS 
SELECT  CIC_CTAMOD AS ATC_CTAMOD, CIC_CODIGO AS ATC_CODGRU, CIC_CUENTA AS GRU_CTAATC FROM 
 DPDPTO_INV_CTA  WHERE CIC_CODINT='CTAATC'
;

-- 92
 CREATE OR REPLACE VIEW  VIEW_DPDPTOINVCTA_COM AS 
SELECT  CIC_CTAMOD AS COM_CTAMOD, CIC_CODIGO AS COM_CODGRU, CIC_CUENTA AS GRU_CTACOM FROM 
 DPDPTO_INV_CTA  WHERE CIC_CODINT='CTACOM'
;

-- 93
 CREATE OR REPLACE VIEW  VIEW_DPDPTOINVCTA_COS AS 
SELECT  CIC_CTAMOD AS COS_CTAMOD, CIC_CODIGO AS COS_CODGRU, CIC_CUENTA AS GRU_CTACOS FROM 
 DPDPTO_INV_CTA  WHERE CIC_CODINT='CTACOS'
;

-- 94
 CREATE OR REPLACE VIEW  VIEW_DPDPTOINVCTA_DVC AS 
SELECT  CIC_CTAMOD AS DVC_CTAMOD, CIC_CODIGO AS DVC_CODGRU, CIC_CUENTA AS GRU_CTADVC FROM 
 DPDPTO_INV_CTA  WHERE CIC_CODINT='CTADVC'
;

-- 95
 CREATE OR REPLACE VIEW  VIEW_DPDPTOINVCTA_DVV AS 
SELECT  CIC_CTAMOD AS DVV_CTAMOD, CIC_CODIGO AS DVV_CODGRU, CIC_CUENTA AS GRU_CTADVV FROM 
 DPDPTO_INV_CTA  WHERE CIC_CODINT='CTADVV'
;

-- 96
 CREATE OR REPLACE VIEW  VIEW_DPDPTOINVCTA_FIN AS 
SELECT  CIC_CTAMOD AS FIN_CTAMOD, CIC_CODIGO AS FIN_CODGRU, CIC_CUENTA AS GRU_CTAFIN FROM 
 DPDPTO_INV_CTA  WHERE CIC_CODINT='CTAFIN'
;

-- 97
 CREATE OR REPLACE VIEW  VIEW_DPDPTOINVCTA_INI AS 
SELECT  CIC_CTAMOD AS INI_CTAMOD, CIC_CODIGO AS INI_CODGRU, CIC_CUENTA AS GRU_CTAINI FROM 
 DPDPTO_INV_CTA  WHERE CIC_CODINT='CTAINI'
;

-- 98
 CREATE OR REPLACE VIEW  VIEW_DPDPTOINVCTA_VTA AS 
SELECT  CIC_CTAMOD AS VTA_CTAMOD, CIC_CODIGO AS VTA_CODGRU, CIC_CUENTA AS GRU_CTAVTA FROM 
 DPDPTO_INV_CTA  WHERE CIC_CODINT='CTAVTA'
;

-- 99
 CREATE OR REPLACE VIEW  VIEW_DPMOVINVDETEXP AS 
SELECT   MOV_CODSUC AS EXP_CODSUC, MOV_ASOTIP AS EXP_ASOTIP, MOV_ASODOC AS EXP_ASODOC, MOV_DOCUME AS EXP_DOCUME, MOV_TIPDOC AS EXP_TIPDOC, MOV_CODIGO AS EXP_CODIGO, MOV_CANTID AS EXP_CANTID, MOV_ITEM   AS EXP_ITEM,   MOV_ITEM_A AS EXP_ITEM_A, MOV_TOTAL  AS EXP_TOTAL , MOV_FISICO AS EXP_FISICO, MOV_LOGICO AS EXP_LOGICO, MOV_CONTAB AS EXP_CONTAB  FROM 
  DPMOVINV  WHERE  MOV_ASOTIP<>"" AND MOV_ASODOC<>"" AND MOV_ITEM_A<>""  AND MOV_INVACT=1 
 ORDER BY MOV_CODSUC,MOV_ASOTIP,MOV_DOCUME,MOV_CODIGO;

-- 100
 CREATE OR REPLACE VIEW  VIEW_DPPROVXINVDET AS 
SELECT          MOV_CODIGO      AS PXP_CODINV, MOV_CODCTA      AS PXP_CODPRO, MAX(MOV_FECHA)  AS PXP_FECHA  FROM 
 DPMOVINV  WHERE  MOV_APLORG="C" AND MOV_INVACT=1 
 GROUP BY MOV_CODIGO,MOV_CODCTA 
 ORDER BY MOV_CODCTA;

-- 101
 CREATE OR REPLACE VIEW  VIEW_ASIENTOS_DIAG AS 
SELECT  MOC_CODSUC AS ACR_CODSUC, MOC_NUMEJE AS ACR_NUMEJE, MOC_CUENTA AS ACR_CUENTA, EJE_DESDE  AS ACR_DESDE,  EJE_HASTA  AS ACR_HASTA, 
 SUM(IF(MOC_ACTUAL="S",MOC_MONTO,0)) AS ACR_MTOHIS,
 SUM(IF(MOC_ACTUAL="N",MOC_MONTO,0)) AS ACR_MTODIF,
 SUM(IF(MOC_ACTUAL="A",MOC_MONTO,0)) AS ACR_MTOAUD,
 SUM(IF(MOC_ACTUAL="F",MOC_MONTO,0)) AS ACR_MTOFIN,
 SUM(IF(MOC_ACTUAL="X",MOC_MONTO,0)) AS ACR_MTOFIS  FROM 
 DPASIENTOS 
 INNER JOIN DPEJERCICIOS ON MOC_CODSUC=EJE_CODSUC AND MOC_NUMEJE=EJE_NUMERO 
 GROUP BY MOC_CODSUC,MOC_NUMEJE,MOC_CUENTA 
 ORDER BY MOC_CODSUC,MOC_NUMEJE,MOC_CUENTA;

-- 102
 CREATE OR REPLACE VIEW  VIEW_RDCDIARIO_CAJA AS 
SELECT  DOC_SERFIS   AS CAJ_SERFIS,  CAJ_CODSUC   AS CAJ_CODSUC, CAJ_FECHA    AS CAJ_FECHA, 
 SUM(CAJ_MONTO *CAJ_DEBCRE) AS CAJ_MONTO, 
 SUM(IF(CAJ_TIPO="DOL",CAJ_MTODIV*CAJ_DEBCRE,0)) AS CAJ_MTODIV, 
 SUM(CAJ_MTOITF*CAJ_DEBCRE) AS CAJ_MTOITF, COUNT(*) AS CAJ_CANREG  FROM 
 dpcajamov 
 INNER JOIN DPDOCCLI ON CAJ_CODSUC=DOC_CODSUC AND CAJ_ORIGEN=DOC_TIPDOC AND CAJ_DOCASO=DOC_NUMERO AND DOC_TIPTRA="D" AND DOC_ACT=1  WHERE CAJ_ACT=1    AND (CAJ_TIPO="DOL" OR CAJ_TIPO="EFE") 
 GROUP BY CAJ_CODSUC,CAJ_FECHA,DOC_SERFIS 
 ORDER BY CAJ_CODSUC,CAJ_FECHA,DOC_SERFIS;

-- 103
 CREATE OR REPLACE VIEW  VIEW_DPRUTADIA AS 
SELECT       DRT_CODRUT,      DRT_DIASEM,      DRT_DIADES,      DRT_DIAPED,      COUNT(*) AS DRT_CANTID      FROM 
 DPRUTADIA      LEFT JOIN DPCLIENTES ON DRT_CODRUT=CLI_CODRUT      
 GROUP BY DRT_CODRUT,DRT_DIADES,DRT_DIAPED,DRT_DIASEM     
 ORDER BY DRT_CODRUT,DRT_DIASEM
;

-- 104
 CREATE OR REPLACE VIEW  VIEW_CLICATMAXFCH AS 
SELECT     DOC_CODSUC      AS CAT_CODSUC,    DOC_TIPDOC      AS CAT_TIPDOC,    DOC_CODIGO      AS CAT_CODIGO,    MAX(DOC_FECHA)  AS CAT_MAXFCH,   
 SUM(DOC_BASNET*DOC_CXC) AS CAT_MTOBAS    FROM 
 DPDOCCLI    WHERE DOC_CXC<>0 AND DOC_ACT=1 AND DOC_TIPTRA="D"   
 GROUP BY DOC_CODSUC,DOC_TIPDOC,DOC_CODIGO   
 ORDER BY DOC_CODSUC,DOC_TIPDOC,DOC_CODIGO
;

-- 105
 CREATE OR REPLACE VIEW  VIEW_DOCCLIDESORG AS 
SELECT    DOC_CODSUC AS DOR_CODSUC, DOC_TIPDOC AS DOR_TIPORG, DOC_NUMERO AS DOR_DOCORG, DOC_TIPORG AS DOR_TIPDES, DOC_ASODOC AS DOR_DOCDES, DOC_BASNET AS DOR_BASNET, DOC_NETO   AS DOR_NETO  , DOC_ESTADO AS DOR_ESTADO, DOC_VALCAM AS DOR_VALCAM, DOC_FECHA  AS DOR_FECHA   FROM 
 DPDOCCLI  WHERE DOC_TIPTRA="D" 
 ORDER BY DOC_CODSUC,DOC_TIPDOC,DOC_NUMERO,DOC_TIPORG,DOC_ASODOC;

-- 106
 CREATE OR REPLACE VIEW  VIEW_DPASIENTOSDOCPAG AS 
SELECT      MOC_CODSUC AS DCP_CODSUC,      MOC_TIPO   AS DCP_TIPDOC,      MOC_CODAUX AS DCP_CODIGO,      MOC_DOCUME AS DCP_NUMERO,      MOC_CTAMOD AS DCP_CTAMOD,      MOC_NUMPAR AS DCP_NUMPAR,      MOC_CUENTA AS DCP_CUENTA,      MOC_MONTO  AS DCP_MONTO ,  MOC_FECHA  AS DCP_FECHA     FROM 
 DPASIENTOS      WHERE MOC_ORIGEN="COM" AND  MOC_TIPTRA="P" AND MOC_DOCUME<>""     
 ORDER BY MOC_CODSUC,MOC_TIPO,MOC_CODAUX,MOC_DOCUME
;

-- 107
 CREATE OR REPLACE VIEW  VIEW_DOCPRODOC AS 
SELECT  DOC_CODSUC AS ORG_CODSUC, DOC_TIPDOC AS ORG_TIPDOC, DOC_CODIGO AS ORG_CODIGO, DOC_NUMERO AS ORG_NUMERO, DOC_FECHA  AS ORG_FECHA,  DOC_NETO   AS ORG_NETO,   DOC_BASNET AS ORG_BASNET, DOC_MTOIVA AS ORG_MTOIVA, DOC_VALCAM AS ORG_VALCAM  FROM 
 DPDOCPRO  WHERE DOC_TIPTRA="D" AND DOC_CXP<>0 
 GROUP BY DOC_CODSUC,DOC_TIPDOC,DOC_CODIGO,DOC_NUMERO 
 ORDER BY DOC_CODSUC,DOC_TIPDOC,DOC_CODIGO,DOC_NUMERO;

-- 108
 CREATE OR REPLACE VIEW  VIEW_DOCPRODESORG AS 
SELECT    DOC_CODSUC AS DOR_CODSUC, DOC_TIPDOC AS DOR_TIPORG, DOC_CODIGO AS DOR_CODIGO, DOC_NUMERO AS DOR_DOCORG, DOC_TIPORG AS DOR_TIPDES, DOC_ASODOC AS DOR_DOCDES, DOC_BASNET AS DOR_BASNET, DOC_NETO   AS DOR_NETO  , DOC_ESTADO AS DOR_ESTADO, DOC_VALCAM AS DOR_VALCAM, DOC_FECHA  AS DOR_FECHA   FROM 
 DPDOCPRO  WHERE DOC_TIPTRA="D" 
 ORDER BY DOC_CODSUC,DOC_TIPDOC,DOC_CODIGO,DOC_NUMERO,DOC_TIPORG,DOC_ASODOC;

-- 109
 CREATE OR REPLACE VIEW  VIEW_DOCCLIDOC AS 
SELECT  DOC_CODSUC AS ORG_CODSUC,  DOC_TIPDOC AS ORG_TIPDOC,  DOC_NUMERO AS ORG_NUMERO,  DOC_FECHA  AS ORG_FECHA,   DOC_NETO   AS ORG_NETO,    DOC_BASNET AS ORG_BASNET,  DOC_MTOIVA AS ORG_MTOIVA,  DOC_VALCAM AS ORG_VALCAM,  DOC_ESTADO AS ORG_ESTADO   FROM 
 DPDOCCLI  WHERE DOC_TIPTRA="D" AND DOC_CXC<>0 
 GROUP BY DOC_CODSUC,DOC_TIPDOC,DOC_NUMERO 
 ORDER BY DOC_CODSUC,DOC_TIPDOC,DOC_NUMERO;

-- 110
 CREATE OR REPLACE VIEW  VIEW_DPMOVINVRESINV AS 
SELECT           MOV_CODSUC      AS MOV_CODSUC,          MOV_TIPDOC      AS MOV_TIPDOC,          MOV_DOCUME      AS MOV_DOCUME,          MOV_CODIGO      AS MOV_CODIGO,         MOV_UNDMED      AS MOV_UNDMED,        
 SUM(MOV_CANTID) AS MOV_CANTID,         
 SUM(MOV_CXUND)  AS MOV_CXUND          FROM 
 DPMOVINV          WHERE MOV_APLORG="V"     
 GROUP BY MOV_CODSUC,MOV_TIPDOC,MOV_DOCUME,MOV_CODIGO,MOV_UNDMED         
 ORDER BY MOV_CODSUC,MOV_TIPDOC,MOV_DOCUME,MOV_CODIGO,MOV_UNDMED
;

-- 111
 CREATE OR REPLACE VIEW  VIEW_DPCOBCOM AS 
SELECT      DOC_CODSUC AS COB_CODSUC,      DOC_TIPDOC AS COB_TIPDOC,      DOC_NUMERO AS COB_NUMERO,      DOC_BASNET AS COB_BASNET,      DOC_FECHA  AS COB_FECHA,      DOC_CODVEN AS COB_CODVEN,      DOC_FCHVEN AS COB_FCHVEN         FROM 
    DPDOCCLI     
 INNER JOIN DPTIPDOCCLI ON DOC_TIPDOC=TDC_TIPO AND TDC_COMISI=1      WHERE DOC_TIPTRA="P" AND DOC_ACT=1
;

-- 112
 CREATE OR REPLACE VIEW  VIEW_DPDOCCLICXCNOLIBVTA AS 
SELECT   DOC_CODSUC AS DOO_CODSUC,  DOC_TIPDOC AS DOO_TIPDOC,  DOC_NUMERO AS DOO_NUMERO  FROM 
 DPDOCCLI 
 INNER JOIN DPTIPDOCCLI ON DOC_TIPDOC=TDC_TIPO AND TDC_LIBVTA=0   WHERE DOC_CXC<>0 AND DOC_ACT=1 AND DOC_TIPTRA="D"   
 ORDER BY DOC_CODSUC,DOC_TIPDOC,DOC_NUMERO
;

-- 113
 CREATE OR REPLACE VIEW  VIEW_DPDOCCLIAAA AS 
SELECT                   DOC_CODSUC             AS AAA_CODSUC,                  DOC_TIPDOC             AS AAA_TIPDOC,                  DOC_CODIGO             AS AAA_CODIGO,                  YEAR(DOC_FECHA)        AS AAA_ANO,                  MONTH(DOC_FECHA)       AS AAA_MES,                 
 SUM(DOC_NETO*DOC_CXC)  AS AAA_NETO,    
 SUM(DOC_NETO*DOC_CXC/DOC_VALCAM)  AS AAA_MTODIV,     COUNT(*)               AS AAA_CUANTOS                  FROM 
 DPDOCCLI                  WHERE DOC_TIPTRA="D" AND DOC_ACT=1                 
 GROUP BY DOC_CODSUC,DOC_TIPDOC,DOC_CODIGO,YEAR(DOC_FECHA),MONTH(DOC_FECHA)                 
 ORDER BY DOC_CODSUC,DOC_TIPDOC,DOC_CODIGO,YEAR(DOC_FECHA),MONTH(DOC_FECHA)
;

-- 114
 CREATE OR REPLACE VIEW  VIEW_DOCCLIORGDES AS 
SELECT  DOC_CODSUC AS DEX_CODSUC, DOC_TIPORG AS DEX_TIPORG, DOC_ASODOC AS DEX_DOCORG, DOC_TIPDOC AS DEX_TIPDES, DOC_NUMERO AS DEX_DOCDES, DOC_BASNET AS DEX_BASNET, DOC_NETO   AS DEX_NETO  , DOC_ESTADO AS DEX_ESTADO, DOC_FECHA  AS DEX_FECHA,  DOC_VALCAM AS DEX_VALCAM  FROM 
 DPDOCCLI  WHERE DOC_TIPTRA="D" AND DOC_TIPORG<>"" 
 ORDER BY DOC_CODSUC,DOC_TIPORG,DOC_ASODOC,DOC_TIPDOC,DOC_NUMERO;

-- 115
 CREATE OR REPLACE VIEW  VIEW_DPDOCCLITIPXEXP AS 
SELECT          DOC_CODSUC AS DXE_CODSUC, DOC_TIPDOC AS DXE_TIPDOC, DOC_NUMERO AS DXE_NUMERO, DOC_CODIGO AS DXE_CODIGO, DOC_FECHA  AS DXE_FECHA,  DOC_BASNET AS DXE_BASNET, DOC_MTOIVA AS DXE_MTOIVA, DOC_NETO   AS DXE_NETO,   DOC_MTODIV AS DXE_MTODIV, DOC_VALCAM AS DXE_VALCAM, DOC_ESTADO AS DXE_ESTADO, TDC_DOCDES AS DXE_TIPDES  FROM 
 DPDOCCLI 
 INNER JOIN DPTIPDOCCLI  ON DOC_TIPDOC=TDC_TIPO AND TDC_DOCDES<>"" 
 INNER JOIN DPCLIENTES   ON DOC_CODIGO=CLI_CODIGO   WHERE DOC_ASODOC="" AND DOC_ACT=1 AND DOC_ESTADO="AC" 
 ORDER BY DOC_CODSUC,DOC_TIPDOC,DOC_NUMERO;

-- 116
 CREATE OR REPLACE VIEW  VIEW_DPDOCCBTE AS 
SELECT DOC_NUMERO,DOC_TIPDOC,              IF(CBT_NUMERO IS NULL, "No posee Asiento Diferido",CBT_NUMERO) AS "Comprobante Diferido",                      IF(CBT_ACTUAL IS NULL, "No posee Asiento Diferido",IF(CBT_ACTUAL="S","Asiento Actualizado","Asiento no Actualizado")) AS "Comprobante Actualizado"                             FROM 
         DPDOCPRO                     
 INNER JOIN DPTIPDOCPRO ON TDC_TIPO = DOC_TIPDOC                      LEFT  JOIN DPCBTE ON DOC_CBTNUM = CBT_NUMERO                      WHERE TDC_CONTAB = 1                     
 GROUP BY DOC_NUMERO,DOC_TIPDOC,CBT_NUMERO         
 ORDER BY DOC_NUMERO
;

-- 117
 CREATE OR REPLACE VIEW  VIEW_DPDOCPROTIPXEXP AS 
SELECT  DOC_CODSUC AS DXE_CODSUC, DOC_TIPDOC AS DXE_TIPDOC, DOC_NUMERO AS DXE_NUMERO, DOC_CODIGO AS DXE_CODIGO, DOC_FECHA  AS DXE_FECHA,  DOC_BASNET AS DXE_BASNET, DOC_MTOIVA AS DXE_MTOIVA, DOC_NETO   AS DXE_NETO,   DOC_MTODIV AS DXE_MTODIV, DOC_VALCAM AS DXE_VALCAM, DOC_ESTADO AS DXE_ESTADO, TDC_DOCDES AS DXE_TIPDES  FROM 
 DPDOCPRO 
 INNER JOIN DPTIPDOCPRO  ON DOC_TIPDOC=TDC_TIPO AND TDC_DOCDES<>"" 
 INNER JOIN DPPROVEEDOR  ON DOC_CODIGO=PRO_CODIGO   WHERE DOC_ASODOC="" AND DOC_ACT=1 AND DOC_ESTADO="AC" AND DOC_TIPTRA="D" 
 ORDER BY DOC_CODSUC,DOC_TIPDOC,DOC_CODIGO,DOC_NUMERO;

-- 118
 CREATE OR REPLACE VIEW  VIEW_DOCVTACOM AS 
SELECT      DOC_CODSUC AS VTA_CODSUC,      DOC_TIPDOC AS VTA_TIPDOC,      DOC_NUMERO AS VTA_NUMERO,      DOC_BASNET AS VTA_BASNET,      DOC_FECHA  AS VTA_FECHA,      DOC_CODVEN AS VTA_CODVEN,      DOC_FCHVEN AS VTA_FCHVEN         FROM 
    DPDOCCLI     
 INNER JOIN DPTIPDOCCLI ON DOC_TIPDOC=TDC_TIPO AND TDC_COMISI=1      WHERE DOC_TIPTRA="D" AND DOC_ACT=1
;

-- 119
 CREATE OR REPLACE VIEW  VIEW_DPDOCCLIBBB AS 
SELECT           DOC_CODSUC             AS BBB_CODSUC,          DOC_TIPDOC             AS BBB_TIPDOC,     DOC_CODIGO             AS BBB_CODIGO,          YEAR(DOC_FECHA)        AS BBB_ANO,          MONTH(DOC_FECHA)       AS BBB_MES,         
 SUM(DOC_NETO*DOC_CXC)  AS BBB_NETO,  
 SUM(DOC_NETO*DOC_CXC/DOC_VALCAM)  AS BBB_MTODIV,          COUNT(*)               AS BBB_CUANTOS          FROM 
 DPDOCCLI          WHERE DOC_TIPTRA="D" AND DOC_ACT=1         
 GROUP BY DOC_CODSUC,DOC_TIPDOC,DOC_CODIGO,YEAR(DOC_FECHA),MONTH(DOC_FECHA)             
 ORDER BY DOC_CODSUC,DOC_TIPDOC,DOC_CODIGO,YEAR(DOC_FECHA),MONTH(DOC_FECHA)
;

-- 120
 CREATE OR REPLACE VIEW  VIEW_DPDOCPRODOC AS 
SELECT   DOC_CODSUC,  DOC_TIPDOC,  DOC_CODIGO,  DOC_FECHA,   PRO_NOMBRE,  DOC_NUMERO,  DOC_CXP,     DOC_BASNET,  DOC_NETO,    DOC_ESTADO,  DOC_PAGNUM,  DOC_TIPTRA   FROM 
  DPDOCPRO 
 INNER JOIN DPPROVEEDOR ON PRO_CODIGO = DOC_CODIGO 
 INNER JOIN DPTIPDOCPRO ON TDC_TIPO   = DOC_TIPDOC  WHERE DOC_TIPTRA="D" AND DOC_CXP<>0 AND TDC_PAGOS = 1 
 ORDER BY DOC_CODSUC,DOC_TIPDOC,DOC_CODIGO,DOC_NUMERO;

-- 121
 CREATE OR REPLACE VIEW  VIEW_DPDOCPROCXPTIP AS 
SELECT  DOC_CODSUC AS REI_CODSUC, DOC_CXPTIP AS REI_CXPTIP, DOC_CXPCOD AS REI_CXPCOD, DOC_CXPDOC AS REI_CXPDOC, DOC_RIF    AS REI_RIF,    DOC_FECHA  AS REI_FECHA,  DOC_ACT    AS REI_ACT,    DOC_TIPDOC AS REI_TIPDOC, DOC_NUMERO AS REI_NUMERO  FROM 
 dpdocpro  WHERE DOC_CXPTIP<>"" 
 ORDER BY DOC_CODSUC,DOC_CXPTIP,DOC_CXPCOD,DOC_CXPDOC;

-- 122
 CREATE OR REPLACE VIEW  VIEW_RESDOCPROEXT AS 
SELECT         DOC_CODSUC        AS EXT_CODSUC,        YEAR(DOC_FCHDEC)  AS EXT_ANODEC,         MONTH(DOC_FCHDEC) AS EXT_MESDEC,        YEAR(DOC_FECHA)   AS EXT_ANOREG,        MONTH(DOC_FECHA)  AS EXT_MESREG,        COUNT(*)          AS EXT_CANTID        FROM 
 DPDOCPRO       
 INNER JOIN DPTIPDOCPRO ON TDC_TIPO=DOC_TIPDOC AND TDC_LIBCOM=1        WHERE CONCAT(YEAR(DOC_FCHDEC),MONTH(DOC_FCHDEC))<>CONCAT(YEAR(DOC_FECHA),MONTH(DOC_FECHA))       
 GROUP BY DOC_CODSUC,CONCAT(YEAR(DOC_FCHDEC),MONTH(DOC_FCHDEC))
;

-- 123
 CREATE OR REPLACE VIEW  VIEW_DPDOCCLIPAG AS 
SELECT  DOC_CODSUC AS PAG_CODSUC,  DOC_TIPDOC AS PAG_TIPDOC,  DOC_CODIGO AS PAG_CODIGO,  DOC_FECHA  AS PAG_FECHA ,  CLI_NOMBRE AS PAG_NOMBRE,  DOC_NUMERO AS PAG_NUMERO,  DOC_CXC    AS PAG_CXC,     IF(DOC_TIPTRA="D","P","D") AS PAG_TIPTRA, DOC_NETO   AS PAG_NETO,   DOC_BASNET AS PAG_BASNET, DOC_MTOIVA AS PAG_MTOIVA, DOC_RECNUM AS PAG_RECNUM, DOC_FCHDEC AS PAG_FCHDEC, DOC_VALCAM AS PAG_VALCAM, ROUND(DOC_NETO/DOC_VALCAM,2) AS PAG_PAGDIV, DOC_MTOCOM AS PAG_MTODIF, DOC_ACT    AS PAG_ACT,    REC_ACT    AS REC_ACT     FROM 
 DPDOCCLI 
 INNER JOIN DPCLIENTES   ON CLI_CODIGO = DOC_CODIGO   
 INNER JOIN DPRECIBOSCLI ON DOC_CODSUC = REC_CODSUC AND DOC_RECNUM=REC_NUMERO 
 INNER JOIN DPTIPDOCCLI  ON TDC_TIPO   = DOC_TIPDOC    WHERE DOC_TIPTRA="P" AND DOC_CXC<>0 AND TDC_PAGOS=1 
 ORDER BY DOC_CODSUC,DOC_TIPDOC,DOC_NUMERO;

-- 124
 CREATE OR REPLACE VIEW  VIEW_DPDOCPROPAG AS 
SELECT  DOC_CODSUC AS PAG_CODSUC,  DOC_TIPDOC AS PAG_TIPDOC,  DOC_CODIGO AS PAG_CODIGO,  DOC_FECHA  AS PAG_FECHA ,  PRO_NOMBRE AS PAG_NOMBRE,  DOC_NUMERO AS PAG_NUMERO,  DOC_CXP    AS PAG_CXP,     IF(DOC_TIPTRA="D","P","D") AS PAG_TIPTRA, DOC_NETO   AS PAG_NETO,   DOC_BASNET AS PAG_BASNET, DOC_MTOIVA AS PAG_MTOIVA, DOC_PAGNUM AS PAG_PAGNUM, DOC_FCHDEC AS PAG_FCHDEC, DOC_VALCAM AS PAG_VALCAM, ROUND(DOC_NETO/DOC_VALCAM,2) AS PAG_PAGDIV, DOC_MTOCOM AS PAG_MTODIF, DOC_ACT    AS PAG_ACT,    PAG_ACT    AS CBT_ACT     FROM 
 DPDOCPRO 
 INNER JOIN DPPROVEEDOR ON PRO_CODIGO = DOC_CODIGO   
 INNER JOIN DPCBTEPAGO  ON DOC_CODSUC = PAG_CODSUC AND DOC_PAGNUM=PAG_NUMERO 
 INNER JOIN DPTIPDOCPRO ON TDC_TIPO   = DOC_TIPDOC    WHERE DOC_TIPTRA="P" AND DOC_CXP<>0 AND TDC_PAGOS=1 
 ORDER BY DOC_CODSUC,DOC_TIPDOC,DOC_CODIGO,DOC_NUMERO;

-- 125
 CREATE OR REPLACE VIEW  VIEW_DOCCLIPAGREG AS 
SELECT       DOC_CODSUC AS DRC_CODSUC,      DOC_RECNUM AS DRC_NUMERO,     
 SUM(IF(DOC_CXC=+1,DOC_NETO*DOC_ACT,0)) AS DRC_MTODEB,     
 SUM(IF(DOC_CXC=-1,DOC_NETO*DOC_ACT,0)) AS DRC_MTOHAB,     
 SUM(IF(DOC_TIPDOC="CRE",DOC_NETO  ,0)) AS DRC_MTOCRE,     
 SUM(DOC_NETO*DOC_CXC*-1)               AS DRC_MONREC    FROM 
 DPDOCCLI      WHERE DOC_TIPTRA="P" AND DOC_ACT=1     
 GROUP BY DOC_CODSUC,DOC_RECNUM
;

-- 126
 CREATE OR REPLACE VIEW  VIEW_DPDOCCLIPAGDET AS 
SELECT   DOC_CODSUC      AS PAG_CODSUC, DOC_TIPDOC      AS PAG_TIPDOC, DOC_NUMERO      AS PAG_NUMERO, DOC_NETO        AS PAG_NETO,   DOC_MTOCOM      AS PAG_MTODIF, DOC_NETO/IF(DOC_VALCAM>=1,DOC_VALCAM,0) AS PAG_MTODIV, DOC_RECNUM      AS PAG_RECNUM, DOC_CBTNUM      AS PAG_CBTNUM, DOC_FECHA       AS PAG_FECHA , DOC_VALCAM      AS PAG_VALCAM   FROM 
 DPDOCCLI  WHERE DOC_TIPTRA="P" AND DOC_ACT=1  
 ORDER BY DOC_CODSUC,DOC_TIPDOC,DOC_NUMERO;

-- 127
 CREATE OR REPLACE VIEW  VIEW_DOCCLIFACPAGDEP AS 
SELECT           DOC_CODSUC AS PAG_CODSUC,          DOC_TIPDOC AS PAG_TIPDOC,          DOC_NUMERO AS PAG_NUMERO,          DOC_CODIGO AS PAG_CODIGO,          DOC_FECHA  AS PAG_FECHA,       
 SUM(IF(DOC_TIPTRA="D",DOC_NETO*DOC_CXC,0)) AS PAG_NETO          FROM 
 DPDOCCLI          WHERE DOC_ACT=1 AND DOC_CXC<>0         
 GROUP BY DOC_CODSUC,DOC_TIPDOC,DOC_NUMERO          HAVING
 SUM(DOC_NETO*DOC_CXC)=0         
 ORDER BY DOC_CODSUC,DOC_TIPDOC,DOC_NUMERO
;

-- 128
 CREATE OR REPLACE VIEW  VIEW_DPCXPSINPLA AS 
SELECT DOC_CODSUC AS CXP_CODSUC,  DOC_TIPDOC AS CXP_TIPDOC,  DOC_CODIGO AS CXP_CODIGO,  DOC_NUMERO AS CXP_NUMERO, 
 SUM(IF(DOC_TIPTRA="D" AND DOC_PPLREG= "",DOC_NETO/DOC_VALCAM,0))            AS CXP_NETO_SP,  
 SUM(IF(DOC_TIPTRA="P" AND DOC_PPLREG= "",DOC_NETO/DOC_VALCAM,0))            AS CXP_PAGADO_SP,
 SUM(IF(DOC_PPLREG                   = "",(DOC_NETO*DOC_CXP)/DOC_VALCAM,0))  AS CXP_SALDO_SP, 
 SUM(IF(DOC_TIPTRA="D" AND DOC_PPLREG<>"",DOC_NETO/DOC_VALCAM           ,0)) AS CXP_NETO  ,   
 SUM(IF(DOC_TIPTRA="P" AND DOC_PPLREG<>"",DOC_NETO/DOC_VALCAM           ,0)) AS CXP_PAGADO,   
 SUM(IF(DOC_PPLREG                   <>"",(DOC_NETO*DOC_CXP)/DOC_VALCAM,0))  AS CXP_SALDO ,    MAX(DOC_FCHVEN)                                                             AS CXP_FECHA      FROM 
 dpdocpro  WHERE DOC_CXP<>0 AND DOC_ACT=1 
 GROUP BY DOC_CODSUC,DOC_TIPDOC,DOC_CODIGO,DOC_NUMERO  HAVING
 SUM(DOC_NETO*DOC_CXP)<>0 
 ORDER BY DOC_CODSUC,DOC_TIPDOC,DOC_CODIGO,DOC_NUMERO;

-- 129
 CREATE OR REPLACE VIEW  VIEW_DPDOCCLITIPAFEDES AS 
SELECT  DOC_CODSUC  AS DES_CODSUC,  DOC_TIPAFE  AS DES_TIPDOC,  DOC_TIPDOC  AS DES_TIPORG,  DOC_NUMERO  AS DES_DOCORG,  DOC_ASODOC  AS DES_NUMERO,  DOC_NETO    AS DES_NETO,    DOC_FECHA   AS DES_FECHA,   DOC_VALCAM  AS DES_VALCAM,  ROUND(DOC_NETO/DOC_VALCAM,2) AS DES_MTODIV,  DOC_ESTADO          AS DES_ESTADO  FROM 
 dpdoccli  WHERE DOC_TIPAFE<>"" 
 ORDER BY DOC_CODSUC,DOC_TIPAFE,DOC_ASODOC;

-- 130
 CREATE OR REPLACE VIEW  VIEW_EASYDOCANU AS 
SELECT  YEAR(DOC_FECHA) AS AÑO,                 DOC_NUMERO     AS NUMERO,               DOC_TIPDOC     AS TIPDOC,               
 SUM(IF(CCD_TIPIVA="EX",CCD_MONTO,0)) AS CCD_EXENTO,                  
 SUM(IF(CCD_TIPIVA<>"EX",CCD_MONTO,0)) AS CCD_IMPONIBLE,                 
 SUM(IF(CCD_TIPDOC IS NOT NULL,CCD_MONTO,0)) AS CCD_BRUTO,                 
 SUM(IF(CCD_TIPIVA="RD",CCD_MONTO*0.08,0)) AS CCD_IVARD,                 
 SUM(IF(CCD_TIPIVA="GN",CCD_MONTO*0.12,0)) AS CCD_IVAGN,                 
 SUM(IF(CCD_TIPIVA="S1",CCD_MONTO*0.22,0)) AS CCD_IVAS1,                 
 SUM(IF(CCD_TIPIVA="S2",CCD_MONTO*0.32,0)) AS CCD_IVAS2,                 
 SUM(IF(DOC_TIPDOC="RTI",DOC_NETO,0))      AS DOC_RTI,                 
 SUM(IF(DOC_TIPDOC="RET",DOC_NETO,0))      AS DOC_RET             FROM 
     DPDOCPRO         LEFT JOIN DPDOCPROCTA ON DOC_NUMERO=CCD_NUMERO                                                    AND DOC_TIPDOC=CCD_TIPDOC         WHERE  DOC_TIPTRA="D" AND DOC_ACT=1        
 GROUP BY YEAR(DOC_FECHA)
;

-- 131
 CREATE OR REPLACE VIEW  VIEW_EASYDOCMEN AS 
SELECT  YEAR(DOC_FECHA) AS AÑO,               DOC_NUMERO      AS NUMERO,               DOC_TIPDOC      AS TIPDOC,               MONTH(DOC_FECHA) AS MES,               
 SUM(IF(CCD_TIPIVA="EX",CCD_MONTO,0)) AS CCD_EXENTO,               
 SUM(IF(CCD_TIPIVA<>"EX",CCD_MONTO,0)) AS CCD_IMPONIBLE,               
 SUM(IF(CCD_TIPDOC IS NOT NULL,CCD_MONTO,0)) AS CCD_BRUTO,               
 SUM(IF(CCD_TIPIVA="RD",CCD_MONTO*0.08,0)) AS CCD_IVARD,               
 SUM(IF(CCD_TIPIVA="GN",CCD_MONTO*0.12,0)) AS CCD_IVAGN,               
 SUM(IF(CCD_TIPIVA="S1",CCD_MONTO*0.22,0)) AS CCD_IVAS1,               
 SUM(IF(CCD_TIPIVA="S2",CCD_MONTO*0.32,0)) AS CCD_IVAS2,               
 SUM(IF(DOC_TIPDOC="RTI",DOC_NETO,0))      AS DOC_RTI,               
 SUM(IF(DOC_TIPDOC="RET",DOC_NETO,0))      AS DOC_RET          FROM 
    DPDOCPRO       LEFT JOIN DPDOCPROCTA ON DOC_NUMERO=CCD_NUMERO                                                  AND DOC_TIPDOC=CCD_TIPDOC       WHERE  DOC_TIPTRA="D" AND DOC_ACT=1     
 GROUP BY YEAR(DOC_FECHA),MONTH(DOC_FECHA)
;

-- 132
 CREATE OR REPLACE VIEW  VIEW_FIFOENTRADAS AS 
SELECT       MOV_CODSUC AS FIF_CODSUC,      MOV_CODIGO AS FIF_CODIGO,      MOV_LOTE   AS FIF_CAPA,      MOV_FECHA  AS FIF_FECHA,      MOV_CANTID*MOV_CXUND  AS FIF_CANUND,      MOV_TOTAL/(MOV_CANTID*MOV_CXUND) AS FIF_COSTO,  MOV_PRECIO AS FIF_PRECIO      FROM 
 DPMOVINV      WHERE MOV_CONTAB=1 AND MOV_METCOS="F" AND MOV_INVACT=1     
 ORDER BY MOV_CODSUC,MOV_CODIGO,MOV_FECHA
;

-- 133
 CREATE OR REPLACE VIEW  VIEW_DOCCLIENTXCLI AS 
SELECT         MOV_CODSUC           AS ENT_CODSUC,        DPDOCCLI.DOC_CODIGO  AS ENT_CODCLI,        MOV_TIPDOC           AS ENT_TIPDOC,        DOC_NUMERO           AS ENT_NUMDOC,        MOV_ASODOC           AS ENT_CODPLA,      MOV_CODIGO           AS ENT_CODINV,        MOV_FECHA            AS ENT_FECHA,        MOV_FCHVEN           AS ENT_FCHVEN,       
 SUM(MOV_CANTID)      AS ENT_CANUND,       
 SUM(MOV_TOTAL)       AS ENT_TOTAL,    DPDOCCLI.DOC_ESTADO  AS ENT_ESTADO,            COUNT(*)             AS ENT_CANTID      FROM 
 DPMOVINV        
 INNER JOIN DPDOCCLI ON DOC_CODSUC=MOV_CODSUC AND DOC_TIPDOC=MOV_TIPDOC AND DOC_NUMERO=MOV_DOCUME        
 INNER JOIN DPDOCPLANTILLA ON DPDOCPLANTILLA.DOC_CODSUC=DPDOCCLI.DOC_CODSUC AND MOV_ASODOC=DPDOCPLANTILLA.DOC_CODIGO        WHERE MOV_INVACT=1 AND MOV_APLORG="V" AND MOV_TIPO="E"        
 GROUP BY MOV_CODSUC,DPDOCCLI.DOC_CODIGO,MOV_TIPDOC,DOC_NUMERO,MOV_ASODOC       
 ORDER BY MOV_CODSUC,DPDOCCLI.DOC_CODIGO,MOV_TIPDOC,DOC_NUMERO,MOV_ASODOC
;

-- 134
 CREATE OR REPLACE VIEW  VIEW_PAISES_ESTADOS AS 
SELECT PAIS     AS PAIS_NOMBRE, COUNT(*) AS PAIS_CANEDO FROM 
 dpestados
 GROUP BY PAIS
 ORDER BY PAIS;

-- 135
 CREATE OR REPLACE VIEW  VIEW_INVEXICON AS 
SELECT MOV_CODIGO AS EXC_CODIGO,           
 SUM(MOV_CANTID*MOV_CXUND*MOV_CONTAB) AS EXC_CANTID             FROM 
 DPMOVINV  AS EXF_CANTID            WHERE MOV_INVACT<>0  AND MOV_CONTAB<>0     
 GROUP BY MOV_CODIGO     
 ORDER BY MOV_CODIGO
;

-- 136
 CREATE OR REPLACE VIEW  VIEW_INVEXICONSUC AS 
SELECT      MOV_CODSUC AS EXC_CODSUC,      MOV_CODIGO AS EXC_CODIGO,               
 SUM(MOV_CANTID*MOV_CXUND*MOV_CONTAB) AS EXC_CANTID                 FROM 
 DPMOVINV  AS EXF_CANTID                WHERE MOV_INVACT<>0  AND MOV_CONTAB<>0         
 GROUP BY MOV_CODSUC,MOV_CODIGO         
 ORDER BY MOV_CODSUC,MOV_CODIGO
;

-- 137
 CREATE OR REPLACE VIEW  VIEW_INVEXICONSUCALM AS 
SELECT        MOV_CODSUC AS EXC_CODSUC,   MOV_CODALM AS EXC_CODALM,        MOV_CODIGO AS EXC_CODIGO,                 
 SUM(MOV_CANTID*MOV_CXUND*MOV_CONTAB) AS EXC_CANTID                   FROM 
 DPMOVINV  AS EXF_CANTID                  WHERE MOV_INVACT<>0  AND MOV_CONTAB<>0           
 GROUP BY MOV_CODSUC,MOV_CODALM,MOV_CODIGO           
 ORDER BY MOV_CODSUC,MOV_CODALM,MOV_CODIGO
;

-- 138
 CREATE OR REPLACE VIEW  VIEW_INVEXIFIS AS 
SELECT     MOV_CODIGO AS EXF_CODIGO,               
 SUM(MOV_CANTID*MOV_CXUND*MOV_FISICO) AS EXF_CANTID                 FROM 
 DPMOVINV               WHERE MOV_INVACT<>0  AND MOV_FISICO<>0       
 GROUP BY MOV_CODIGO         
 ORDER BY MOV_CODIGO
;

-- 139
 CREATE OR REPLACE VIEW  VIEW_INVEXIFISSUC AS 
SELECT     MOV_CODSUC AS EXF_CODSUC,    MOV_CODIGO AS EXF_CODIGO,                 
 SUM(MOV_CANTID*MOV_CXUND*MOV_FISICO) AS EXF_CANTID                   FROM 
 DPMOVINV                 WHERE MOV_INVACT<>0  AND MOV_FISICO<>0         
 GROUP BY MOV_CODSUC,MOV_CODIGO           
 ORDER BY MOV_CODSUC,MOV_CODIGO
;

-- 140
 CREATE OR REPLACE VIEW  VIEW_INVEXIFISSUCALM AS 
SELECT       MOV_CODSUC AS EXF_CODSUC,   MOV_CODALM AS EXF_CODALM,         MOV_CODIGO AS EXF_CODIGO,                   
 SUM(MOV_CANTID*MOV_CXUND*MOV_FISICO) AS EXF_CANTID                     FROM 
 DPMOVINV                   WHERE MOV_INVACT<>0  AND MOV_FISICO<>0           
 GROUP BY MOV_CODSUC,MOV_CODALM,MOV_CODIGO             
 ORDER BY MOV_CODSUC,MOV_CODALM,MOV_CODIGO
;

-- 141
 CREATE OR REPLACE VIEW  VIEW_INVEXILOG AS 
SELECT MOV_CODIGO AS EXL_CODIGO,             
 SUM(MOV_CANTID*MOV_CXUND*MOV_LOGICO) AS EXL_CANTID               FROM 
 DPMOVINV             WHERE MOV_INVACT<>0  AND MOV_LOGICO<>0   
 GROUP BY MOV_CODIGO     
 ORDER BY MOV_CODIGO
;

-- 142
 CREATE OR REPLACE VIEW  VIEW_INVEXILOGSUC AS 
SELECT     MOV_CODSUC AS EXL_CODSUC,                  MOV_CODIGO AS EXL_CODIGO,                 
 SUM(MOV_CANTID*MOV_CXUND*MOV_LOGICO) AS EXL_CANTID                   FROM 
 DPMOVINV                 WHERE MOV_INVACT<>0  AND MOV_LOGICO<>0       
 GROUP BY MOV_CODIGO,MOV_CODSUC         
 ORDER BY MOV_CODIGO,MOV_CODSUC
;

-- 143
 CREATE OR REPLACE VIEW  VIEW_INVEXILOGSUCALM AS 
SELECT     MOV_CODSUC AS EXL_CODSUC,  MOV_CODALM AS EXL_CODALM,                  MOV_CODIGO AS EXL_CODIGO,                 
 SUM(MOV_CANTID*MOV_CXUND*MOV_LOGICO) AS EXL_CANTID                   FROM 
 DPMOVINV                 WHERE MOV_INVACT<>0  AND MOV_LOGICO<>0       
 GROUP BY MOV_CODIGO,MOV_CODSUC,MOV_CODALM         
 ORDER BY MOV_CODIGO,MOV_CODSUC,MOV_CODALM
;

-- 144
 CREATE OR REPLACE VIEW  VIEW_FAVDEBCRE AS 
SELECT   DOC_TIPDOC               AS DYC_TIPDOC, DOC_NUMERO               AS DYC_DOCUME, DOC_CODSUC               AS DYC_CODSUC, DOC_FACAFE               AS DYC_NUMDOC,
 SUM(DOC_NETO*DOC_CXC*-1) AS DYC_MONTO,  AVG(DOC_VALCAM)          AS DYC_VALCAM,
 SUM((DOC_NETO*DOC_CXC*-1)/DOC_VALCAM) AS DYC_MTODIV, COUNT(*) AS CUANTOS FROM 
 DPDOCCLI  WHERE DOC_TIPTRA="D" AND (NOT (DOC_TIPDOC="FAV" OR DOC_TIPDOC="ANT" OR DOC_TIPDOC="FAM") ) AND DOC_CXC<>0 AND DOC_ACT=1  AND DOC_FACAFE<>"" 
 GROUP BY DOC_CODSUC,DOC_FACAFE 
 ORDER BY DOC_CODSUC,DOC_FACAFE;

-- 145
 CREATE OR REPLACE VIEW  VIEW_FACDEBCRE AS 
SELECT             DOC_TIPDOC               AS DYC_TIPDOC,            DOC_NUMERO               AS DYC_DOCUME,      DOC_CODIGO               AS DYC_CODIGO,                                            DOC_CODSUC               AS DYC_CODSUC,                    DOC_FACAFE               AS DYC_NUMDOC,                                             
 SUM(DOC_NETO*DOC_CXP*-1) AS DYC_MONTO,                                           AVG(DOC_VALCAM)          AS DYC_VALCAM,                                         
 SUM((DOC_NETO*DOC_CXP*-1)/DOC_VALCAM) AS DYC_MTODIV,                                          COUNT(*) AS CUANTOS                                          FROM 
                                               DPDOCPRO                                              WHERE DOC_TIPTRA="D" AND (NOT (DOC_TIPDOC="FAC" OR DOC_TIPDOC="ANT") ) AND DOC_CXP<>0 AND DOC_ACT=1  AND DOC_FACAFE<>""                                         
 GROUP BY DOC_CODSUC,DOC_CODIGO,DOC_FACAFE                                         
 ORDER BY DOC_CODSUC,DOC_CODIGO,DOC_FACAFE
;

-- 146
 CREATE OR REPLACE VIEW  VIEW_DOCCLIFAVVTA AS 
SELECT                                                 DOC_CODSUC     AS PAG_CODSUC,                                                DOC_TIPDOC     AS PAG_TIPDOC,                                                DOC_NUMERO     AS PAG_NUMERO,                                                DOC_CODIGO     AS PAG_CODIGO,                                                DOC_CODVEN     AS PAG_CODVEN,                                            DOC_CXC*-1     AS PAG_CXC,                                              DOC_TIPTRA     AS PAG_TIPTRA,                                  DOC_RECNUM     AS PAG_RECNUM,                                             DOC_FECHA      AS PAG_FCHPAG,          DOC_NETO       AS PAG_MONTO,      DOC_MTOIVA     AS PAG_MTOIVA,  DOC_BASNET     AS PAG_BASNET                                                                                    FROM 
  DPDOCCLI                                                WHERE (DOC_TIPDOC="FAV" OR DOC_TIPDOC="CRE" OR DOC_TIPDOC="DEV" OR DOC_TIPDOC="CHD")                         AND DOC_TIPTRA="P" AND DOC_ACT=1                                               
 GROUP BY DOC_CODSUC,DOC_TIPDOC,DOC_NUMERO,DOC_RECNUM                                                
 ORDER BY DOC_CODSUC,DOC_FECHA
;

-- 147
 CREATE OR REPLACE VIEW  VIEW_DOCCLIFAVPAG AS 
SELECT    DOC_CODSUC     AS PAG_CODSUC, DOC_TIPDOC     AS PAG_TIPDOC, DOC_NUMERO     AS PAG_NUMERO, DOC_CODIGO     AS PAG_CODIGO, DOC_CODVEN     AS PAG_CODVEN, IF((DOC_TIPDOC="CHD" OR DOC_TIPDOC="CRE" OR DOC_TIPDOC="DEV") AND DOC_TIPTRA="D",-1,DOC_CXC*-1) AS PAG_CXC, DOC_TIPTRA     AS PAG_TIPTRA, DOC_RECNUM     AS PAG_RECNUM, MAX(DOC_FECHA) AS PAG_FCHPAG, DOC_MTOIVA     AS PAG_MTOIVA, DOC_BASNET     AS PAG_BASNET, DOC_NETO       AS PAG_NETO  , DOC_VALCAM     AS PAG_VALCAM  FROM 
  DPDOCCLI  WHERE ((DOC_TIPDOC="FAV" AND DOC_TIPTRA="P") OR        (DOC_TIPDOC="CRE" AND DOC_TIPTRA="D") OR         (DOC_TIPDOC="DEV" AND DOC_TIPTRA="D") OR         (DOC_TIPDOC="CHD" AND (DOC_TIPTRA="P" OR DOC_TIPTRA="D"))) AND DOC_ACT=1 
 GROUP BY DOC_CODSUC,DOC_TIPDOC,DOC_NUMERO,DOC_TIPTRA 
 ORDER BY DOC_CODSUC,DOC_FECHA;

-- 148
 CREATE OR REPLACE VIEW  VIEW_CALFISPRT AS 
SELECT         PLP_CODSUC AS PRT_CODSUC,        PLP_FECHA  AS PRT_FECHA        FROM 
 DPDOCPROPROG         WHERE PLP_TIPDOC="PRT"
;

-- 149
 CREATE OR REPLACE VIEW  VIEW_DPCTABANFCHCON AS 
SELECT      MOB_CODBCO,      MOB_CUENTA,      DPBANCOS.BAN_NOMBRE,      MAX(MOB_FCHCON) AS MOB_FCHCON,      COUNT(*) AS MOB_CUANTOS      FROM 
 dpctabancomov     
 INNER JOIN DPBANCOS ON DPBANCOS.BAN_CODIGO = MOB_CODBCO      WHERE MOB_CUENTA<>""     
 GROUP BY MOB_CODBCO,MOB_CUENTA     
 ORDER BY MOB_CODBCO,MOB_CUENTA
;

-- 150
 CREATE OR REPLACE VIEW  VIEW_CALFISITF AS 
SELECT     PLP_CODSUC AS ITF_CODSUC,    PLP_FECHA  AS ITF_FECHA    FROM 
 DPDOCPROPROG     WHERE PLP_TIPDOC="ITF"
;

-- 151
 CREATE OR REPLACE VIEW  VIEW_NMHISMONMAXFCH AS 
SELECT    HMN_CODIGO      AS MAX_CODIGO, MIN(HMN_FECHA)  AS MAX_DESDE,  MAX(HMN_FECHA)  AS MAX_FECHA,  MAX(MID(CONCAT(HMN_FECHA,HMN_HORA),11,8)) AS MAX_HORA, COUNT(*) AS MAX_CANTID  FROM 
 DPHISMON 
 GROUP BY HMN_CODIGO 
 ORDER BY CONCAT(HMN_FECHA,HMN_HORA);

-- 152
 CREATE OR REPLACE VIEW  VIEW_NMHISMONMINFCH AS 
SELECT         HMN_CODIGO AS MIN_CODIGO,        HMN_FECHA  AS MIN_FECHA          FROM 
 DPHISMON         
 GROUP BY HMN_CODIGO         
 ORDER BY HMN_FECHA LIMIT 1
;

-- 153
 CREATE OR REPLACE VIEW  VIEW_DOCCLIVENTIPDOC AS 
SELECT           DOC_CODSUC AS UVC_CODSUC,       DOC_CODVEN AS UVC_CODVEN,       DOC_TIPDOC AS UVC_TIPDOC,       MIN(DOC_FECHA) AS UVC_FCHMIN,   MAX(DOC_FECHA) AS UVC_FCHMAX   FROM 
 DPDOCCLI       WHERE DOC_TIPTRA="D" AND DOC_ACT=1      
 GROUP BY DOC_CODSUC,DOC_CODVEN,DOC_TIPDOC      
 ORDER BY DOC_CODSUC,DOC_CODVEN
;

-- 154
 CREATE OR REPLACE VIEW  VIEW_DPDOCCLIDEFFLOW AS 
SELECT                     MPN_CODIGO AS FLU_CODIGO,                    MPN_DESCRI AS FLU_DESCRI,                    TEX_TIPDOC AS FLU_TIPORG,                TEX_TIPINI AS FLU_TIPINI,            TEX_TIPEXP AS FLU_TIPDES,                    TEX_DESDE  AS FLU_DESDE ,                TEX_EDIT   AS FLU_EDIT  ,              TEX_POS    AS FLU_POS              FROM 
 DPMODPROCDOCCLI                   
 INNER JOIN DPTIPDOCCLIEXP ON TEX_CODMOD=MPN_CODIGO                    WHERE MPN_ACTIVO=1                  
 ORDER BY MPN_CODIGO,TEX_POS
;

-- 155
 CREATE OR REPLACE VIEW  VIEW_GRUACTIVOS_CTA AS 
SELECT           GAC_CODIGO AS GSC_CODIGO    FROM 
 DPGRUACTIVOS         LEFT JOIN DPGRUACTIVOS_CTA ON CIC_CODIGO=GAC_CODIGO          WHERE GAC_ACTIVO AND CIC_CODIGO IS NULL
;

-- 156
 CREATE OR REPLACE VIEW  VIEW_GRUCTA_ACT AS 
SELECT  CIC_CTAMOD AS ACT_CTAMOD, CIC_CODIGO AS ACT_CODGRU, CIC_CUENTA AS GRU_CTAACT FROM 
 DPGRU_CTA  WHERE CIC_CODINT='CTAACT'
;

-- 157
 CREATE OR REPLACE VIEW  VIEW_GRUCTA_COM AS 
SELECT  CIC_CTAMOD AS COM_CTAMOD, CIC_CODIGO AS COM_CODGRU, CIC_CUENTA AS GRU_CTACOM FROM 
 DPGRU_CTA  WHERE CIC_CODINT='CTACOM'
;

-- 158
 CREATE OR REPLACE VIEW  VIEW_GRUCTA_COS AS 
SELECT  CIC_CTAMOD AS COS_CTAMOD, CIC_CODIGO AS COS_CODGRU, CIC_CUENTA AS GRU_CTACOS FROM 
 DPGRU_CTA  WHERE CIC_CODINT='CTACOS'
;

-- 159
 CREATE OR REPLACE VIEW  VIEW_GRUCTA_DVC AS 
SELECT  CIC_CTAMOD AS DVC_CTAMOD, CIC_CODIGO AS DVC_CODGRU, CIC_CUENTA AS GRU_CTADVC FROM 
 DPGRU_CTA  WHERE CIC_CODINT='CTADVC'
;

-- 160
 CREATE OR REPLACE VIEW  VIEW_GRUCTA_DVV AS 
SELECT  CIC_CTAMOD AS DVV_CTAMOD, CIC_CODIGO AS DVV_CODGRU, CIC_CUENTA AS GRU_CTADVV FROM 
 DPGRU_CTA  WHERE CIC_CODINT='CTADVV'
;

-- 161
 CREATE OR REPLACE VIEW  VIEW_GRUCTA_VTH AS 
SELECT  CIC_CTAMOD AS VTH_CTAMOD, CIC_CODIGO AS VTH_CODGRU, CIC_CUENTA AS GRU_CTAVTH FROM 
 DPGRU_CTA  WHERE CIC_CODINT='CTAVTH'
;

-- 162
 CREATE OR REPLACE VIEW  VIEW_GRUCTA_FIN AS 
SELECT  CIC_CTAMOD AS FIN_CTAMOD, CIC_CODIGO AS FIN_CODGRU, CIC_CUENTA AS GRU_CTAFIN FROM 
 DPGRU_CTA  WHERE CIC_CODINT='CTAFIN'
;

-- 163
 CREATE OR REPLACE VIEW  VIEW_GRUCTA_INI AS 
SELECT  CIC_CTAMOD AS INI_CTAMOD, CIC_CODIGO AS INI_CODGRU, CIC_CUENTA AS GRU_CTAINI FROM 
 DPGRU_CTA  WHERE CIC_CODINT='CTAINI'
;

-- 164
 CREATE OR REPLACE VIEW  VIEW_GRUCTA_VTA AS 
SELECT  CIC_CTAMOD AS VTA_CTAMOD, CIC_CODIGO AS VTA_CODGRU, CIC_CUENTA AS GRU_CTAVTA FROM 
 DPGRU_CTA  WHERE CIC_CODINT='CTAVTA'
;

-- 165
 CREATE OR REPLACE VIEW  VIEW_GRUCTA_VTE AS 
SELECT  CIC_CTAMOD AS VTE_CTAMOD, CIC_CODIGO AS VTE_CODGRU, CIC_CUENTA AS GRU_CTAVTE FROM 
 DPGRU_CTA  WHERE CIC_CODINT='CTAVTE'
;

-- 166
 CREATE OR REPLACE VIEW  VIEW_GRUCTA_VTP AS 
SELECT  CIC_CTAMOD AS VTP_CTAMOD, CIC_CODIGO AS VTP_CODGRU, CIC_CUENTA AS GRU_CTAVTP FROM 
 DPGRU_CTA  WHERE CIC_CODINT='CTAVTP'
;

-- 167
 CREATE OR REPLACE VIEW  VIEW_DPHISMON AS 
SELECT         HMN_CODIGO      AS HIS_CODIGO,        AVG(HMN_VALOR)  AS HIS_VALOR,      HMN_FECHA       AS HIS_FECHA        FROM 
 DPHISMON       
 GROUP BY HMN_CODIGO,HIS_FECHA        
 ORDER BY HMN_CODIGO,HMN_FECHA,HMN_HORA
;

-- 168
 CREATE OR REPLACE VIEW  VIEW_DPHISMON_MES AS 
SELECT  HMN_CODIGO       AS HMN_CODIGO, YEAR(HMN_FECHA)  AS HMN_ANO   , MONTH(HMN_FECHA) AS HMN_MES   , MAX(HMN_FECHA)   AS HMN_FECHA  FROM 
 dphismon 
 GROUP BY HMN_CODIGO,YEAR(HMN_FECHA),MONTH(HMN_FECHA) 
 ORDER BY HMN_CODIGO,YEAR(HMN_FECHA),MONTH(HMN_FECHA);

-- 169
 CREATE OR REPLACE VIEW  VIEW_PRECIOHISNAC AS 
SELECT      PRE_LISTA  AS PHI_LISTA,       PRE_CODIGO AS PHI_CODIGO,        MAX(CONCAT(PRE_FECHA,PRE_HORA)) AS PHI_FCHHOR        FROM 
 DPPRECIOSHIS        WHERE PRE_ORIGEN<>"USD"       
 GROUP BY PRE_CODIGO       
 ORDER BY PRE_LISTA,CONCAT(PRE_FECHA,PRE_HORA)
;

-- 170
 CREATE OR REPLACE VIEW  VIEW_CNDINQUILINOS AS 
SELECT CLI_CODIGO AS INQ_CODIGO,CLI_NOMBRE AS INQ_NOMBRE  FROM 
  DPCLIENTESREC  
 INNER JOIN DPCLIENTES ON CRC_CODIGO=CLI_CODIGO  
 GROUP BY CLI_CODIGO 
 ORDER BY CLI_CODIGO;

-- 171
 CREATE OR REPLACE VIEW  VIEW_INVINICIAL AS 
SELECT               MOV_CODSUC AS IIN_CODSUC,              MOV_CODALM AS IIN_CODALM,              MOV_CODIGO AS IIN_CODIGO,              MOV_UNDMED AS IIN_UNDMED,              MOV_CANTID AS IIN_CANTID,              MOV_COSTO  AS IIN_COSTO,     MOV_MTODIV AS IIN_COSDIV,           MOV_FECHA  AS IIN_FECHA,        MOV_TOTAL  AS IIN_TOTAL              FROM 
 DPMOVINV              WHERE MOV_APLORG="2" AND MOV_INVACT=1             
 ORDER BY MOV_CODIGO,MOV_CODSUC,MOV_CODALM
;

-- 172
 CREATE OR REPLACE VIEW  VIEW_LOTESPRECIOS AS 
SELECT MOV_CODSUC AS LOT_CODSUC,        MOV_CODIGO AS LOT_CODIGO,        MOV_LOTE   AS LOT_LOTE  ,        MOV_CAPAC  AS LOT_CAPAC ,        MOV_COSTO  AS LOT_COSTO ,        MOV_PRECIO AS LOT_PRECIO,        MOV_FCHVEN AS LOT_FCHVEN           FROM 
    DPMOVINV        WHERE MOV_FISICO=1  AND MOV_LOTE<>""    
 GROUP BY MOV_CODSUC,MOV_CODIGO,MOV_LOTE,MOV_CAPAC,MOV_COSTO,MOV_PRECIO,MOV_FCHVEN
;

-- 173
 CREATE OR REPLACE VIEW  VIEW_LOTESINVFIS AS 
SELECT                                           MOV_CODSUC    AS LOT_CODSUC,                                        MOV_CODIGO    AS LOT_CODIGO,                                  MOV_LOTE      AS LOT_NUMERO,                              
 SUM(MOV_CANTID*MOV_FISICO) AS LOT_CANTID,                                         
 SUM(MOV_CXUND *MOV_FISICO) AS LOT_CXUND,                                         
 SUM(MOV_PESO  *MOV_FISICO) AS LOT_PESO,                          
 SUM(MOV_MTOCOM*MOV_FISICO) AS LOT_MTOCOM,          
 SUM(IF(MOV_FISICO =1,MOV_PESO  ,0)) AS LOT_PESENT,            
 SUM(IF(MOV_FISICO=-1,MOV_PESO  ,0)) AS LOT_PESSAL,          
 SUM(IF(MOV_FISICO =1 AND MOV_PESO=0,MOV_CANTID,0)) AS LOT_CANENT,            
 SUM(IF(MOV_FISICO=-1 AND MOV_PESO=0,MOV_CANTID,0)) AS LOT_CANSAL,                           CONCAT(LEFT(MOV_LOTE,4),"-",MID(MOV_LOTE,5,2),"-",RIGHT(MOV_LOTE,2)) AS LOT_FECHA                                          FROM 
 DPMOVINV                                           WHERE MOV_INVACT=1 AND MOV_FISICO<>0 AND MOV_LOTE<>""                                          
 GROUP BY MOV_CODSUC,MOV_CODIGO,MOV_LOTE                                       
 ORDER BY MOV_CODSUC,MOV_CODIGO,MOV_LOTE
;

-- 174
 CREATE OR REPLACE VIEW  VIEW_LOTESINVPACK AS 
SELECT                                               MOV_CODSUC    AS LOT_CODSUC,                                            MOV_CODIGO    AS LOT_CODIGO,                                      MOV_LOTE      AS LOT_LOTE,                                   MOV_FECHA     AS LOT_FECHA,                     MOV_UNDMED    AS LOT_UNDMED,                   MOV_CODPER    AS LOT_CODUBI,     MOV_CODCTA    AS LOT_NUMPED,                
 SUM(MOV_MTOCOM*MOV_FISICO) AS LOT_PESBRU,                                               
 SUM(MOV_PRECIO*MOV_FISICO) AS LOT_PESTAR,                                               
 SUM(MOV_CANTID-MOV_EXPORT) AS LOT_PESNET,                                               
 SUM(MOV_CXUND *MOV_FISICO) AS LOT_CANCES,                                               
 SUM(MOV_BANDA *MOV_FISICO) AS LOT_CANUND,         
 SUM(MOV_EXPORT) AS LOT_EXPORT     FROM 
 DPMOVINV                                               WHERE MOV_INVACT=1 AND MOV_FISICO<>0 AND MOV_LOTE<>"" AND MOV_CODCTA<>""                                             
 GROUP BY MOV_CODSUC,MOV_CODIGO,MOV_LOTE,MOV_UNDMED                                           HAVING LOT_CANCES<>0                     
 ORDER BY MOV_CODSUC,MOV_CODIGO,MOV_LOTE,MOV_UNDMED
;

-- 175
 CREATE OR REPLACE VIEW  VIEW_INVMEDPRESENTACION AS 
SELECT           IME_CODIGO,          IME_UNDMED,          IME_CANTID           FROM 
 DPINVMED        
 INNER JOIN DPINV ON IME_CODIGO=INV_CODIGO AND INV_ESTADO="A"          WHERE IME_MEDPRE=1         
 GROUP BY IME_CODIGO,IME_UNDMED
;

-- 176
 CREATE OR REPLACE VIEW  VIEW_DPMEMOINVTIPDOCCLI AS 
SELECT     PXD_CODIGO AS MXT_CODIGO,  PXD_TIPDOC AS MXT_TIPDOC,  PXD_NUMMEM AS MXT_NUMMEM,    MEM_MEMO   AS MXT_MEMO    FROM 
    DPINVTIPDOCCLI   
 INNER JOIN DPMEMO ON PXD_NUMMEM>0 AND PXD_NUMMEM=MEM_NUMERO     WHERE MEM_NUMERO IS NOT NULL OR LENGTH(MEM_NUMERO)>0 
 ORDER BY MXT_CODIGO
;

-- 177
 CREATE OR REPLACE VIEW  VIEW_DPDIARIO_MES AS 
SELECT   DIA_ANO AS FCH_ANO,  DIA_MES AS FCH_MES,  MIN(date_add(DIA_FECHA, INTERVAL -1 DAY)) AS FCH_FCHANT,  MIN(DIA_FECHA) AS FCH_DESDE,  MAX(DIA_FECHA) AS FCH_HASTA,  DIA_CMES       AS FCH_CMES,  MAX(HMN_FECHA) AS FCH_MAXDIV,  HMN_CODIGO     AS FCH_CODMON,  IPC_TASA       AS FCH_IPC,  IPC_INPC       AS FCH_INPC  FROM 
 DPDIARIO  LEFT JOIN dphismon ON YEAR(HMN_FECHA)=YEAR(DIA_FECHA) AND MONTH(HMN_FECHA)=MONTH(DIA_FECHA) AND HMN_CODIGO="DBC"  LEFT JOIN admconfig51.dpipc ON YEAR(DIA_FECHA)=IPC_ANO AND MONTH(DIA_FECHA)=IPC_MES 
 GROUP BY DIA_ANO,DIA_MES  
 ORDER BY DIA_ANO,DIA_MES;

-- 178
 CREATE OR REPLACE VIEW  VIEW_INVCATCONCAT AS 
SELECT CXI_CODINV,GROUP_CONCAT(CXI_CODSAT) AS CXI_CODSAT  FROM 
 dpcatsat_inv 
 GROUP BY CXI_CODINV 
 ORDER BY CXI_CODINV;

-- 179
 CREATE OR REPLACE VIEW  VIEW_DOCPROCTAMTO AS 
SELECT          CCD_CODSUC AS CCS_CODSUC,         CCD_TIPDOC AS CCS_TIPDOC,         CCD_CODIGO AS CCS_CODIGO,         CCD_NUMERO AS CCS_NUMERO,        
 SUM(IF(CCD_TIPIVA<>"EX", CCD_MONTO, 0)) AS CCS_MONTO,   
 SUM(IF(CCD_TIPIVA="EX" , CCD_MONTO, 0)) AS CCS_MTOEXE     FROM 
 DPDOCPROCTA         WHERE CCD_ACT=1        
 GROUP BY CCD_CODSUC,CCD_TIPDOC,CCD_CODIGO,CCD_NUMERO      
 ORDER BY CCD_CODSUC,CCD_TIPDOC,CCD_CODIGO,CCD_NUMERO
;

-- 180
 CREATE OR REPLACE VIEW  VIEW_DPCAJMOVORGREC AS 
SELECT             CAJ_CODSUC,            CAJ_DOCASO,           
 SUM(CAJ_MONTO) AS CAJ_MONTO,    MAX(CAJ_FECHA) AS CAJ_FECHA           FROM 
 DPCAJAMOV            WHERE CAJ_ORIGEN="REC" AND CAJ_ACT=1           
 GROUP BY CAJ_CODSUC,CAJ_DOCASO           
 ORDER BY CAJ_CODSUC,CAJ_DOCASO
;

-- 181
 CREATE OR REPLACE VIEW  VIEW_DPCAJMOVORGPAG AS 
SELECT           CAJ_CODSUC,          CAJ_DOCASO,         
 SUM(CAJ_MONTO) AS CAJ_MONTO,  MAX(CAJ_FECHA) AS CAJ_FECHA         FROM 
 DPCAJAMOV          WHERE CAJ_ORIGEN="PAG" AND CAJ_ACT=1         
 GROUP BY CAJ_CODSUC,CAJ_DOCASO         
 ORDER BY CAJ_CODSUC,CAJ_DOCASO
;

-- 182
 CREATE OR REPLACE VIEW  VIEW_DPMOVINVCLIORGDES AS 
SELECT  MOV_CODSUC AS ORG_SUCDES,  MOV_TIPDOC AS ORG_TIPDES,  MOV_DOCUME AS ORG_DOCDES,  MOV_CODIGO AS ORG_CODIGO,  MOV_CODCTA AS ORG_CODCLI,  MOV_ITEM   AS ORG_ITMDES,  MOV_FECHA  AS ORG_FCHDES,  MOV_CANTID AS ORG_CANDES,  MOV_CXUND  AS ORG_CXUDES,  MOV_PESO   AS ORG_PESDES,  MOV_PRECIO AS ORG_PREDES,  MOV_COSTO  AS ORG_COSDES,  MOV_TOTAL  AS ORG_TOTDES,  MOV_MTODIV AS ORG_TOTDIV,  MOV_ASOTIP AS ORG_TIPORG,  MOV_ASODOC AS ORG_DOCORG,  MOV_ITEM_A AS ORG_ITMORG,  DOC_VALCAM AS ORG_VALCAM,  DOC_RECNUM AS ORG_RECNUM,  DOC_GIRNUM AS ORG_CODMOT   FROM 
 dpmovinv  
 INNER JOIN dpdoccli ON MOV_CODSUC=DOC_CODSUC AND MOV_TIPDOC=DOC_TIPDOC AND MOV_DOCUME=DOC_NUMERO AND DOC_TIPTRA="D" AND DOC_ACT=1  WHERE MOV_APLORG="V" AND MOV_ASOTIP<>"" AND MOV_ASODOC<>"" AND MOV_ITEM_A<>""  
 ORDER BY MOV_CODSUC,MOV_TIPDOC,MOV_DOCUME  ;

-- 183
 CREATE OR REPLACE VIEW  VIEW_DPMOVBCORGPAG AS 
SELECT              MOB_CODSUC,          MOB_DOCASO,             
 SUM(MOB_MONTO) AS MOB_MONTO,  MAX(MOB_FECHA) AS MOB_FECHA  FROM 
 DPCTABANCOMOV             WHERE MOB_ORIGEN="PAG" AND MOB_ACT=1           
 GROUP BY MOB_CODSUC,MOB_DOCASO         
 ORDER BY MOB_CODSUC,MOB_DOCASO
;

-- 184
 CREATE OR REPLACE VIEW  VIEW_DPMOVBCORGREC AS 
SELECT                    MOB_CODSUC,                MOB_DOCASO,                   
 SUM(MOB_MONTO) AS MOB_MONTO,     
 SUM(MOB_MONTO/IF(MOB_VALCAM=1,0,MOB_VALCAM)) AS MOB_MTODIV,          MAX(MOB_FECHA) AS MOB_FECHA        FROM 
 DPCTABANCOMOV                   WHERE MOB_ORIGEN="REC" AND MOB_ACT=1                 
 GROUP BY MOB_CODSUC,MOB_DOCASO               
 ORDER BY MOB_CODSUC,MOB_DOCASO
;

-- 185
 CREATE OR REPLACE VIEW  VIEW_DPCAJAMOVDEP AS 
SELECT       CAJ_CODSUC AS DEP_CODSUC,      CAJ_DOCASO AS DEP_DOCASO      FROM 
 DPCAJAMOV        WHERE CAJ_ORIGEN="REC" AND CAJ_DOCASO<>""       
 ORDER BY CAJ_CODSUC,CAJ_DOCASO
;

-- 186
 CREATE OR REPLACE VIEW  VIEW_DOCCLIFAVNETO AS 
SELECT                                         DOC_CODSUC AS FAV_CODSUC,                                        DOC_TIPDOC AS FAV_TIPDOC,                                        DOC_NUMERO AS FAV_NUMERO,                                        DOC_CODIGO AS FAV_CODIGO,                                  DOC_CODVEN AS FAV_CODVEN,                                        MIN(DOC_FECHA)  AS FAV_FECHA,                      MIN(DOC_FCHVEN) AS FAV_FCHVEN,    
 SUM(DOC_NETO*DOC_CXC) AS FAV_SALDO,                                       
 SUM(IF(DOC_TIPTRA="D",DOC_BASNET*IF(DOC_TIPDOC="CHD",1,DOC_CXC),0)) AS FAV_BASNET,                                       
 SUM(IF(DOC_TIPTRA="D",DOC_NETO  *IF(DOC_TIPDOC="CHD",1,DOC_CXC),0)) AS FAV_NETO,  DOC_MTOIVA      AS FAV_MTOIVA                                                                             FROM 
 DPDOCCLI                                        WHERE (DOC_TIPDOC="FAV" OR DOC_TIPDOC="CHD" OR DOC_TIPDOC="CRE" OR DOC_TIPDOC="DEV") AND DOC_ACT=1                                       
 GROUP BY DOC_CODSUC,DOC_TIPDOC,DOC_NUMERO                        HAVING (SUM(DOC_NETO*DOC_CXC)=0 AND (DOC_TIPDOC="FAV" OR DOC_TIPDOC="CHD")) OR (DOC_TIPDOC="CHD" OR DOC_TIPDOC="CRE" OR DOC_TIPDOC="DEV")                       
 ORDER BY DOC_CODSUC,DOC_TIPDOC,DOC_NUMERO
;

-- 187
 CREATE OR REPLACE VIEW  VIEW_DPTIPDOCCLINUM AS 
SELECT  RIGHT(DAT_GROUP,6) AS TDC_CODSUC,  LEFT(DAT_NAME,3)   AS TDC_TIPDOC,  DAT_VALUE          AS TDC_NUMERO  FROM 
 DPDATASET  WHERE LEFT(DAT_GROUP,5)="SUC_V" AND RIGHT(DAT_NAME,6)="NUMERO";

-- 188
 CREATE OR REPLACE VIEW  VIEW_DPTIPDOCPRONUM AS 
SELECT  RIGHT(DAT_GROUP,6) AS TDC_CODSUC,  LEFT(DAT_NAME,3)   AS TDC_TIPDOC,  DAT_VALUE          AS TDC_NUMERO  FROM 
 DPDATASET  WHERE LEFT(DAT_GROUP,5)="SUC_P" AND RIGHT(DAT_NAME,6)="NUMERO";

-- 189
 CREATE OR REPLACE VIEW  VIEW_OBJFIN_COSTO AS 
SELECT OBD_FECHA  AS COS_FECHA,OBD_MONTO  AS COS_MONTO,OBD_MTOEJE AS COS_MTOEJE FROM 
 dpobjfin_diario WHERE OBD_CODIGO="Costo";

-- 190
 CREATE OR REPLACE VIEW  VIEW_OBJFIN_GANANCIA AS 
SELECT OBD_FECHA  AS GAN_FECHA,OBD_MONTO  AS GAN_MONTO,OBD_MTOEJE AS GAN_MTOEJE FROM 
 dpobjfin_diario WHERE OBD_CODIGO="Ganancia";

-- 191
 CREATE OR REPLACE VIEW  VIEW_OBJFIN_GASTO AS 
SELECT OBD_FECHA  AS GAS_FECHA,OBD_MONTO  AS GAS_MONTO,OBD_MTOEJE AS GAS_MTOEJE FROM 
 dpobjfin_diario WHERE OBD_CODIGO="Gasto";

-- 192
 CREATE OR REPLACE VIEW  VIEW_OBJFINMEN AS 
SELECT              OBD_CODIGO,             OBD_ID,              OBD_ID_SUB,             OBD_IDSUBC,             DIA_MES,      DIA_ANO,          MIN(OBD_FECHA)  AS OBD_DESDE,               MAX(OBD_FECHA)  AS OBD_HASTA,              
 SUM(OBD_MONTO)  AS OBD_MONTO,             
 SUM(OBD_HABIL)  AS OBD_HABIL                 FROM 
 DPOBJFIN_DIARIO              
 INNER JOIN DPDIARIO ON OBD_FECHA=DIA_FECHA             WHERE OBD_CODIGO="VTAGEN" AND OBD_COMPAR=0             
 GROUP BY OBD_CODIGO,OBD_ID,OBD_ID_SUB,OBD_IDSUBC,DIA_ANO,DIA_MES             
 ORDER BY DIA_ANO,DIA_MES,OBD_CODIGO,OBD_ID,OBD_ID_SUB,OBD_IDSUBC
;

-- 193
 CREATE OR REPLACE VIEW  VIEW_OBJFINSEM AS 
SELECT            OBD_CODIGO,           OBD_ID,            OBD_ID_SUB,           OBD_IDSUBC,           DIA_SEMANA,   DIA_ANO,           MIN(OBD_FECHA)  AS OBD_DESDE,             MAX(OBD_FECHA)  AS OBD_HASTA,            
 SUM(OBD_MONTO)  AS OBD_MONTO,           
 SUM(OBD_HABIL)  AS OBD_HABIL               FROM 
 DPOBJFIN_DIARIO            
 INNER JOIN DPDIARIO ON OBD_FECHA=DIA_FECHA           WHERE OBD_CODIGO="VTAGEN" AND OBD_COMPAR=0           
 GROUP BY OBD_CODIGO,OBD_ID,OBD_ID_SUB,OBD_IDSUBC,DIA_ANO,DIA_SEMANA           
 ORDER BY OBD_CODIGO,OBD_ID,OBD_ID_SUB,OBD_IDSUBC,DIA_ANO,DIA_SEMANA
;

-- 194
 CREATE OR REPLACE VIEW  VIEW_OBJFIN_VENTA AS 
SELECT OBD_FECHA  AS VTA_FECHA,OBD_MONTO  AS VTA_MONTO,OBD_MTOEJE AS VTA_MTOEJE FROM 
 dpobjfin_diario WHERE OBD_CODIGO="Venta General";

-- 195
 CREATE OR REPLACE VIEW  VIEW_OBJFIN_VENTA_AAMM AS 
SELECT  YEAR(OBD_FECHA)  AS VTA_ANO, MONTH(OBD_FECHA) AS VTA_MES,
 SUM(OBD_MONTO)   AS VTA_MONTO,
 SUM(OBD_MTOEJE)  AS VTA_MTOEJE FROM 
 dpobjfin_diario WHERE OBD_CODIGO="Venta General" 
 GROUP BY YEAR(OBD_FECHA),MONTH(OBD_FECHA) 
 ORDER BY YEAR(OBD_FECHA),MONTH(OBD_FECHA);

-- 196
 CREATE OR REPLACE VIEW  VIEW_MOVINVLIBINV AS 
SELECT MOV_CODIGO  AS MIN_CODIGO, YEAR(MOV_FECHA)  AS MIN_ANO, MONTH(MOV_FECHA) AS MIN_MES, COUNT(*)         AS MIN_CANTID  FROM 
 dpmovinv 
 INNER JOIN dpinv ON MOV_CODIGO=INV_CODIGO 
 INNER JOIN dpinvutiliz ON INV_UTILIZ=UTL_CODIGO AND UTL_LIBINV=1  WHERE MOV_CONTAB<>0 AND MOV_INVACT=1  
 GROUP BY MOV_CODIGO,YEAR(MOV_FECHA),MONTH(MOV_FECHA) 
 ORDER BY MOV_CODIGO,YEAR(MOV_FECHA),MONTH(MOV_FECHA);

-- 197
 CREATE OR REPLACE VIEW  VIEW_DPMOVINVORGPDC AS 
SELECT             MOV_CODSUC AS PDC_CODSUC,            MOV_ASODOC AS PDC_DOCUME,         MOV_CODIGO AS PDC_CODIGO,          
 SUM(IF(MOV_TIPDOC="OCA",MOV_CANTID,0))            AS PDC_OCACAN,      
 SUM(IF(MOV_TIPDOC="OCA",MOV_EXPORT,0))            AS PDC_OCAEXP,            
 SUM(IF(MOV_TIPDOC="OCA",MOV_TOTAL ,0))            AS PDC_OCATOT,           
 SUM(IF(MOV_TIPDOC="OCA",MOV_CANTID*MOV_MTODIV,0)) AS PDC_OCADIV,  
 SUM(IF(MOV_TIPDOC="NRC",MOV_CANTID,0))            AS PDC_NRCCAN,      
 SUM(IF(MOV_TIPDOC="NRC",MOV_EXPORT,0))            AS PDC_NRCEXP,            
 SUM(IF(MOV_TIPDOC="NRC",MOV_TOTAL ,0))            AS PDC_NRCTOT,           
 SUM(IF(MOV_TIPDOC="NRC",MOV_CANTID*MOV_MTODIV,0)) AS PDC_NRCDIV, 
 SUM(IF(MOV_TIPDOC="ORC",MOV_CANTID,0))            AS PDC_ORCCAN,   
 SUM(IF(MOV_TIPDOC="ORC",MOV_EXPORT,0))            AS PDC_ORCEXP,                    
 SUM(IF(MOV_TIPDOC="ORC",MOV_TOTAL ,0))            AS PDC_ORCTOT,           
 SUM(IF(MOV_TIPDOC="SCT",MOV_CANTID*MOV_MTODIV,0)) AS PDC_ORCDIV,           
 SUM(IF(MOV_TIPDOC="SCT",MOV_CANTID,0))            AS PDC_SCTCAN,           
 SUM(IF(MOV_TIPDOC="SCT",MOV_EXPORT,0))            AS PDC_SCTEXP,            
 SUM(IF(MOV_TIPDOC="SCT",MOV_TOTAL ,0))            AS PDC_SCTTOT,           
 SUM(IF(MOV_TIPDOC="SCT",MOV_CANTID*MOV_MTODIV,0)) AS PDC_SCTDIV            FROM 
 dpmovinv            WHERE MOV_APLORG="C" AND MOV_ASOTIP="PDC" AND MOV_INVACT=1            
 GROUP BY MOV_CODSUC,MOV_ASODOC,MOV_CODIGO
;

-- 198
 CREATE OR REPLACE VIEW  VIEW_DOCCLIPAG AS 
SELECT  DOC_CODSUC      AS PAG_CODSUC, DOC_TIPDOC      AS PAG_TIPDOC, DOC_NUMERO      AS PAG_NUMERO,
 SUM(DOC_NETO)   AS PAG_NETO, 
 SUM(DOC_MTOCOM) AS PAG_MTODIF,
 SUM(DOC_NETO/IF(DOC_VALCAM>=1,DOC_VALCAM,0)) AS PAG_MTODIV,  COUNT(*)        AS PAG_CUANTOS,  DOC_RECNUM      AS PAG_RECNUM,   DOC_CBTNUM      AS PAG_CBTNUM,   DOC_FECHA       AS PAG_FECHA ,   AVG(DOC_VALCAM) AS PAG_VALCAM  FROM 
 DPDOCCLI   WHERE DOC_TIPTRA="P" AND DOC_ACT=1 
 GROUP BY DOC_CODSUC,DOC_TIPDOC,DOC_NUMERO 
 ORDER BY DOC_CODSUC,DOC_TIPDOC,DOC_NUMERO
;

-- 199
 CREATE OR REPLACE VIEW  VIEW_DOCPROPAG AS 
SELECT  DOC_CODSUC AS PAG_CODSUC,  DOC_TIPDOC AS PAG_TIPDOC,  DOC_CODIGO AS PAG_CODIGO,  DOC_NUMERO AS PAG_NUMERO, 
 SUM(DOC_NETO) AS PAG_NETO,
 SUM(ROUND(DOC_NETO/IF(DOC_VALCAM>1,DOC_VALCAM,0),2)) AS PAG_MTODIV,
 SUM(DOC_NETO*DOC_CXP) AS PAG_NETOCXP,
 SUM(DOC_MTOCOM) AS PAG_MTODIF, AVG(DOC_VALCAM) AS PAG_VALCAM , MAX(DOC_PAGNUM) AS PAG_PAGNUM ,  COUNT(*)      AS PAG_CUANTOS  FROM 
 DPDOCPRO  WHERE DOC_TIPTRA="P" AND DOC_ACT=1 
 GROUP BY DOC_CODSUC,DOC_TIPDOC,DOC_CODIGO,DOC_NUMERO 
 ORDER BY DOC_CODSUC,DOC_TIPDOC,DOC_CODIGO,DOC_NUMERO;

-- 200
 CREATE OR REPLACE VIEW  VIEW_DPPEDIDOS_EP AS 
SELECT       DOC_CODSUC AS PDE_CODSUC,      DOC_MTOCOM AS PDE_ID     FROM 
 DPDOCCLI       WHERE DOC_TIPDOC="PED"  AND DOC_MTOCOM>0     
 ORDER BY DOC_CODSUC,DOC_ANUFIS
;

-- 201
 CREATE OR REPLACE VIEW  VIEW_DOCCLIPED AS 
SELECT    DOC_CODSUC AS PED_CODSUC,     DOC_NUMERO AS PED_NUMERO,    DOC_CODIGO AS PED_CODIGO,    DOC_FECHA  AS PED_FECHA,    DOC_FCHVEN AS PED_FCHENT,    DOC_NETO   AS PED_NETO,    DOC_ESTADO AS PED_ESTADO,  DOC_CODVEN AS PED_CODVEN    FROM 
 DPDOCCLI    WHERE DOC_TIPDOC="PED" AND DOC_ACT=1   
 ORDER BY DOC_CODSUC,DOC_NUMERO
;

-- 202
 CREATE OR REPLACE VIEW  VIEW_PEDIDOSXFACTURAR AS 
SELECT                 MOV_DOCUME AS PED_NUMERO,                CLI_NOMBRE AS PED_NOMBRE,                MOV_CODCTA AS PED_CODCTA,                MOV_FECHA  AS PED_FECHA,          DOC_FCHVEN AS PED_FCHVEN,      DOC_CODVEN AS PED_CODVEN,           
 SUM(MOV_CANTID) AS PED_CANTID,                 
 SUM(MOV_EXPORT) AS PED_EXPORT,                 
 SUM(MOV_CANTID-MOV_EXPORT) AS PED_PENDTE,                 
 SUM(MOV_TOTAL) AS PED_TOTAL,                 
 SUM((MOV_TOTAL/MOV_CANTID)*(MOV_CANTID-MOV_EXPORT))  AS PED_TOTEXP                   FROM 
  DPMOVINV                 
 INNER JOIN DPCLIENTES ON MOV_CODCTA=CLI_CODIGO                 
 INNER JOIN DPDOCCLI   ON MOV_CODSUC=DOC_CODSUC AND MOV_TIPDOC=DOC_TIPDOC AND MOV_DOCUME=DOC_NUMERO            WHERE MOV_APLORG="V" AND MOV_TIPDOC="PED" AND MOV_INVACT=1                 
 GROUP BY MOV_DOCUME                  HAVING
 SUM(MOV_CANTID-MOV_EXPORT)>0
;

-- 203
 CREATE OR REPLACE VIEW  VIEW_INVLOTESPRECIOS AS 
SELECT                             MOV_CODSUC AS LOT_CODSUC,   MOV_CODALM AS LOT_CODALM,                           MOV_CODIGO AS LOT_CODIGO,                            MOV_LOTE   AS LOT_LOTE  ,           MOV_FECHA  AS LOT_FECHA ,          MOV_FCHVEN AS LOT_FCHVEN,                            MOV_PRECIO AS LOT_PRECIO,                    MOV_COSTO  AS LOT_COSTO ,                  MOV_CANTID AS LOT_CANTID                            FROM 
  DPMOVINV                              WHERE MOV_FISICO>0   AND MOV_INVACT=1                           
 GROUP BY MOV_CODSUC,MOV_CODALM,MOV_CODIGO,MOV_LOTE,MOV_FCHVEN,MOV_PRECIO                       
 ORDER BY MOV_CODSUC,MOV_CODALM,MOV_CODIGO,MOV_LOTE,MOV_FCHVEN
;

-- 204
 CREATE OR REPLACE VIEW  VIEW_INVCTA_ACT AS 
SELECT  CIC_CTAMOD AS ACT_CTAMOD, CIC_CODIGO AS ACT_CODINV, CIC_CUENTA AS INV_CTAACT FROM 
 DPINV_CTA  WHERE CIC_CODINT="CTAACT";

-- 205
 CREATE OR REPLACE VIEW  VIEW_INVCTA_COM AS 
SELECT  CIC_CTAMOD AS COM_CTAMOD, CIC_CODIGO AS COM_CODINV, CIC_CUENTA AS INV_CTACOM FROM 
 DPINV_CTA  WHERE CIC_CODINT="CTACOM";

-- 206
 CREATE OR REPLACE VIEW  VIEW_INVCTA_COS AS 
SELECT  CIC_CTAMOD AS COS_CTAMOD, CIC_CODIGO AS COS_CODINV, CIC_CUENTA AS INV_CTACOS FROM 
 DPINV_CTA  WHERE CIC_CODINT="CTACOS";

-- 207
 CREATE OR REPLACE VIEW  VIEW_INVCTA_DVC AS 
SELECT  CIC_CTAMOD AS DVC_CTAMOD, CIC_CODIGO AS DVC_CODINV, CIC_CUENTA AS INV_CTADVC FROM 
 DPINV_CTA  WHERE CIC_CODINT="CTADVC";

-- 208
 CREATE OR REPLACE VIEW  VIEW_INVCTA_DVV AS 
SELECT  CIC_CTAMOD AS DVV_CTAMOD, CIC_CODIGO AS DVV_CODINV, CIC_CUENTA AS INV_CTADVV FROM 
 DPINV_CTA  WHERE CIC_CODINT="CTADVV";

-- 209
 CREATE OR REPLACE VIEW  VIEW_INVCTA_VTH AS 
SELECT  CIC_CTAMOD AS VTH_CTAMOD, CIC_CODIGO AS VTH_CODINV, CIC_CUENTA AS INV_CTAVTH FROM 
 DPINV_CTA  WHERE CIC_CODINT="CTAVTH";

-- 210
 CREATE OR REPLACE VIEW  VIEW_INVCTA_FIN AS 
SELECT  CIC_CTAMOD AS FIN_CTAMOD, CIC_CODIGO AS FIN_CODINV, CIC_CUENTA AS INV_CTAFIN FROM 
 DPINV_CTA  WHERE CIC_CODINT="CTAFIN";

-- 211
 CREATE OR REPLACE VIEW  VIEW_INVCTA_INI AS 
SELECT  CIC_CTAMOD AS INI_CTAMOD, CIC_CODIGO AS INI_CODINV, CIC_CUENTA AS INV_CTAINI FROM 
 DPINV_CTA  WHERE CIC_CODINT="CTAINI";

-- 212
 CREATE OR REPLACE VIEW  VIEW_INVCTA_VTA AS 
SELECT  CIC_CTAMOD AS VTA_CTAMOD, CIC_CODIGO AS VTA_CODINV, CIC_CUENTA AS INV_CTAVTA FROM 
 DPINV_CTA  WHERE CIC_CODINT="CTAVTA";

-- 213
 CREATE OR REPLACE VIEW  VIEW_INVCTA_VTE AS 
SELECT  CIC_CTAMOD AS VTE_CTAMOD, CIC_CODIGO AS VTE_CODINV, CIC_CUENTA AS INV_CTAVTE FROM 
 DPINV_CTA  WHERE CIC_CODINT="CTAVTE";

-- 214
 CREATE OR REPLACE VIEW  VIEW_INVCTA_VTP AS 
SELECT  CIC_CTAMOD AS VTP_CTAMOD, CIC_CODIGO AS VTP_CODINV, CIC_CUENTA AS INV_CTAVTP FROM 
 DPINV_CTA  WHERE CIC_CODINT="CTAVTP";

-- 215
 CREATE OR REPLACE VIEW  VIEW_INVPRECANT AS 
SELECT     PRE_CODIGO AS PMP_CODIGO,    COUNT(*)   AS PMP_CANTID    FROM 
 DPPRECIOS    
 GROUP BY PRE_CODIGO    HAVING PMP_CANTID>1
;

-- 216
 CREATE OR REPLACE VIEW  VIEW_INVMEDCANT AS 
SELECT                         IME_CODIGO AS MXP_CODIGO,                        COUNT(*)   AS MXP_CANTID                        FROM 
 DPINVMED                          
 INNER JOIN DPINV ON IME_CODIGO=INV_CODIGO                         WHERE INV_ESTADO="A"                                   
 GROUP BY IME_CODIGO                        HAVING MXP_CANTID>1
;

-- 217
 CREATE OR REPLACE VIEW  VIEW_DPINVXCOMPRA AS 
SELECT                   MOV_CODSUC AS UCP_CODSUC,                  MOV_CODIGO AS UCP_CODIGO  FROM 
 DPMOVINV                  WHERE MOV_APLORG="C" AND MOV_INVACT=1          
 GROUP BY MOV_CODSUC,MOV_CODIGO 
 ORDER BY MOV_CODSUC,MOV_CODIGO      ,MOV_CODCTA
;

-- 218
 CREATE OR REPLACE VIEW  VIEW_PRODUCTOS AS 
SELECT INV_CODIGO AS id,INV_GRUPO  AS id_categoria,INV_CODIGO AS codigo,INV_DESCRI AS descripcion,INV_OBS1   AS imagen,  INV_COSADQ AS precio_compra,  IF(PRE_PRECIO IS NULL,0,PRE_PRECIO) AS precio_venta, 0          AS ventas,  INV_FCHACT AS fecha  FROM 
 dpinv  LEFT JOIN dpprecios ON PRE_CODIGO=INV_CODIGO AND PRE_LISTA="A" AND PRE_UNDMED="UND";

-- 219
 CREATE OR REPLACE VIEW  VIEW_INVCOMPPROD AS 
SELECT                      COM_CODINV,                     INV_DESCRI                 AS COM_DESCRI,          
 SUM(INV_COSMER*COM_CANTID) AS COM_COSTO,     
 SUM(INV_COSFOB*COM_CANTID) AS COM_COSFOB,           COUNT(*)   AS COM_CANTID                     FROM 
 DPCOMPPRODUCCION                    
 INNER JOIN DPINV ON COM_CODINV=INV_CODIGO     
 GROUP BY COM_CODINV                       
 ORDER BY COM_CODINV
;

-- 220
 CREATE OR REPLACE VIEW  VIEW_DPPROVEEDORDPINV AS 
SELECT                 MOV_CODIGO AS INV_CODIGO,                MOV_CODCTA AS PRO_CODIGO,          PRO_NOMBRE,          PRO_RIF,PRO_TIPPER,PRO_CONESP,PRO_RETIVA,PRO_RESIDE,PRO_CREFIS,MIN(MOV_FECHA) AS PRO_DESDE,MAX(MOV_FECHA) AS PRO_HASTA        FROM 
 DPMOVINV            
 INNER JOIN DPPROVEEDOR ON MOV_CODCTA=PRO_CODIGO                 WHERE  MOV_APLORG="C" AND MOV_INVACT=1                
 GROUP BY MOV_CODIGO,MOV_CODCTA               
 ORDER BY MOV_CODIGO
;

-- 221
 CREATE OR REPLACE VIEW  VIEW_DPPROVXINV AS 
SELECT   MOV_CODSUC AS UCP_CODSUC,  MOV_CODIGO AS UCP_CODIGO,  MOV_CODCTA AS UCP_CODPRO,  MAX(MOV_FECHA) AS UCP_FECHA  FROM 
 DPMOVINV 
 INNER JOIN DPTIPDOCPRO ON TDC_TIPO=MOV_TIPDOC AND TDC_ESTCOM=1  WHERE MOV_APLORG="C" AND MOV_INVACT=1 
 GROUP BY MOV_CODSUC,MOV_CODCTA,MOV_CODIGO 
 ORDER BY MOV_CODSUC,MOV_CODCTA,MOV_CODIGO;

-- 222
 CREATE OR REPLACE VIEW  VIEW_DPPROVEEDORBCO AS 
SELECT CBP_CODIGO AS CBP_CODIGO,COUNT(*) AS CBP_CUANTOS FROM 
 dpproveedorbco
 GROUP BY CBP_CODIGO
;

-- 223
 CREATE OR REPLACE VIEW  VIEW_PROVEEDOREXPOR AS 
SELECT   PRO_CODIGO AS PEX_CODIGO,  PRO_RIF    AS PEX_RIF,  PRO_NOMBRE AS PEX_NOMBRE  FROM 
 DPPROVEEDOR  WHERE PRO_TIPO="Exporádicos" 
 ORDER BY PRO_RIF
;

-- 224
 CREATE OR REPLACE VIEW  VIEW_ESTORGPROXCLI AS 
SELECT   EPC_CODCLI AS EOR_CODCLI,  COUNT(*) AS EOR_CANPRO  FROM 
  dpestructorgprocli  WHERE EPC_ACTIVO=1 
 GROUP BY EPC_CODCLI
;

-- 225
 CREATE OR REPLACE VIEW  VIEW_PROXFAC AS 
SELECT       DOC_CODSUC     AS PFC_CODSUC,      DOC_CODIGO     AS PFC_CODIGO,      MIN(DOC_FECHA) AS PFC_FCHMAX,      MAX(DOC_FECHA) AS PFC_FCHMIN      FROM 
 DPDOCPRO      WHERE DOC_TIPDOC="FAC" AND DOC_ACT=1 AND DOC_DOCORG="C"     
 GROUP BY DOC_CODSUC,DOC_CODIGO     
 ORDER BY DOC_CODSUC,DOC_CODIGO
;

-- 226
 CREATE OR REPLACE VIEW  VIEW_DPDIARIO_QUINCE AS 
SELECT DIA_ANO AS FCH_ANO, DIA_QUINCE AS FCH_QUINCE, DIA_CMES   AS FCH_CMES, MIN(DIA_FECHA) AS FCH_DESDE, MAX(DIA_FECHA) AS FCH_HASTA  FROM 
   DPDIARIO 
 GROUP BY DIA_ANO,DIA_QUINCE 
 ORDER BY DIA_ANO,DIA_QUINCE;

-- 227
 CREATE OR REPLACE VIEW  VIEW_DPRECIBOSCLIDOC AS 
SELECT  REC_CODSUC,  REC_NUMERO,  REC_CODIGO, 
 SUM(IF(DOC_CXC>0,DOC_NETO*DOC_CXC,0))  AS REC_DEBE, 
 SUM(IF(DOC_CXC<1,DOC_NETO*DOC_CXC*-1,0))  AS REC_HABER, 
 SUM(DOC_NETO*DOC_CXC)  AS REC_MONTO, 
 SUM(ROUND(DOC_NETO*DOC_CXC/DOC_VALCAM,2))  AS REC_MTODIV,  GROUP_CONCAT(DOC_TIPDOC,"-",DOC_NUMERO) AS REC_NUMDOC  FROM 
 dpreciboscli 
 INNER JOIN dpdoccli ON REC_CODSUC=DOC_CODSUC AND REC_NUMERO=DOC_RECNUM AND DOC_TIPTRA="P" AND DOC_ACT=1 AND DOC_CXC<>0
 GROUP BY REC_CODSUC,REC_NUMERO,REC_CODIGO;

-- 228
 CREATE OR REPLACE VIEW  VIEW_NMRECIBOS AS 
SELECT REC_CODSUC,REC_NUMERO,REC_FORMAP,REC_CODTRA,REC_CODGRU, REC_CODDEP,REC_CODBCO,REC_CODMON,REC_NUMFCH,     
 SUM(IF(LEFT(HIS_CODCON,1)="A",HIS_MONTO   ,0)) AS REC_MTOASG,    
 SUM(IF(LEFT(HIS_CODCON,1)="D",HIS_MONTO*-1,0)) AS REC_MTODED,    
 SUM(HIS_MONTO)                              AS REC_NETO,       COUNT(*) AS REC_CANTID       FROM 
 NMRECIBOS     
 INNER JOIN NMHISTORICO  ON REC_CODSUC=HIS_CODSUC AND REC_NUMERO=HIS_NUMREC AND (LEFT(HIS_CODCON,1)="A" OR LEFT(HIS_CODCON,1)="D")     
 GROUP BY REC_CODSUC,REC_NUMERO    
 ORDER BY REC_CODSUC,REC_NUMERO
;

-- 229
 CREATE OR REPLACE VIEW  VIEW_DPCTAREGXCOS AS 
SELECT     PLA_CODMOD AS RCC_CODMOD,    PLA_CODCTA AS RCC_CODCTA,    COUNT(*)   AS RCC_CANTID    FROM 
 DPPLACOS   
 GROUP BY PLA_CODMOD,PLA_CODCTA   
 ORDER BY PLA_CODMOD,PLA_CODCTA
;

-- 230
 CREATE OR REPLACE VIEW  VIEW_DPCTAREGXDEP AS 
SELECT       PLA_CODMOD AS RCD_CODMOD,      PLA_CODCTA AS RCD_CODCTA,      COUNT(*)   AS RCD_CANTID      FROM 
 DPPLADPTO     
 GROUP BY PLA_CODMOD,PLA_CODCTA     
 ORDER BY PLA_CODMOD,PLA_CODCTA
;

-- 231
 CREATE OR REPLACE VIEW  VIEW_DOCCLIREP AS 
SELECT         DOC_CODSUC AS REP_CODSUC,        DOC_TIPAFE AS REP_TIPDOC,        DOC_FACAFE AS REP_NUMERO,        DOC_TIPDOC AS REP_TIPAFE,        DOC_NUMERO AS REP_NUMREG,        DOC_FECHA  AS REP_FECHA ,        DOC_FCHVEN AS REP_FCHVEN        FROM 
 DPDOCCLI WHERE DOC_TIPDOC="REP" AND DOC_ACT=1 AND DOC_TIPTRA="D"       
 ORDER BY DOC_CODSUC,DOC_TIPDOC,DOC_NUMERO
;

-- 232
 CREATE OR REPLACE VIEW  VIEW_REGVEHINGPESO AS 
SELECT     VHP_NUMERO  AS VRE_NUMERO,    VHP_PLACA   AS VRE_PLACA,    VHP_PESO    AS VRE_PESO ,  VHP_FECHA   AS VRE_FECHA,  VHP_HORA    AS VRE_HORA   FROM 
 DPVEHICULOSPESAJE    WHERE VHP_TIPO="E"    
 ORDER BY VHP_NUMERO
;

-- 233
 CREATE OR REPLACE VIEW  VIEW_ACTIVOSGAS AS 
SELECT           DEP_CODSUC AS DAC_CODSUC,           DEP_NUMEJE AS DAC_NUMEJE,          CIC_CODINT AS DAC_CODINT,          CIC_CUENTA AS DAC_CUENTA,   CTA_DESCRI AS DAC_DESCRI,        
 SUM(IF(DEP_TIPTRA="I",DEP_MONTO,0))  AS DAC_MTOINI,         
 SUM(IF(DEP_TIPTRA="D",DEP_MONTO,0))  AS DAC_MTODEP,         
 SUM(IF(DEP_TIPTRA="V",DEP_MONTO,0))  AS DAC_COSADQ          FROM 
 DPDEPRECIAACT         
 INNER JOIN DPACTIVOS     ON ATV_CODSUC=DEP_CODSUC AND ATV_CODIGO=DEP_CODACT         
 INNER JOIN DPACTIVOS_CTA ON CIC_CODSUC=ATV_CODSUC AND CIC_CODIGO=ATV_CODIGO AND CIC_CODINT="CTADEP"  
 INNER JOIN DPCTA         ON CIC_CTAMOD=CTA_CODMOD AND CIC_CUENTA=CTA_CODIGO       WHERE CIC_CODINT="CTADEP"         
 GROUP BY DEP_CODSUC,DEP_NUMEJE,CIC_CODINT,CIC_CUENTA         
 ORDER BY DEP_CODSUC,DEP_NUMEJE,CIC_CODINT,CIC_CUENTA
;

-- 234
 CREATE OR REPLACE VIEW  VIEW_INVREQM AS 
SELECT  MOV_CODSUC AS REQ_CODSUC,  MOV_CODCTA AS REQ_CODIGO  FROM 
 DPMOVINV_REQM  WHERE MOV_APLORG="INV" AND MOV_INVACT=1 
 GROUP BY MOV_CODSUC,MOV_CODCTA 
 ORDER BY MOV_CODSUC,MOV_CODCTA
;

-- 235
 CREATE OR REPLACE VIEW  VIEW_DPMOVINV_REQMTDC AS 
SELECT       MOV_APLORG,      MOV_RIF,      COUNT(*) AS MOV_CUANTOS, 
 SUM(MOV_TOTAL) AS MOV_TOTAL      FROM 
 DPMOVINV_REQM      WHERE MOV_INVACT=1     
 GROUP BY MOV_APLORG,MOV_RIF     
 ORDER BY MOV_APLORG,MOV_RIF
;

-- 236
 CREATE OR REPLACE VIEW  VIEW_REQCLIINT AS 
SELECT           DOC_NUMERO AS RQC_NUMERO,          DOC_CODEST AS RQC_CODEST,          EOR_DESCRI AS RQC_DESCRI,      DOC_FECHA  AS RQC_FECHA,  DOC_FCHENT AS RQC_FCHENT,    DOC_ESTADO AS RQC_ESTADO          FROM 
 dpestructorgdocreqm         
 INNER JOIN dpestructorg ON DOC_CODEST=EOR_CODIGO          WHERE DOC_TIPTRA="C"         
 ORDER BY DOC_NUMERO
;

-- 237
 CREATE OR REPLACE VIEW  VIEW_REQPROINT AS 
SELECT     DOC_NUMERO AS RQP_NUMERO,    DOC_CODEST AS RQP_CODEST,    EOR_DESCRI AS RQP_DESCRI    FROM 
 dpestructorgdocreqm   
 INNER JOIN dpestructorg ON DOC_CODEST=EOR_CODIGO    WHERE DOC_TIPTRA="P"   
 ORDER BY DOC_NUMERO
;

-- 238
 CREATE OR REPLACE VIEW  VIEW_ACTIVOSDEP AS 
SELECT           DEP_CODSUC AS DAC_CODSUC,           DEP_NUMEJE AS DAC_NUMEJE,          CIC_CODINT AS DAC_CODINT,          CIC_CUENTA AS DAC_CUENTA,    CTA_DESCRI AS DAC_DESCRI,       
 SUM(IF(DEP_TIPTRA="I",DEP_MONTO,0))  AS DAC_MTOINI,         
 SUM(IF(DEP_TIPTRA="D",DEP_MONTO,0))  AS DAC_MTODEP,         
 SUM(IF(DEP_TIPTRA="V",DEP_MONTO,0))  AS DAC_COSADQ          FROM 
 DPDEPRECIAACT         
 INNER JOIN DPACTIVOS ON ATV_CODSUC=DEP_CODSUC AND ATV_CODIGO=DEP_CODACT         
 INNER JOIN DPACTIVOS_CTA ON CIC_CODSUC=ATV_CODSUC AND CIC_CODIGO=ATV_CODIGO AND CIC_CODINT="CTAACU"     
 INNER JOIN DPCTA         ON CIC_CTAMOD=CTA_CODMOD AND CIC_CUENTA=CTA_CODIGO       WHERE CIC_CODINT="CTAACU"         
 GROUP BY DEP_CODSUC,DEP_NUMEJE,CIC_CODINT,CIC_CUENTA         
 ORDER BY DEP_CODSUC,DEP_NUMEJE,CIC_CODINT,CIC_CUENTA
;

-- 239
 CREATE OR REPLACE VIEW  VIEW_RDDANUAL AS 
SELECT             DOC_CODSUC       AS RDD_CODSUC,      DOC_SERFIS       AS RDD_SERFIS,              YEAR(DOC_FECHA)  AS RDD_YEAR  ,            MONTH(DOC_FECHA) AS RDD_MES   ,           
 SUM(DOC_BASNET*DOC_CXC) AS RDD_BASE,           
 SUM(DOC_MTOIVA*DOC_CXC) AS RDD_IVA ,           
 SUM(DOC_NETO  *DOC_CXC) AS RDD_NETO,            COUNT(*)                AS RDD_RECCO            FROM 
 DPDOCCLI             WHERE DOC_TIPDOC="RDD" AND DOC_TIPTRA="D"           
 GROUP BY DOC_CODSUC,DOC_SERFIS,YEAR(DOC_FECHA),MONTH(DOC_FECHA)
;

-- 240
 CREATE OR REPLACE VIEW  VIEW_RDVANUAL AS 
SELECT        DOC_CODSUC       AS RDV_CODSUC,          DOC_SERFIS       AS RDV_SERFIS,           YEAR(DOC_FECHA)  AS RDV_YEAR,            MONTH(DOC_FECHA) AS RDV_MES,           
 SUM(DOC_BASNET*DOC_CXC) AS RDV_BASE,           
 SUM(DOC_MTOIVA*DOC_CXC) AS RDV_IVA,           
 SUM(DOC_NETO  *DOC_CXC) AS RDV_NETO,            COUNT(*)                AS RDV_RECCO,        MAX(DOC_FECHA)          AS RDV_FECHA        FROM 
 DPDOCCLI             WHERE DOC_TIPDOC="RDV" AND DOC_TIPTRA="D"           
 GROUP BY DOC_CODSUC,DOC_SERFIS,YEAR(DOC_FECHA),MONTH(DOC_FECHA)
;

-- 241
 CREATE OR REPLACE VIEW  VIEW_DPASIENTOSDIA AS 
SELECT MOC_CODSUC, MOC_ORIGEN,MOC_CTAMOD,MOC_CUENTA,MOC_FECHA,MOC_ACTUAL,MOC_CODMON,MOC_MTOORG,MOC_VALCAM,SUM(MOC_MONTO) AS MOC_MONTO  FROM 
 dpasientos  WHERE MOC_ACTUAL="S" 
 GROUP BY MOC_CODSUC,MOC_CTAMOD,MOC_CUENTA,MOC_FECHA 
 ORDER BY MOC_CODSUC,MOC_CTAMOD,MOC_CUENTA,MOC_FECHA,MOC_ACTUAL,MOC_VALCAM,MOC_CODMON;

-- 242
 CREATE OR REPLACE VIEW  VIEW_DOCPROCTACENCOS AS 
SELECT        CCD_CENCOS AS CDX_CODIGO,      MIN(DOC_FECHA) AS CDX_DESDE,      MAX(DOC_FECHA) AS CDX_HASTA,      COUNT(*)       AS CDX_CANTID,     
 SUM(CCD_MONTO) AS CDX_MONTO      FROM 
 DPDOCPROCTA     
 INNER JOIN DPDOCPRO ON CCD_CODSUC=DOC_CODSUC AND CCD_TIPDOC=DOC_TIPDOC AND CCD_CODIGO=DOC_CODIGO AND CCD_NUMERO=DOC_NUMERO AND CCD_TIPTRA=DOC_TIPTRA AND DOC_TIPTRA="D"      WHERE DOC_ACT=1     
 GROUP BY CCD_CENCOS
;

-- 243
 CREATE OR REPLACE VIEW  VIEW_CXCCLIXTIPDOC AS 
SELECT          DOC_CODIGO AS CXC_CODIGO,               DOC_CODSUC AS CXC_CODSUC,            DOC_TIPDOC AS CXC_TIPDOC,           
 SUM(DOC_NETO*DOC_CXC) AS CXC_SALDO            FROM 
 DPDOCCLI            WHERE DOC_ACT=1 AND DOC_CXC<>0           
 GROUP BY DOC_CODIGO,DOC_CODSUC,DOC_TIPDOC            HAVING
 SUM(DOC_NETO*DOC_CXC)<>0
;

-- 244
 CREATE OR REPLACE VIEW  VIEW_CLIENTEXTIPPRE AS 
SELECT   CLI_LISTA AS CXL_LISTA,  COUNT(*)  AS CXL_CANTID  FROM 
 DPCLIENTES 
 GROUP BY CLI_LISTA 
 ORDER BY CLI_LISTA
;

-- 245
 CREATE OR REPLACE VIEW  VIEW_DPPROVEEDORCTA_CANT AS 
SELECT CXP_CODMOD,CXP_TIPDOC,COUNT(*) AS CXP_CUANTOS FROM 
 DPPROVEEDORCTA
 GROUP BY CXP_CODMOD,CXP_TIPDOC;

-- 246
 CREATE OR REPLACE VIEW  VIEW_DPDPTOINV_CTA AS 
SELECT  CIC_CTAMOD AS GRU_CTAMOD,  DEP_CODIGO AS GRU_CODIGO,  DEP_DESCRI AS GRU_DESCRI   FROM 
 DPDPTO  LEFT JOIN DPDPTO_INV_CTA ON CIC_CODIGO=DEP_CODIGO 
 GROUP BY CIC_CTAMOD,DEP_CODIGO
;

-- 247
 CREATE OR REPLACE VIEW  VIEW_DPGRU_CTA AS 
SELECT        CIC_CTAMOD AS GRU_CTAMOD,        GRU_CODIGO,       GRU_DESCRI,       COUNT(*) AS GRU_CANTID        FROM 
 DPGRU       
 INNER JOIN DPGRU_CTA ON CIC_CODIGO=GRU_CODIGO       
 GROUP BY CIC_CTAMOD,GRU_CODIGO
;

-- 248
 CREATE OR REPLACE VIEW  VIEW_DPINV_CTA AS 
SELECT  CIC_CTAMOD AS INV_CTAMOD,  INV_CODIGO,  INV_DESCRI  FROM 
 DPINV 
 INNER JOIN DPINV_CTA ON CIC_CODIGO=INV_CODIGO 
 GROUP BY CIC_CTAMOD,INV_CODIGO;

-- 249
 CREATE OR REPLACE VIEW  VIEW_DPCTAEGRESORES AS 
SELECT         CCD_CODSUC     AS RCA_CODSUC,        CCD_CTAEGR     AS RCA_CTAEGR,       
 SUM(CCD_MONTO) AS RCA_MONTO ,        MIN(DOC_FECHA) AS RCA_FCHMIN,        MAX(DOC_FECHA) AS RCA_FCHMAX,        COUNT(*)       AS RCA_CANREG        FROM 
 DPDOCPROCTA       
 INNER JOIN DPDOCPRO ON DPDOCPRO.DOC_CODSUC=DPDOCPROCTA.CCD_CODSUC AND DPDOCPRO.DOC_TIPDOC=DPDOCPROCTA.CCD_TIPDOC AND DPDOCPRO.DOC_CODIGO=DPDOCPROCTA.CCD_CODIGO AND DPDOCPRO.DOC_NUMERO=DPDOCPROCTA.CCD_NUMERO AND DPDOCPRO.DOC_TIPTRA=DPDOCPROCTA.CCD_TIPTRA       
 GROUP BY CCD_CODSUC,CCD_CTAEGR       
 ORDER BY CCD_CODSUC,CCD_CTAEGR
;

-- 250
 CREATE OR REPLACE VIEW  VIEW_DOCPROREI AS 
SELECT         CCD_CODSUC AS REI_CODSUC,  CCD_CODIGO AS REI_CODIGO,        CCD_NUMERO AS REI_NUMERO,       
 SUM(CCD_MONTO) AS REI_MONTO,    COUNT(*) AS REI_CANTID          FROM 
 DPDOCPROCTA          WHERE CCD_TIPDOC="REI" AND CCD_ACT=1         
 GROUP BY CCD_CODSUC,CCD_TIPDOC,CCD_CODIGO,CCD_NUMERO       
 ORDER BY CCD_CODSUC,CCD_NUMERO  ,CCD_CODIGO
;

-- 251
 CREATE OR REPLACE VIEW  VIEW_CXCRESUMEN AS 
SELECT   
 SUM(DOC_MTOIVA*DOC_CXC) AS RXC_MTOIVA,         
 SUM(DOC_CXC*DOC_NETO)   AS RXC_NETO          FROM 
   DPDOCCLI          WHERE DOC_ACT=1 AND DOC_CXC<>0
;

-- 252
 CREATE OR REPLACE VIEW  VIEW_DPPROSLD AS 
SELECT SLD_CODIGO,SUM(SLD_SALDO) AS SLD_SALDO,SUM(SLD_CXPDIV) AS SLD_CXPDIV FROM 
 DPPROSLD
 GROUP BY SLD_CODIGO;

-- 253
 CREATE OR REPLACE VIEW  VIEW_DPDOCCLIXMOT AS 
SELECT   MDC_CODIGO AS MXD_CODIGO, MDC_TIPDOC AS MXD_TIPDOC, COUNT(*)   AS MXD_CANTID  FROM 
 DPTIPDOCCLIMOT 
 INNER JOIN DPDOCCLI ON MDC_TIPDOC=DOC_TIPDOC AND MDC_CODIGO=DOC_GIRNUM AND DOC_TIPTRA="D" AND DOC_ACT=1 
 GROUP BY MDC_CODIGO,MDC_TIPDOC;

-- 254
 CREATE OR REPLACE VIEW  VIEW_DPMOVINVRESVTA AS 
SELECT                   MOV_CODSUC AS RVT_CODSUC,                  MOV_TIPDOC AS RVT_TIPDOC,                  MOV_DOCUME AS RVT_DOCUME,                 
 SUM(MOV_CANTID) AS RVT_CANTID,       
 SUM(MOV_TOTAL)  AS RVT_TOTAL,      COUNT(*) AS RTV_COUNT      FROM 
                   DPMOVINV                  WHERE                  MOV_APLORG="V" AND MOV_INVACT=1       
 GROUP BY MOV_CODSUC,MOV_TIPDOC,MOV_DOCUME                
 ORDER BY MOV_CODSUC,MOV_TIPDOC,MOV_DOCUME
;

-- 255
 CREATE OR REPLACE VIEW  VIEW_CXPPROXTIPDOC AS 
SELECT     DOC_CODSUC AS CXP_CODSUC,    DOC_CODIGO AS CXP_CODIGO,    DOC_TIPDOC AS CXP_TIPDOC,   
 SUM(DOC_NETO*DOC_CXP) AS CXP_SALDO    FROM 
 DPDOCPRO    WHERE DOC_ACT=1 AND DOC_CXP<>0   
 GROUP BY DOC_CODSUC,DOC_CODIGO,DOC_TIPDOC    HAVING
 SUM(DOC_NETO*DOC_CXP)<>0
;

-- 256
 CREATE OR REPLACE VIEW  VIEW_DPMOVINVRESEXP AS 
SELECT           MOV_CODSUC AS REX_CODSUC,          MOV_ASOTIP AS REX_ASOTIP,          MOV_ASODOC AS REX_ASODOC,          MOV_DOCUME AS REX_DOCUME,          MOV_TIPDOC AS REX_TIPDOC,         
 SUM(MOV_CANTID) AS REX_CANTID    FROM 
           DPMOVINV          WHERE          MOV_ASOTIP<>"" AND MOV_ASODOC<>"" AND MOV_ITEM_A<>"" AND MOV_INVACT=1 
 GROUP BY MOV_CODSUC,MOV_ASOTIP,MOV_DOCUME        
 ORDER BY MOV_CODSUC,MOV_ASOTIP,MOV_DOCUME        ,MOV_CODIGO
;

-- 257
 CREATE OR REPLACE VIEW  VIEW_MBREGTRANSFBCO AS 
SELECT       MOB_CODSUC AS BXT_CODSUC,      MOB_DOCASO AS BXT_NUMFCH,      MOB_CODBCO AS BXT_CODBCO,      MOB_CUENTA AS BXT_CTABCO,      MOB_DOCUME AS BXT_NUMERO,     MOB_FECHA  AS BXT_FECHA,     MOB_MONTO  AS BXT_MONTO,  MOB_TIPO   AS BXT_TIPO       FROM 
 DPCTABANCOMOV       WHERE MOB_TIPO="CRET" AND  MOB_ORIGEN="NOM" AND MOB_ACT=1     
 ORDER BY MOB_CODSUC,MOB_DOCASO,MOB_CODBCO,MOB_CUENTA,MOB_DOCUME
;

-- 258
 CREATE OR REPLACE VIEW  VIEW_NMREGTRANSFBCO AS 
SELECT          REC_CODSUC AS RXT_CODSUC,         REC_NUMFCH AS RXT_NUMFCH,         REC_CODBCO AS RXT_CODBCO,         REC_CTABCO AS RXT_CTABCO,         REC_NUMCHQ AS RXT_NUMERO,         FCH_SISTEM AS RXT_FECHA,        
 SUM(HIS_MONTO) AS RXT_MONTO,   REC_TIPDOC    AS RXT_TIPO           FROM 
 NMHISTORICO          
 INNER JOIN NMRECIBOS    ON HIS_CODSUC=REC_CODSUC AND HIS_NUMREC=REC_NUMERO          
 INNER JOIN NMFECHAS     ON REC_CODSUC=FCH_CODSUC AND REC_NUMFCH=FCH_NUMERO           WHERE LEFT(REC_FORMAP,1)="T"  AND HIS_CODCON<="DZZZ"    AND REC_NUMCHQ<>""           
 GROUP BY REC_CODSUC,REC_NUMFCH,REC_CODBCO,REC_CTABCO,REC_NUMCHQ         
 ORDER BY REC_CODSUC,REC_NUMFCH,REC_CODBCO,REC_CTABCO,REC_NUMCHQ
;

-- 259
 CREATE OR REPLACE VIEW  VIEW_RESLIBINV AS 
SELECT              DLI_CODSUC                 AS RLI_CODSUC,              DLI_NUMERO                 AS RLI_NUMERO,             
 SUM(DLI_CANANT*DLI_COSANT) AS RLI_VALANT,             
 SUM(DLI_SALDO*DLI_COSPRO)  AS RLI_VALACT, 
 SUM(DLI_ACTFIN)            AS RLI_ACTFIN                          FROM 
               DPLIBINVDET             
 GROUP BY DLI_CODSUC,DLI_NUMERO             
 ORDER BY DLI_CODSUC,DLI_NUMERO
;

-- 260
 CREATE OR REPLACE VIEW  VIEW_DPMOVINVEXP AS 
SELECT                   MOV_CODSUC AS MVE_CODSUC,                  MOV_ASOTIP AS MVE_ASOTIP,                  MOV_ASODOC AS MVE_ASODOC,                  MOV_CODIGO AS MVE_CODIGO,                 
 SUM(MOV_CANTID) AS MVE_EXPORT                   FROM 
 DPMOVINV                  WHERE MOV_ASOTIP<>"" AND MOV_INVACT<>0                 
 GROUP BY MOV_CODSUC,MOV_ASOTIP,MOV_ASODOC,MOV_CODIGO
;

-- 261
 CREATE OR REPLACE VIEW  VIEW_DPCTABANCOMOVORG AS 
SELECT           MOB_CODSUC,          MOB_DOCASO,        MOB_ORIGEN,        
 SUM(MOB_MONTO*MOB_ACT) AS MOB_MONTO          FROM 
 DPCTABANCOMOV           
 GROUP BY MOB_CODSUC,MOB_DOCASO,MOB_ORIGEN       
 ORDER BY MOB_CODSUC,MOB_DOCASO,MOB_ORIGEN
;

-- 262
 CREATE OR REPLACE VIEW  VIEW_DPCAJAMOVORG AS 
SELECT CAJ_CODSUC,CAJ_DOCASO,CAJ_ORIGEN,
 SUM(IF(CAJ_MTODIV>0,0,CAJ_MONTO *CAJ_ACT*CAJ_DEBCRE)  ) AS CAJ_MONTO ,
 SUM(IF(CAJ_TIPO="DOL",CAJ_MTODIV*CAJ_ACT*CAJ_DEBCRE,0)) AS CAJ_MTODIV,
 SUM(CAJ_MTOITF*CAJ_ACT*CAJ_DEBCRE) AS CAJ_MTOITF  FROM 
 DPCAJAMOV 
 GROUP BY CAJ_CODSUC,CAJ_DOCASO,CAJ_ORIGEN  
 ORDER BY CAJ_CODSUC,CAJ_DOCASO,CAJ_ORIGEN;

-- 263
 CREATE OR REPLACE VIEW  VIEW_RESDOCPROPROG AS 
SELECT   PLP_TIPDOC,  PLP_CODIGO,  PLP_REFERE   FROM 
 DPDOCPROPROG 
 GROUP BY PLP_TIPDOC,PLP_CODIGO,PLP_REFERE
;

-- 264
 CREATE OR REPLACE VIEW  VIEW_DPASIENTOSCTAEJEMES AS 
SELECT MOC_CUENTA AS RMA_CUENTA, YEAR(MOC_FECHA)   AS RMA_NUMEJE,
 SUM(IF(MOC_FECHA<EJE_DESDE,MOC_MONTO,0)) AS RMA_MTOANT, MONTH(MOC_FECHA)  AS RMA_MES,   
 SUM(MOC_MONTO)    AS RMA_MONTO   FROM 
 DPASIENTOS 
 INNER JOIN dpejercicios ON MOC_NUMEJE=EJE_NUMERO  WHERE MOC_ACTUAL="S" 
 GROUP BY MOC_CUENTA,MOC_NUMEJE,MONTH(MOC_FECHA) 
 ORDER BY MOC_CUENTA,MOC_NUMEJE,MONTH(MOC_FECHA)
;

-- 265
 CREATE OR REPLACE VIEW  VIEW_DPDOCCLIPAGRES AS 
SELECT      DOC_CODSUC AS PAG_CODSUC,     DOC_TIPDOC AS PAG_TIPDOC,      DOC_NUMERO AS PAG_NUMERO,     
 SUM(DOC_NETO) AS PAG_MONTO      FROM 
 DPDOCCLI        WHERE DOC_TIPTRA="P" AND DOC_ACT<>0         
 GROUP BY DOC_CODSUC,DOC_TIPDOC,DOC_NUMERO   
 ORDER BY PAG_CODSUC,PAG_TIPDOC,PAG_NUMERO
;

-- 266
 CREATE OR REPLACE VIEW  VIEW_DOCPRORMU AS 
SELECT   DOC_CODSUC AS RMU_CODSUC,  DOC_TIPAFE AS RMU_TIPDOC,  DOC_CODIGO AS RMU_CODIGO,  DOC_FACAFE AS RMU_NUMDOC,  DOC_NUMERO AS RMU_NUMERO,  DOC_NETO   AS RMU_MONTO  FROM 
  DPDOCPRO  WHERE((DOC_TIPDOC="RMU") and (DOC_TIPTRA = "D")) 
 ORDER BY DOC_CODSUC,DOC_TIPAFE,DOC_CODIGO,DOC_FACAFE
;

-- 267
 CREATE OR REPLACE VIEW  VIEW_DOCCLIRMU AS 
SELECT  DOC_CODSUC AS RMU_CODSUC, DOC_TIPAFE AS RMU_TIPDOC, DOC_CODIGO AS RMU_CODIGO, DOC_FACAFE AS RMU_NUMDOC, DOC_NUMERO AS RMU_NUMERO, DOC_NETO   AS RMU_MONTO   FROM 
   DPDOCCLI  WHERE((DOC_TIPDOC="RMU") and (DOC_TIPTRA = "D")) 
 ORDER BY DOC_CODSUC,DOC_TIPAFE,DOC_FACAFE;

-- 268
 CREATE OR REPLACE VIEW  VIEW_DPDOCCLIRET AS 
SELECT         DOC_CODSUC AS RET_CODSUC,        DOC_TIPDOC AS RET_TIPDOC,     DOC_CODIGO AS RET_CODIGO,       DOC_NUMERO AS RET_NUMERO,        DOC_NETO   AS RET_NETO,        DOC_RECNUM AS RET_RECNUM,        DOC_CBTNUM AS RET_CBTNUM,      DOC_ESTADO AS RET_ESTADO       FROM 
 DPDOCCLIISLR       
 INNER JOIN DPDOCCLI ON RXC_CODSUC=DOC_CODSUC AND RXC_TIPDOC=DOC_TIPDOC AND RXC_NUMDOC=DOC_NUMERO AND DOC_TIPTRA="D"       
 GROUP BY DOC_CODSUC,DOC_TIPDOC,DOC_CODIGO,DOC_NUMERO       
 ORDER BY DOC_CODSUC,DOC_TIPDOC,DOC_CODIGO,DOC_NUMERO
;

-- 269
 CREATE OR REPLACE VIEW  VIEW_DOCPROISLR AS 
SELECT                   RXP_CODSUC AS RET_CODSUC,                                RXP_TIPDOC AS RET_TIPDOC,                                RXP_CODIGO AS RET_CODIGO,                                RXP_NUMDOC AS RET_NUMERO,                                DOC_FECHA  AS RET_FECHA ,                  DOC_FCHDEC AS RET_FCHDEC,        RXP_DOCTIP AS RET_DOCTIP,        RXP_DOCNUM AS RET_DOCNUM,    RXP_DOCNUM AS RXP_DOCNUM, 
 SUM(RXP_PORCEN)  AS RET_PORCEN ,                                COUNT(*)         AS RET_CUANTOS,                                MONTH(DOC_FECHA) AS RET_MES    ,              YEAR(DOC_FECHA)  AS RET_YEAR   ,           MONTH(DOC_FECHA) AS RET_MES_D  ,              YEAR(DOC_FECHA)  AS RET_YEAR_D ,             
 SUM(RXP_MTORET)  AS RET_MONTO              FROM 
  DPDOCPROISLR               
 INNER JOIN DPDOCPRO ON                 RXP_CODSUC=DOC_CODSUC AND                 RXP_TIPDOC=DOC_TIPDOC AND                RXP_CODIGO=DOC_CODIGO AND                RXP_NUMDOC=DOC_NUMERO                                WHERE 1=1                             
 GROUP BY RXP_CODSUC,RXP_TIPDOC,RXP_CODIGO,RXP_DOCNUM                               
 ORDER BY RXP_CODSUC,RXP_TIPDOC,RXP_CODIGO,RXP_DOCNUM
;

-- 270
 CREATE OR REPLACE VIEW  VIEW_DPDOCPRORET AS 
SELECT             DOC_CODSUC AS RET_CODSUC,            DOC_TIPDOC AS RET_TIPDOC,            DOC_CODIGO AS RET_CODIGO,            DOC_NUMERO AS RET_NUMERO,          DOC_NETO   AS RET_NETO,          RXP_MTORET AS RET_MTORET,              DOC_PAGNUM AS RET_RECNUM,            DOC_CBTNUM AS RET_CBTNUM,          DOC_ESTADO AS RET_ESTADO           FROM 
 DPDOCPROISLR           
 INNER JOIN DPDOCPRO ON RXP_CODSUC=DOC_CODSUC AND RXP_TIPDOC=DOC_TIPDOC AND RXP_CODIGO=DOC_CODIGO AND RXP_NUMDOC=DOC_NUMERO AND DOC_TIPTRA="D"           
 GROUP BY DOC_CODSUC,DOC_TIPDOC,DOC_CODIGO,DOC_NUMERO           
 ORDER BY DOC_CODSUC,DOC_TIPDOC,DOC_CODIGO,DOC_NUMERO
;

-- 271
 CREATE OR REPLACE VIEW  VIEW_DOCCLIRTI AS 
SELECT RTI_CODSUC AS RTI_CODSUC,                                    RTI_TIPDOC AS RTI_TIPDOC,                                    RTI_DOCNUM AS RTI_NUMERO,                                    RTI_NUMERO AS RTI_NUMDOC,                             RTI_PORCEN AS RTI_PORCEN,                                    DOC_NETO   AS RTI_MONTO ,                                    DOC_FECHA  AS RTI_FECHA ,                                   RTI_DOCTIP    FROM 
  DPDOCCLIRTI                                   
 INNER JOIN DPDOCCLI ON             RTI_CODSUC=DOC_CODSUC AND                                    RTI_DOCTIP=DOC_TIPDOC AND                                    RTI_DOCNUM=DOC_NUMERO AND DOC_TIPTRA="D"                  WHERE DOC_ACT=1                           
 ORDER BY RTI_CODSUC,RTI_TIPDOC,RTI_NUMDOC
;

-- 272
 CREATE OR REPLACE VIEW  VIEW_DOCPRORTI AS 
SELECT RTI_CODSUC AS RTI_CODSUC,                                                RTI_CODIGO AS RTI_CODIGO,                                                RTI_TIPDOC AS RTI_TIPDOC,                                                RTI_DOCNUM AS RTI_NUMERO,                                                RTI_NUMERO AS RTI_NUMDOC,                                         RTI_PORCEN AS RTI_PORCEN,                                                DOC_NETO   AS RTI_MONTO ,                                                DOC_FCHDEC AS RTI_FCHDEC,                                                DOC_FECHA  AS RTI_FECHA ,                        DOC_ACT    AS RTI_ACT,                      RTI_NUMRET AS RTI_NUMRET                                                                   FROM 
  DPDOCPRORTI                                               
 INNER JOIN DPDOCPRO ON RTI_CODSUC=DOC_CODSUC AND                                                RTI_DOCTIP=DOC_TIPDOC AND                                                RTI_CODIGO=DOC_CODIGO AND                                                RTI_DOCNUM=DOC_NUMERO AND DOC_TIPTRA="D"                              WHERE DOC_ACT=1                                       
 ORDER BY RTI_CODSUC,RTI_TIPDOC,RTI_CODIGO,RTI_NUMDOC
;

-- 273
 CREATE OR REPLACE VIEW  VIEW_DOCCLIISLR AS 
SELECT                     RXC_CODSUC AS RET_CODSUC,                                  RXC_TIPDOC AS RET_TIPDOC,                                  DOC_CODIGO AS RET_CODIGO,                                  RXC_NUMDOC AS RET_NUMERO,                                  DOC_FECHA  AS RET_FECHA ,                    RXC_DOCTIP AS RET_DOCTIP,         RXC_DOCNUM AS RET_DOCNUM,        
 SUM(RXC_PORCEN)  AS RET_PORCEN ,                                  COUNT(*)         AS RET_CUANTOS,                                  MONTH(DOC_FECHA) AS RET_MES    ,                YEAR(DOC_FECHA)  AS RET_YEAR   ,             MONTH(DOC_FECHA) AS RET_MES_D  ,                YEAR(DOC_FECHA)  AS RET_YEAR_D ,               
 SUM(RXC_MTORET)  AS RET_MONTO                FROM 
  DPDOCCLIISLR                 
 INNER JOIN DPDOCCLI ON                   RXC_CODSUC=DOC_CODSUC AND                   RXC_TIPDOC=DOC_TIPDOC AND                  RXC_NUMDOC=DOC_NUMERO                                  WHERE 1=1                               
 GROUP BY RXC_CODSUC,RXC_TIPDOC,RXC_DOCNUM                                 
 ORDER BY RXC_CODSUC,RXC_TIPDOC,RXC_DOCNUM
;

-- 274
 CREATE OR REPLACE VIEW  VIEW_DOCPROISLR_REP AS 
SELECT       RXP_CODSUC,  RXP_TIPDOC,  TDC_DESCRI,  RXP_DOCNUM,  COUNT(*)      FROM 
 DPDOCPROISLR      LEFT JOIN DPTIPDOCPRO ON RXP_TIPDOC=TDC_TIPO   
 GROUP BY RXP_CODSUC,RXP_TIPDOC,RXP_DOCNUM      HAVING COUNT(*)>1
;

-- 275
 CREATE OR REPLACE VIEW  VIEW_DOCPROISLREDO AS 
SELECT                     RXP_CODSUC AS ISL_CODSUC,                    RXP_TIPDOC AS ISL_TIPDOC,                    RXP_CODIGO AS ISL_CODIGO,                    RXP_NUMDOC AS ISL_NUMDOC,                    DOC_FECHA  AS ISL_FECHA ,                    DOC_FCHDEC AS ISL_FCHDEC,                    RXP_DOCTIP AS ISL_DOCTIP,                    RXP_DOCNUM AS ISL_NUMRET,                    RXP_PORCEN AS ISL_PORCEN,                    DOC_ESTADO AS ISL_ESTADO,                    DOC_ACT    AS ISL_ACT,                    DOC_NUMPAR AS ISL_NUMPAR,                    DOC_CBTNUM AS ISL_CBTNUM                    FROM 
 DPDOCPROISLR                   
 INNER JOIN DPDOCPRO ON                    RXP_CODSUC=DOC_CODSUC AND                    RXP_DOCTIP=DOC_TIPDOC AND                    RXP_CODIGO=DOC_CODIGO AND                    RXP_DOCNUM=DOC_NUMERO AND DOC_TIPTRA="D"                    WHERE DOC_TIPTRA="D"                   
 GROUP BY RXP_CODSUC,RXP_TIPDOC,RXP_CODIGO,RXP_DOCNUM                   
 ORDER BY RXP_CODSUC,RXP_TIPDOC,RXP_CODIGO,RXP_DOCNUM
;

-- 276
 CREATE OR REPLACE VIEW  VIEW_DOCPRORET AS 
SELECT             DOC_CODSUC AS RET_CODSUC,            DOC_TIPDOC AS RET_TIPDOC,         DOC_CODIGO AS RET_CODIGO,           DOC_NUMERO AS RET_NUMERO,            DOC_NETO   AS RET_NETO,            DOC_PAGNUM AS RET_PAGNUM,            DOC_CBTNUM AS RET_CBTNUM,          DOC_ESTADO AS RET_ESTADO,  RXP_NUMDOC AS RET_NUMRET  FROM 
 DPDOCPROISLR           
 INNER JOIN DPDOCPRO ON RXP_CODSUC=DOC_CODSUC AND RXP_TIPDOC=DOC_TIPDOC AND RXP_CODIGO=DOC_CODIGO AND RXP_NUMDOC=DOC_NUMERO AND DOC_TIPTRA="D"           
 GROUP BY DOC_CODSUC,DOC_TIPDOC,DOC_CODIGO,DOC_NUMERO           
 ORDER BY DOC_CODSUC,DOC_TIPDOC,DOC_CODIGO,DOC_NUMERO
;

-- 277
 CREATE OR REPLACE VIEW  VIEW_DPINVSLD AS 
SELECT  SLD_CODIGO,SUM(SLD_FISICO) AS SLD_FISICO,SUM(SLD_LOGICO) AS SLD_LOGICO,SUM(SLD_CONTAB) AS SLD_CONTAB FROM 
 DPINVSLD 
 GROUP BY SLD_CODIGO;

-- 278
 CREATE OR REPLACE VIEW  VIEW_DPCAJASALDO AS 
SELECT   CAJ_CODSUC AS SLD_CODSUC,  CAJ_CODCAJ AS SLD_CODCAJ, 
 SUM(CAJ_MONTO*CAJ_DEBCRE) AS SLD_TOTAL   FROM 
 DPCAJAMOV  WHERE CAJ_ACT=1 
 GROUP BY CAJ_CODSUC,CAJ_CODCAJ 
 ORDER BY CAJ_CODSUC,CAJ_CODCAJ
;

-- 279
 CREATE OR REPLACE VIEW  VIEW_CTABCOSLDCON AS 
SELECT             MOB_CODSUC     AS CBC_CODSUC,            MOB_CODBCO     AS CBC_CODBCO,            MOB_CUENTA     AS CBC_CUENTA,            MIN(MOB_FECHA) AS CBC_DESDE,            MAX(MOB_FECHA) AS CBC_HASTA,           
 SUM(MOB_MONTO*TDB_SIGNO) AS  CBC_SALDO,           
 SUM(MOB_MTOIDB) AS  CBC_MTOIDB,           
 SUM((MOB_MONTO*TDB_SIGNO)-MOB_MTOIDB) AS CBC_SLDIDB,    COUNT(*) AS CBC_CANTID            FROM 
 DPCTABANCOMOV             
 INNER JOIN DPBANCOTIP ON TDB_CODIGO=MOB_TIPO              WHERE MOB_FCHCON<>"0000-00-00" AND MOB_ACT <> 0            
 GROUP BY MOB_CODSUC,MOB_CODBCO,MOB_CUENTA         
 ORDER BY MOB_CODSUC,MOB_CODBCO,MOB_CUENTA
;

-- 280
 CREATE OR REPLACE VIEW  VIEW_CTABCOSLDLIB AS 
SELECT         MOB_CODSUC     AS CBL_CODSUC,        MOB_CODBCO     AS CBL_CODBCO,        MOB_CUENTA     AS CBL_CUENTA,        MIN(MOB_FECHA) AS CBL_DESDE,        MAX(MOB_FECHA) AS CBL_HASTA,       
 SUM(MOB_MONTO*TDB_SIGNO) AS  CBL_SALDO,       
 SUM(MOB_MTOIDB) AS  CBL_MTOIDB,       
 SUM((MOB_MONTO*TDB_SIGNO)-MOB_MTOIDB) AS CBL_SLDIDB,    COUNT(*) AS CBL_CANTID        FROM 
 DPCTABANCOMOV         
 INNER JOIN DPBANCOTIP ON TDB_CODIGO=MOB_TIPO          WHERE MOB_ACT <> 0        
 GROUP BY MOB_CODSUC,MOB_CODBCO,MOB_CUENTA       
 ORDER BY MOB_CODSUC,MOB_CODBCO,MOB_CUENTA
;

-- 281
 CREATE OR REPLACE VIEW  VIEW_DPDIARIO_SEMLUN AS 
SELECT               YEAR(DIA_FECHA) AS SEM_ANO,              DIA_DIALUN      AS SEM_NUMERO,              DIA_FECHA       AS SEM_DESDE,              DATE_ADD(DIA_FECHA,INTERVAL 6 DAY) AS SEM_HASTA              FROM 
 DPDIARIO              WHERE  DAYOFWEEK(DIA_FECHA)=2             
 GROUP BY YEAR(DIA_FECHA),DIA_SEMANA             
 ORDER BY YEAR(DIA_FECHA),DIA_SEMANA
;

-- 282
 CREATE OR REPLACE VIEW  VIEW_DPLICCLIENTES AS 
SELECT CLI_RIF AS LIC_RIF,CLI_NOMBRE AS LIC_NOMBRE,INV_CODIGO AS LIC_CODIGO,INV_DESCRI AS LIC_DESCRI,            MOV_CODCOM AS LIC_NUMERO,MOV_DESCUE AS LIC_VERSION,MOV_FECHA AS LIC_FCHINI,MOV_FCHVEN AS LIC_FCHVEN,INV_GRUPO AS LIC_GRUPO,            CLI_SITUAC AS LIC_SITUA,INV_ESTADO AS LIC_ESTADO                FROM 
        DPMOVINV                      
 INNER JOIN DPCLIENTES ON MOV_DOCUME=CLI_CODIGO                       LEFT  JOIN DPVENDEDOR ON CLI_CODVEN=VEN_CODIGO                       
 INNER JOIN DPINV      ON MOV_CODIGO=INV_CODIGO                       WHERE MOV_APLORG="A" and mov_tipdoc<>"CLI"   AND (INV_GRUPO="ADM" OR INV_GRUPO="NOM") AND MOV_CODCOM<>""            AND LENGTH(MOV_CODCOM)>20             
 GROUP BY MOV_CODCOM                   
 ORDER BY MOV_CODCOM
;

-- 283
 CREATE OR REPLACE VIEW  VIEW_DOCCLISERFIS AS 
SELECT       DOC_CODSUC,      DOC_SERFIS,      MAX(DOC_NUMFIS) AS DOC_NUMFIS,  MAX(DOC_NUMERO) AS DOC_NUMERO      FROM 
 DPDOCCLI     
 INNER JOIN DPSERIEFISCAL ON DOC_SERFIS=SFI_LETRA       
 INNER JOIN DPTIPDOCCLI   ON DOC_TIPDOC=TDC_TIPO AND TDC_LIBVTA=1       
 GROUP BY DOC_SERFIS      
 ORDER BY DOC_CODSUC,DOC_SERFIS
;

-- 284
 CREATE OR REPLACE VIEW  VIEW_DPTIPDOCCLISERFIS AS 
SELECT  RIGHT(DAT_GROUP,6) AS TSF_CODSUC,  LEFT(DAT_NAME,3)   AS TSF_TIPDOC,  DAT_VALUE          AS TSF_SERIEF,  SFI_LETRA          AS TSF_LETRA,  SFI_IMPFIS         AS TSF_IMPFIS  FROM 
 DPDATASET 
 INNER JOIN DPTIPDOCCLI ON TDC_TIPO=LEFT(DAT_NAME,3) AND TDC_LIBVTA=1  LEFT  JOIN DPSERIEFISCAL ON TDC_SERIEF=SFI_MODELO  WHERE LEFT(DAT_GROUP,5)="SUC_V" AND RIGHT(DAT_NAME,5)="SERIE";

-- 285
 CREATE OR REPLACE VIEW  VIEW_REGACTSERIMP AS 
SELECT           INV_CODIGO,          INV_DESCRI,          IF(LEFT(INV_ESTADO,1)="A",1,0) AS INV_ACTIVO,          EOR_DESCRI          FROM 
 DPINV_TIN            LEFT JOIN DPESTRUCTORG ON EOR_CODIGO=INV_CODEOR                 WHERE INV_TIPO="PRY"              
 ORDER BY INV_CODIGO
;

-- 286
 CREATE OR REPLACE VIEW  VIEW_NMTRABJSLDIA AS 
SELECT         CODIGO,                              COD_DPTO                        AS TRA_CODDEP,        SALARIO/IF(TIPO_NOM="S",1,30)   AS TRA_SALDIA,          PORCENPRES                      AS TRA_PORCEN,          IF(PORCENPRES=0,0,(SALARIO*PORCENPRES/100)) AS TRA_MTOPRE,          SALARIO+IF(PORCENPRES=0,0,IF(PORCENPRES=0,0,(SALARIO*PORCENPRES/100))) AS TRA_SALPRE          FROM 
 NMTRABAJADOR                                     WHERE CONDICION="A"                                                       
 ORDER BY CODIGO
;

-- 287
 CREATE OR REPLACE VIEW  VIEW_DPDOCCLIISLRSUM AS 
SELECT       RXC_CODSUC      AS ISR_CODSUC,      RXC_TIPDOC      AS ISR_TIPDOC,      RXC_DOCNUM      AS ISR_DOCNUM,     
 SUM(RXC_MTORET) AS ISR_MTORET,      DOC_NETO        AS ISR_NETO,      DOC_ESTADO      AS ISR_ESTADO      FROM 
 DPDOCCLIISLR      LEFT JOIN DPDOCCLI ON DOC_CODSUC=RXC_CODSUC AND DOC_TIPDOC="RET" AND DOC_NUMERO=RXC_DOCNUM AND DOC_TIPTRA="D" AND DOC_ACT=1     
 GROUP BY RXC_CODSUC,RXC_TIPDOC,RXC_DOCNUM   
 ORDER BY RXC_CODSUC,RXC_TIPDOC,RXC_DOCNUM
;

-- 288
 CREATE OR REPLACE VIEW  VIEW_SUSTITUTOSCONCAT AS 
SELECT SUS_CODIGO,GROUP_CONCAT(SUS_SUSTIT) AS SUS_SUSTIT,COUNT(*) AS CUANTOS FROM 
 dpsustitutos
 GROUP BY SUS_CODIGO
 ORDER BY SUS_CODIGO;

-- 289
 CREATE OR REPLACE VIEW  VIEW_DPINVTARACARGA AS 
SELECT     INV_CODIGO AS TAR_CODIGO,    INV_DESCRI AS TAR_DESCRI,  INV_GRADOS AS TAR_PESO   FROM 
 DPINV    WHERE INV_UTILIZ="Tara de Carga"   
 ORDER BY INV_CODIGO
;

-- 290
 CREATE OR REPLACE VIEW  VIEW_TIPDOCCLI_Y AS 
SELECT           TDC_TIPO   AS TDY_TIPO,          TDC_DESCRI AS TDY_DESCRI,          TDC_DOCDES AS TDY_DOCDES          FROM 
 DPTIPDOCCLI
;

-- 291
 CREATE OR REPLACE VIEW  VIEW_TIPDOCCLI_X AS 
SELECT     TDC_TIPO   AS TDX_TIPO,    TDC_DESCRI AS TDX_DESCRI,    TDC_DOCDES AS TDX_DOCDES    FROM 
 DPTIPDOCCLI
;

-- 292
 CREATE OR REPLACE VIEW  VIEW_DPTIPPROCONPLA AS 
SELECT     PRO_TIPO AS PTP_TIPO,    COUNT(*) AS PTP_CUANTOS     FROM 
 DPPROVEEDORPROG   
 INNER JOIN DPPROVEEDOR ON PRO_CODIGO=PGC_CODIGO   
 GROUP BY PRO_TIPO
;

-- 293
 CREATE OR REPLACE VIEW  VIEW_DOCCLITOTALES AS 
SELECT    MOV_CODSUC      AS  DLC_CODSUC,    MOV_TIPDOC      AS  DLC_TIPDOC,    MOV_DOCUME      AS  DLC_NUMERO,   
 SUM(MOV_CANTID) AS  DLC_CANTID,   
 SUM(MOV_PESO)   AS  DLC_PESO,   
 SUM(MOV_TOTAL)  AS  DLC_TOTAL    FROM 
 dpmovinv    WHERE MOV_TIPDOC="FAV" AND MOV_INVACT=1   
 GROUP BY MOV_CODSUC,MOV_TIPDOC,MOV_DOCUME   
 ORDER BY MOV_CODSUC,MOV_TIPDOC,MOV_DOCUME
;

-- 294
 CREATE OR REPLACE VIEW  VIEW_NMEGRESADOSXANO AS 
SELECT  YEAR(FECHA_EGR)  AS EGR_ANO,  COUNT(*)         AS EGR_CANT  FROM 
 nmtrabajador  WHERE FECHA_EGR<>"0000-00-00" 
 GROUP BY YEAR(FECHA_EGR) 
 ORDER BY YEAR(FECHA_EGR);

-- 295
 CREATE OR REPLACE VIEW  VIEW_NMEGRESADOSXMES AS 
SELECT  YEAR(FECHA_EGR)  AS EGR_ANO,  MONTH(FECHA_EGR) AS EGR_MES,  COUNT(*)         AS EGR_CANT  FROM 
 nmtrabajador  WHERE FECHA_EGR<>"0000-00-00" 
 GROUP BY YEAR(FECHA_EGR),MONTH(FECHA_EGR) 
 ORDER BY YEAR(FECHA_EGR),MONTH(FECHA_EGR);

-- 296
 CREATE OR REPLACE VIEW  VIEW_NMINGRESADOSXANO AS 
SELECT  YEAR(FECHA_ING)  AS ING_ANO, COUNT(*)         AS ING_CANT FROM 
 nmtrabajador  WHERE FECHA_ING<>"0000-00-00"
 GROUP BY YEAR(FECHA_ING)
 ORDER BY YEAR(FECHA_ING);

-- 297
 CREATE OR REPLACE VIEW  VIEW_NMINGRESADOSXMES AS 
SELECT  YEAR(FECHA_ING)  AS ING_ANO, MONTH(FECHA_ING) AS ING_MES, COUNT(*)         AS ING_CANT FROM 
 nmtrabajador  WHERE FECHA_ING<>"0000-00-00"
 GROUP BY YEAR(FECHA_ING),MONTH(FECHA_ING)
 ORDER BY YEAR(FECHA_ING),MONTH(FECHA_ING);

-- 298
 CREATE OR REPLACE VIEW  VIEW_NMTRABJXDEP AS 
SELECT                                 COD_DPTO AS TRA_CODDEP,                               
 SUM(SALARIO/IF(TIPO_NOM="S",1,30)) AS TRA_SALDIA,                      COUNT(*) AS TRA_CANTID                                FROM 
 NMTRABAJADOR             WHERE CONDICION="A"                               
 GROUP BY COD_DPTO                               
 ORDER BY COD_DPTO
;

-- 299
 CREATE OR REPLACE VIEW  VIEW_TRANSFERENCIABCODEB AS 
SELECT MOB_CODSUC AS TDB_CODSUC, MOB_TRAASO AS TDB_NUMTRA,  MOB_TIPO   AS TDB_TIPO  ,  MOB_CODBCO AS TDB_CODBCO,  MOB_CUENTA AS TDB_CUENTA,  BAN_NOMBRE AS TDB_NOMBRE,  MOB_ACT    AS TDB_ACT   ,  MOB_MONTO  AS TDB_MONTO ,  MOB_FECHA  AS TDB_FECHA ,  MOB_HORA   AS TDB_HORA  ,  IF(MOB_ACT=1,"Activo","Nulo") AS TDB_ESTADO  FROM 
 dpctabancomov   
 INNER  JOIN DPBANCOS ON DPCTABANCOMOV.MOB_CODBCO=DPBANCOS.BAN_CODIGO  WHERE MOB_ORIGEN="TRA" AND MOB_TIPO  ="DEBT" 
 ORDER BY MOB_CODSUC,MOB_NUMTRA,MOB_MONTO,MOB_FECHA,MOB_HORA;

-- 300
 CREATE OR REPLACE VIEW  VIEW_ASIENTOS_TF AS 
SELECT       EJE_CODSUC AS BTF_CODSUC,                  EJE_NUMERO AS BTF_NUMEJE,                 EJE_CBTTRA AS BTF_NUMCBT,                  MOC_CTAMOD AS BTF_CTAMOD,                  MOC_ITEM   AS BTF_ITEM,                  MOC_CUENTA AS BTF_CUENTA,            CTA_DESCRI AS BTF_DESCRI,      MOC_MONTO  AS BTF_MONTO                  FROM 
 DPEJERCICIOS                 
 INNER JOIN DPASIENTOS ON EJE_CODSUC=MOC_CODSUC AND EJE_CBTTRA=MOC_NUMCBT AND MOC_TIPO="BF" AND MOC_ACTUAL="S"                
 INNER JOIN DPCTA      ON MOC_CTAMOD=CTA_CODMOD AND MOC_CUENTA=CTA_CODIGO            WHERE EJE_CBTTRA<>""                  
 GROUP BY EJE_CODSUC,EJE_CBTTRA,MOC_CTAMOD,MOC_ITEM
;

-- 301
 CREATE OR REPLACE VIEW  VIEW_INVUBICAFISICA AS 
SELECT  UXP_CODIGO AS UBI_CODINV, UXP_CODUBI AS UBI_CODUBI, UBI_DESCRI, UBI_CODALM,  ALM_DESCRI AS UBI_ALMACEN,  UBI_PASILL,  UBI_ANAQUE,  UBI_NIVEL,  UBI_SUBNIV  FROM 
 dpinvubifisica 
 INNER JOIN dpubicacfis ON UXP_CODUBI=UBI_CODIGO  LEFT  JOIN DPALMACEN ON ALM_CODSUC=UBI_CODSUC AND ALM_CODIGO=UBI_CODALM 
 GROUP BY UXP_CODIGO,UXP_CODUBI;

-- 302
 CREATE OR REPLACE VIEW  VIEW_INVUBIFISPAS AS 
SELECT   UXP_CODSUC AS CPP_CODSUC,  UXP_CODALM AS CPP_CODALM,  UXP_PASILL AS CPP_PASILL,  COUNT(*)   AS CPP_CANTID  FROM 
 DPINVUBIFISICA 
 GROUP BY UXP_CODSUC,UXP_CODALM,UXP_PASILL
;

-- 303
 CREATE OR REPLACE VIEW  VIEW_INVULTIMACOMPRA AS 
SELECT   MOV_CODSUC     AS ULT_CODSUC,  MOV_CODIGO     AS ULT_CODIGO,    MAX(CONCAT(MOV_FECHA,MOV_HORA)) AS ULT_FCHHOR  FROM 
 DPMOVINV  WHERE MOV_INVACT=1 AND MOV_CONTAB=1 
 GROUP BY MOV_CODSUC,MOV_CODIGO 
 ORDER BY MOV_CODSUC,MOV_CODIGO
;

-- 304
 CREATE OR REPLACE VIEW  VIEW_INVULTCOMPRASUC AS 
SELECT                                       MOV_CODSUC     AS ULT_CODSUC,                                      MOV_CODIGO     AS ULT_CODIGO,                                        MAX(MOV_FECHA) AS ULT_FECHA,                  MOV_HORA       AS ULT_HORA,        CONCAT(MOV_FECHA,MOV_HORA) AS ULT_FCHHOR                    FROM 
 DPMOVINV                                      WHERE (MOV_APLORG="C") AND MOV_INVACT=1 AND MOV_CONTAB=1                         
 GROUP BY MOV_CODSUC,MOV_CODIGO                                     
 ORDER BY MOV_CODSUC,MOV_CODIGO                  ,CONCAT(MOV_FECHA,MOV_HORA) DESC
;

-- 305
 CREATE OR REPLACE VIEW  VIEW_INVULTENTSUC AS 
SELECT                                 MOV_CODSUC     AS ULE_CODSUC,                                MOV_CODIGO     AS ULE_CODIGO,                                  MAX(MOV_FECHA) AS ULE_FECHA,            MOV_HORA       AS ULE_HORA              FROM 
 DPMOVINV                                WHERE (MOV_APLORG="C" OR MOV_APLORG="I")  AND MOV_INVACT=1 AND MOV_CONTAB=1                   
 GROUP BY MOV_CODSUC,MOV_CODIGO                               
 ORDER BY MOV_CODSUC,MOV_CODIGO            ,CONCAT(MOV_FECHA,MOV_HORA) DESC
;

-- 306
 CREATE OR REPLACE VIEW  VIEW_DPDOCPROMAXFCHP AS 
SELECT   DOC_CODSUC     AS MAX_CODSUC,  DOC_CODIGO     AS MAX_CODIGO,  MAX(DOC_FECHA) AS MAX_FECHA  FROM 
 DPDOCPRO  WHERE DOC_TIPTRA="P" AND DOC_CXP<>0 AND DOC_ACT=1 
 GROUP BY DOC_CODSUC,DOC_CODIGO 
 ORDER BY DOC_CODSUC,DOC_CODIGO
;

-- 307
 CREATE OR REPLACE VIEW  VIEW_DPIVAFCHMAX AS 
SELECT IVM_FECHA AS IVA_FCHMAX      FROM 
 DPIVATAB     
 ORDER BY IVM_FECHA DESC LIMIT 1
;

-- 308
 CREATE OR REPLACE VIEW  VIEW_INVULTVENTA AS 
SELECT                                       MOV_CODIGO     AS ULT_CODIGO,                                        MAX(MOV_FECHA) AS ULT_FECHA,                  MOV_HORA       AS ULT_HORA                  FROM 
 DPMOVINV                                      WHERE (MOV_APLORG="V")  AND MOV_INVACT=1 AND MOV_CONTAB=-1                         
 GROUP BY MOV_CODIGO                                     
 ORDER BY MOV_CODIGO,CONCAT(MOV_FECHA,MOV_HORA) DESC
;

-- 309
 CREATE OR REPLACE VIEW  VIEW_INVULTVENTASUC AS 
SELECT                                     MOV_CODSUC     AS ULT_CODSUC,                                    MOV_CODIGO     AS ULT_CODIGO,                                      MAX(MOV_FECHA) AS ULT_FECHA,                MOV_HORA       AS ULT_HORA                  FROM 
 DPMOVINV                                    WHERE (MOV_APLORG="V") AND MOV_INVACT=1 AND MOV_CONTAB=-1                       
 GROUP BY MOV_CODSUC,MOV_CODIGO                                   
 ORDER BY MOV_CODSUC,MOV_CODIGO                ,CONCAT(MOV_FECHA,MOV_HORA) DESC
;

-- 310
 CREATE OR REPLACE VIEW  VIEW_INVULTVENTASUCL AS 
SELECT                                       MOV_CODSUC     AS ULT_CODSUC,                                      MOV_CODIGO     AS ULT_CODIGO,                                        MAX(MOV_FECHA) AS ULT_FECHA,                  MOV_HORA       AS ULT_HORA ,    MOV_LISTA      AS ULT_LISTA,  MOV_UNDMED     AS ULT_UNDMED                   FROM 
 DPMOVINV                                      WHERE (MOV_APLORG="V") AND MOV_INVACT=1 AND MOV_CONTAB=-1 AND MOV_LISTA<>""                       
 GROUP BY MOV_CODSUC,MOV_CODIGO,MOV_LISTA,MOV_UNDMED                                     
 ORDER BY MOV_CODSUC,MOV_CODIGO,MOV_LISTA,MOV_UNDMED                  ,CONCAT(MOV_FECHA,MOV_HORA) DESC
;

-- 311
 CREATE OR REPLACE VIEW  VIEW_MOVINVULTREGCLIPRO AS 
SELECT  MOV_APLORG AS ULT_APLORG, MOV_CODCTA AS ULT_CODCTA, MOV_CODIGO AS ULT_CODIGO, MAX(CONCAT(MOV_FECHA,MOV_HORA)) AS ULT_FCHHOR  FROM 
 dpmovinv  WHERE ((MOV_APLORG="V" AND MOV_CONTAB<0) OR (MOV_APLORG="C" AND MOV_CONTAB>0)) AND MOV_INVACT=1 
 GROUP BY MOV_CODCTA,MOV_CODIGO 
 ORDER BY MOV_CODCTA,MOV_CODIGO;

-- 312
 CREATE OR REPLACE VIEW  VIEW_UNDMEDXINV AS 
SELECT     IME_CODIGO,    IME_UNDMED,    COUNT(*) AS IME_CANTID    FROM 
 dpinvmed   
 GROUP BY IME_CODIGO
;

-- 313
 CREATE OR REPLACE VIEW  VIEW_TABXUSU AS 
SELECT     TXU_TABLA,    TXU_CODIGO,    COUNT(*) AS TXU_CANTID    FROM 
 dptabxusu   
 GROUP BY TXU_TABLA,TXU_CODIGO
;

-- 314
 CREATE OR REPLACE VIEW  VIEW_DPINVUTILIZ AS 
SELECT   INV_UTILIZ,  COUNT(*) AS INV_CANTID  FROM 
 DPINV 
 GROUP BY INV_UTILIZ 
 ORDER BY INV_UTILIZ
;

-- 315
 CREATE OR REPLACE VIEW  VIEW_INVVALCOMPRAS AS 
SELECT               MOV_CODSUC AS COM_CODSUC,              MOV_CODIGO AS COM_CODIGO,             
 SUM(MOV_TOTAL)            AS COM_TOTAL,             
 SUM(MOV_CANTID*MOV_CXUND) AS COM_CANUND,             
 SUM(MOV_TOTAL)/SUM(MOV_CANTID*MOV_CXUND) AS COM_PROMEDIO              FROM 
 DPMOVINV              WHERE MOV_INVACT=1 AND MOV_CONTAB=1             
 GROUP BY MOV_CODSUC,MOV_CODIGO
;

-- 316
 CREATE OR REPLACE VIEW  VIEW_EPED_VENDEDORES AS 
SELECT    VEN_CODIGO AS codigo,                  VEN_NOMBRE AS nombre,                    VEN_LOGIN AS usuario,                    VEN_CLAVE AS clave,                    IF(VEN_SITUAC="A",1,0) AS status,                VEN_FCHACT AS date,            VEN_EMAIL  AS email,              0 AS UPDATEINV,              0 AS UPDATECLI,              0 AS UPDATECXC      FROM 
    DPVENDEDOR    ;

-- 317
 CREATE OR REPLACE VIEW  VIEW_VTAXPROSUC AS 
SELECT     MOV_CODSUC AS VTA_CODSUC,    MOV_CODCTA AS VTA_CODCTA,    MOV_CODIGO AS VTA_CODIGO,   
 SUM(MOV_CANTID*MOV_CXUND*MOV_CONTAB*-1) AS VTA_CANUND    FROM 
 DPMOVINV    WHERE MOV_CONTAB<>0 AND MOV_APLORG="V"   
 GROUP BY MOV_CODSUC,MOV_CODCTA,MOV_CODIGO   
 ORDER BY MOV_CODSUC,MOV_CODIGO,MOV_CODCTA
;

-- 318
 CREATE OR REPLACE VIEW  VIEW_VENTAS AS 
SELECT MOV_CODIGO AS id_detalle, inv_descri AS descripcion, mov_cantid AS cantidad, SLD_CONTAB AS stock, mov_fecha AS fecha, mov_precio AS precio,  mov_total  AS total  FROM 
 dpmovinv 
 INNER JOIN dpinv         ON MOV_CODIGO=INV_CODIGO 
 INNER JOIN DPINVSLD      ON INV_CODIGO=SLD_CODIGO  WHERE MOV_APLORG="V" AND MOV_TIPDOC="FAV" AND MOV_INVACT=1 
 GROUP BY MOV_DOCUME 
 ORDER BY MOV_DOCUME;

-- 319
 CREATE OR REPLACE VIEW  VIEW_DPCLI_VTA AS 
SELECT  MOV_CODSUC AS INV_CODSUC, MOV_CODCTA AS CLI_CODIGO, CLI_NOMBRE, MOV_FECHA       AS INV_FECHA ,
 SUM(MOV_CANTID*MOV_CXUND) AS INV_CANTID,
 SUM(MOV_PESO  ) AS INV_PESO  ,
 SUM(MOV_TOTAL ) AS INV_TOTAL ,
 SUM(MOV_MTODIV) AS INV_MTODIV,
 SUM(MOV_MTODIV/MOV_TOTAL) AS INV_VALDIV,
 SUM(MOV_COSTO)            AS INV_COSTO , DATEDIFF(MAX(MOV_FECHA), MIN(MOV_FECHA)) / (COUNT(MOV_FECHA) - 1) AS INV_DIAFRQ,  COUNT(*)                  AS INV_COUNT  FROM 
 DPMOVINV
 INNER JOIN dptipdoccli ON MOV_TIPDOC=TDC_TIPO AND TDC_ESTVTA=1 
 INNER JOIN dpclientes  ON MOV_CODCTA=CLI_CODIGO  WHERE MOV_APLORG="V" AND MOV_INVACT=1 AND MOV_TIPASO<>"NEN" 
 GROUP BY INV_CODSUC,MOV_CODCTA,MOV_FECHA 
 ORDER BY MOV_FECHA;

-- 320
 CREATE OR REPLACE VIEW  VIEW_DPGRUPO_VTA AS 
SELECT  MOV_CODSUC AS GRU_CODSUC, GRU_CODIGO, GRU_DESCRI, MOV_FECHA       AS GRU_FECHA ,
 SUM(MOV_CANTID*MOV_CXUND*(MOV_FISICO*-1)) AS GRU_CANTID,
 SUM(MOV_PESO  *(MOV_FISICO*-1)) AS GRU_PESO  ,
 SUM(MOV_TOTAL *(MOV_FISICO*-1)) AS GRU_TOTAL ,
 SUM(MOV_MTODIV*(MOV_FISICO*-1)) AS GRU_MTODIV,
 SUM((MOV_MTODIV/MOV_TOTAL)*(MOV_FISICO*-1)) AS GRU_VALDIV,
 SUM(MOV_COSTO)            AS GRU_COSTO , MIN(MOV_FECHA)            AS GRU_DESDE , MAX(MOV_FECHA)            AS GRU_HASTA , DATEDIFF(MAX(MOV_FECHA), MIN(MOV_FECHA)) / (COUNT(MOV_FECHA) - 1) AS GRU_DIAFRQ,  COUNT(*)                  AS GRU_COUNT   FROM 
 DPMOVINV 
 INNER JOIN dpinv       ON MOV_CODIGO=INV_CODIGO 
 INNER JOIN dpgru       ON INV_GRUPO =GRU_CODIGO 
 INNER JOIN dptipdoccli ON MOV_TIPDOC=TDC_TIPO AND TDC_ESTVTA=1  WHERE MOV_APLORG="V" AND MOV_INVACT=1 AND MOV_TIPASO<>"NEN" 
 GROUP BY GRU_CODSUC,INV_GRUPO,MOV_FECHA 
 ORDER BY GRU_CODSUC,INV_GRUPO,MOV_FECHA;

-- 321
 CREATE OR REPLACE VIEW  VIEW_DPGRUPO_VTAMES AS 
SELECT  MOV_CODSUC AS GRU_CODSUC, GRU_CODIGO, GRU_DESCRI, YEAR(MOV_FECHA)           AS GRU_ANO   , MONTH(MOV_FECHA)          AS GRU_MES   ,
 SUM(MOV_CANTID*MOV_CXUND*(MOV_FISICO*-1)) AS GRU_CANTID,
 SUM(MOV_PESO  *(MOV_FISICO*-1)) AS GRU_PESO  ,
 SUM(MOV_TOTAL *(MOV_FISICO*-1)) AS GRU_TOTAL ,
 SUM(MOV_MTODIV*(MOV_FISICO*-1)) AS GRU_MTODIV,
 SUM((MOV_MTODIV/MOV_TOTAL)*(MOV_FISICO*-1)) AS GRU_VALDIV,
 SUM(MOV_COSTO)            AS GRU_COSTO , DATEDIFF(MAX(MOV_FECHA), MIN(MOV_FECHA)) / (COUNT(MOV_FECHA) - 1) AS GRU_DIAFRQ,  COUNT(*)                  AS GRU_COUNT   FROM 
 DPMOVINV 
 INNER JOIN dpinv       ON MOV_CODIGO=INV_CODIGO 
 INNER JOIN dpgru       ON INV_GRUPO =GRU_CODIGO 
 INNER JOIN dptipdoccli ON MOV_TIPDOC=TDC_TIPO AND TDC_ESTVTA=1  WHERE MOV_APLORG="V" AND MOV_INVACT=1 AND MOV_TIPASO<>"NEN" 
 GROUP BY GRU_CODSUC,INV_GRUPO,YEAR(MOV_FECHA),MONTH(MOV_FECHA) 
 ORDER BY GRU_CODSUC,INV_GRUPO,YEAR(MOV_FECHA),MONTH(MOV_FECHA);

-- 322
 CREATE OR REPLACE VIEW  VIEW_DPMARCAS_VTA AS 
SELECT  MOV_CODSUC AS MAR_CODSUC, MAR_CODIGO, MAR_DESCRI, MOV_FECHA       AS MAR_FECHA ,
 SUM(MOV_CANTID*MOV_CXUND*(MOV_FISICO*-1)) AS MAR_CANTID,
 SUM(MOV_PESO  *(MOV_FISICO*-1)) AS MAR_PESO  ,
 SUM(MOV_TOTAL *(MOV_FISICO*-1)) AS MAR_TOTAL ,
 SUM(MOV_MTODIV*(MOV_FISICO*-1)) AS MAR_MTODIV,
 SUM((MOV_MTODIV/MOV_TOTAL)*(MOV_FISICO*-1)) AS MAR_VALDIV,
 SUM(MOV_COSTO)            AS MAR_COSTO , MIN(MOV_FECHA)            AS MAR_DESDE , MAX(MOV_FECHA)            AS MAR_HASTA , DATEDIFF(MAX(MOV_FECHA), MIN(MOV_FECHA)) / (COUNT(MOV_FECHA) - 1) AS MAR_DIAFRQ,  COUNT(*)                  AS MAR_COUNT   FROM 
 DPMOVINV 
 INNER JOIN dpinv       ON MOV_CODIGO=INV_CODIGO 
 INNER JOIN dpmarcas    ON INV_CODMAR=MAR_CODIGO 
 INNER JOIN dptipdoccli ON MOV_TIPDOC=TDC_TIPO AND TDC_ESTVTA=1  WHERE MOV_APLORG="V" AND MOV_INVACT=1 AND MOV_TIPASO<>"NEN" 
 GROUP BY MAR_CODSUC,INV_CODMAR,MOV_FECHA 
 ORDER BY MAR_CODSUC,INV_CODMAR,MOV_FECHA;

-- 323
 CREATE OR REPLACE VIEW  VIEW_DPMARCAS_VTAMES AS 
SELECT  MOV_CODSUC AS MAR_CODSUC, MAR_CODIGO, MAR_DESCRI, MOV_FECHA       AS MAR_FECHA ,
 SUM(MOV_CANTID*MOV_CXUND*(MOV_FISICO*-1)) AS MAR_CANTID,
 SUM(MOV_PESO  *(MOV_FISICO*-1)) AS MAR_PESO  ,
 SUM(MOV_TOTAL *(MOV_FISICO*-1)) AS MAR_TOTAL ,
 SUM(MOV_MTODIV*(MOV_FISICO*-1)) AS MAR_MTODIV,
 SUM((MOV_MTODIV/MOV_TOTAL)*(MOV_FISICO*-1)) AS MAR_VALDIV,
 SUM(MOV_COSTO)            AS MAR_COSTO , MIN(MOV_FECHA)            AS MAR_DESDE , MAX(MOV_FECHA)            AS MAR_HASTA , DATEDIFF(MAX(MOV_FECHA), MIN(MOV_FECHA)) / (COUNT(MOV_FECHA) - 1) AS MAR_DIAFRQ,  COUNT(*)                  AS MAR_COUNT   FROM 
 DPMOVINV 
 INNER JOIN dpinv       ON MOV_CODIGO=INV_CODIGO 
 INNER JOIN dpmarcas    ON INV_CODMAR=MAR_CODIGO 
 INNER JOIN dptipdoccli ON MOV_TIPDOC=TDC_TIPO AND TDC_ESTVTA=1  WHERE MOV_APLORG="V" AND MOV_INVACT=1 AND MOV_TIPASO<>"NEN" 
 GROUP BY MAR_CODSUC,INV_CODMAR,MOV_FECHA 
 ORDER BY MAR_CODSUC,INV_CODMAR,MOV_FECHA;

-- 324
 CREATE OR REPLACE VIEW  VIEW_DPINV_VTA AS 
SELECT  MOV_CODSUC AS INV_CODSUC, INV_CODIGO, INV_DESCRI, INV_GRUPO , INV_CODMAR, MOV_FECHA       AS INV_FECHA ,
 SUM(MOV_CANTID*MOV_CXUND*(MOV_FISICO*-1)) AS INV_CANTID,
 SUM(MOV_PESO  *(MOV_FISICO*-1)) AS INV_PESO  ,
 SUM(MOV_TOTAL *(MOV_FISICO*-1)) AS INV_TOTAL ,
 SUM(MOV_MTODIV*(MOV_FISICO*-1)) AS INV_MTODIV,
 SUM((MOV_MTODIV/MOV_TOTAL)*(MOV_FISICO*-1)) AS INV_VALDIV,
 SUM(MOV_COSTO)            AS INV_COSTO , DATEDIFF(MAX(MOV_FECHA), MIN(MOV_FECHA)) / (COUNT(MOV_FECHA) - 1) AS INV_DIAFRQ,  COUNT(*)                  AS INV_COUNT   FROM 
 DPMOVINV 
 INNER JOIN dpinv       ON MOV_CODIGO=INV_CODIGO 
 INNER JOIN dptipdoccli ON MOV_TIPDOC=TDC_TIPO AND TDC_ESTVTA=1  WHERE MOV_APLORG="V" AND MOV_INVACT=1 AND MOV_TIPASO<>"NEN" 
 GROUP BY INV_CODSUC,INV_CODIGO,INV_DESCRI,INV_GRUPO,INV_CODMAR,MOV_FECHA 
 ORDER BY MOV_FECHA;

-- 325
 CREATE OR REPLACE VIEW  VIEW_DPCLI_VEN AS 
SELECT  MOV_CODSUC AS INV_CODSUC, DOC_CODVEN AS VEN_CODIGO, VEN_NOMBRE, MOV_FECHA       AS INV_FECHA ,
 SUM(MOV_CANTID*MOV_CXUND) AS INV_CANTID,
 SUM(MOV_PESO  ) AS INV_PESO  ,
 SUM(MOV_TOTAL ) AS INV_TOTAL ,
 SUM(MOV_MTODIV) AS INV_MTODIV,
 SUM(MOV_MTODIV/MOV_TOTAL) AS INV_VALDIV,
 SUM(MOV_COSTO)            AS INV_COSTO , DATEDIFF(MAX(MOV_FECHA), MIN(MOV_FECHA)) / (COUNT(MOV_FECHA) - 1) AS INV_DIAFRQ,  COUNT(*)                  AS INV_COUNT  FROM 
 DPMOVINV
 INNER JOIN dptipdoccli ON MOV_TIPDOC=TDC_TIPO AND TDC_ESTVTA=1 
 INNER JOIN dpdoccli    ON MOV_CODSUC=DOC_CODSUC AND MOV_TIPDOC=DOC_TIPDOC AND MOV_DOCUME=DOC_NUMERO AND DOC_TIPTRA="D" AND DOC_ACT=1 
 INNER JOIN dpvendedor  ON DOC_CODVEN=VEN_CODIGO  WHERE MOV_APLORG="V" AND MOV_INVACT=1 AND MOV_TIPASO<>"NEN" 
 GROUP BY INV_CODSUC,DOC_CODVEN,MOV_FECHA 
 ORDER BY MOV_FECHA;

-- 326
 CREATE OR REPLACE VIEW  VIEW_TIPDOCPRO_Y AS 
SELECT  TDC_TIPO   AS TDY_TIPO,   TDC_DESCRI AS TDY_DESCRI, TDC_DOCDES AS TDY_DOCDES  FROM 
 DPTIPDOCPRO;

-- 327
 CREATE OR REPLACE VIEW  VIEW_DPPRECIOXINV AS 
SELECT     dpprecios.PRE_LISTA AS LIS_LISTA,    dpprecios.PRE_CODIGO AS LIS_CODIGO    FROM 
 dpprecios    group by PRE_LISTA,PRE_CODIGO    order by PRE_LISTA
;

-- 328
 CREATE OR REPLACE VIEW  VIEW_DPPRECIOMAXFCH AS 
SELECT     PRE_LISTA AS PMF_LISTA,    MIN(PRE_FECHA) AS PMF_FCHMIN,    MAX(PRE_FECHA) AS PMF_FCHMAX,    (to_days(now()) - to_days(max(PRE_FECHA))) AS PMF_DIAS    FROM 
 DPPRECIOS   
 GROUP BY PRE_LISTA   
 ORDER BY PRE_LISTA,PRE_FECHA DESC
;

-- 329
 CREATE OR REPLACE VIEW  VIEW_DPVEN_VTA AS 
SELECT  MOV_CODSUC AS INV_CODSUC, DOC_CODVEN AS VEN_CODIGO, VEN_NOMBRE, MOV_FECHA       AS INV_FECHA ,
 SUM(MOV_CANTID*MOV_CXUND) AS INV_CANTID,
 SUM(MOV_PESO  ) AS INV_PESO  ,
 SUM(MOV_TOTAL ) AS INV_TOTAL ,
 SUM(MOV_MTODIV) AS INV_MTODIV,
 SUM(MOV_MTODIV/MOV_TOTAL) AS INV_VALDIV,
 SUM(MOV_COSTO)            AS INV_COSTO , DATEDIFF(MAX(MOV_FECHA), MIN(MOV_FECHA)) / (COUNT(MOV_FECHA) - 1) AS INV_DIAFRQ,  COUNT(*)                  AS INV_COUNT  FROM 
 DPMOVINV
 INNER JOIN dptipdoccli ON MOV_TIPDOC=TDC_TIPO AND TDC_ESTVTA=1 
 INNER JOIN dpdoccli    ON MOV_CODSUC=DOC_CODSUC AND MOV_TIPDOC=DOC_TIPDOC AND MOV_DOCUME=DOC_NUMERO AND DOC_TIPTRA="D" AND DOC_ACT=1 
 INNER JOIN dpvendedor  ON DOC_CODVEN=VEN_CODIGO  WHERE MOV_APLORG="V" AND MOV_INVACT=1 AND MOV_TIPASO<>"NEN" 
 GROUP BY INV_CODSUC,DOC_CODVEN,MOV_FECHA 
 ORDER BY MOV_FECHA;

-- 330
 CREATE OR REPLACE VIEW  VIEW_DOCPRO_CTA_IVA AS 
SELECT CCD_CODSUC AS IVD_CODSUC,CCD_TIPDOC AS IVD_TIPDOC,CCD_CODCTA AS IVD_CODCTA,CCD_NUMERO AS IVD_DOCUME,SUM(IF(CCD_TIPIVA="EX",CCD_MONTO,0)) AS IVD_MTOEX,SUM(IF(CCD_TIPIVA="GN",CCD_MONTO,0)) AS IVD_MTOGN,SUM(IF(CCD_TIPIVA="RD",CCD_MONTO,0)) AS IVD_MTORD,SUM(IF(CCD_TIPIVA="S1",CCD_MONTO,0)) AS IVD_MTOS1,SUM(IF(CCD_TIPIVA="XX",CCD_MONTO,0)) AS IVD_MTOXX,SUM(IF(CCD_TIPIVA="EX",CCD_TOTAL,0)) AS IVD_TOTEX,SUM(IF(CCD_TIPIVA="GN",CCD_TOTAL,0)) AS IVD_TOTGN,SUM(IF(CCD_TIPIVA="RD",CCD_TOTAL,0)) AS IVD_TOTRD,SUM(IF(CCD_TIPIVA="S1",CCD_TOTAL,0)) AS IVD_TOTS1,SUM(IF(CCD_TIPIVA="XX",CCD_TOTAL,0)) AS IVD_TOTXX ,SUM(CCD_TOTAL) AS IVD_BASE  FROM 
 DPDOCPROCTA  WHERE CCD_ACT=1
 GROUP BY CCD_CODSUC,CCD_TIPDOC,CCD_CODCTA,CCD_NUMERO;

-- 331
 CREATE OR REPLACE VIEW  VIEW_DOCPRO_MOV_IVA AS 
SELECT MOV_CODSUC AS IVA_CODSUC,MOV_TIPDOC AS IVA_TIPDOC,MOV_CODCTA AS IVA_CODCTA,MOV_DOCUME AS IVA_DOCUME,SUM(IF(MOV_TIPIVA="EX",MOV_TOTAL,0)) AS IVA_MTOEX,SUM(IF(MOV_TIPIVA="GN",MOV_TOTAL,0)) AS IVA_MTOGN,SUM(IF(MOV_TIPIVA="RD",MOV_TOTAL,0)) AS IVA_MTORD,SUM(IF(MOV_TIPIVA="S1",MOV_TOTAL,0)) AS IVA_MTOS1,SUM(IF(MOV_TIPIVA="XX",MOV_TOTAL,0)) AS IVA_MTOXX,SUM(IF(MOV_TIPIVA="EX",MOV_TOTAL,0)) AS IVA_TOTEX,SUM(IF(MOV_TIPIVA="GN",MOV_TOTAL,0)) AS IVA_TOTGN,SUM(IF(MOV_TIPIVA="RD",MOV_TOTAL,0)) AS IVA_TOTRD,SUM(IF(MOV_TIPIVA="S1",MOV_TOTAL,0)) AS IVA_TOTS1,SUM(IF(MOV_TIPIVA="XX",MOV_TOTAL,0)) AS IVA_TOTXX,SUM(MOV_TOTAL) AS IVA_BASE  FROM 
 DPMOVINV  WHERE MOV_APLORG="C" AND MOV_INVACT=1
 GROUP BY MOV_CODSUC,MOV_TIPDOC,MOV_CODCTA,MOV_DOCUME;

-- 332
 CREATE OR REPLACE VIEW  VIEW_DOCCLI_MOV_IVA AS 
SELECT MOV_CODSUC AS IVA_CODSUC,MOV_TIPDOC AS IVA_TIPDOC,MOV_DOCUME AS IVA_DOCUME,SUM(IF(MOV_TIPIVA="EX",MOV_TOTAL,0)) AS IVA_TOTEX,SUM(IF(MOV_TIPIVA="GN",MOV_TOTAL,0)) AS IVA_TOTGN,SUM(IF(MOV_TIPIVA="RD",MOV_TOTAL,0)) AS IVA_TOTRD,SUM(IF(MOV_TIPIVA="S1",MOV_TOTAL,0)) AS IVA_TOTS1,SUM(IF(MOV_TIPIVA="XX",MOV_TOTAL,0)) AS IVA_TOTXX,SUM(IF(MOV_TIPIVA="EX",MOV_TOTAL,0)) AS IVA_MTOEX,SUM(IF(MOV_TIPIVA="GN",MOV_TOTAL,0)) AS IVA_MTOGN,SUM(IF(MOV_TIPIVA="RD",MOV_TOTAL,0)) AS IVA_MTORD,SUM(IF(MOV_TIPIVA="S1",MOV_TOTAL,0)) AS IVA_MTOS1,SUM(IF(MOV_TIPIVA="XX",MOV_TOTAL,0)) AS IVA_MTOXX,SUM(MOV_TOTAL) AS IVA_BASE  FROM 
 DPMOVINV  WHERE MOV_APLORG="V" AND MOV_INVACT=0 
 GROUP BY MOV_CODSUC,MOV_TIPDOC,MOV_DOCUME;

-- 333
 CREATE OR REPLACE VIEW  VIEW_DOCCLI_CTA_IVA AS 
SELECT CCD_CODSUC AS IVD_CODSUC,CCD_TIPDOC AS IVD_TIPDOC,CCD_NUMERO AS IVD_DOCUME,SUM(IF(CCD_TIPIVA="EX",CCD_TOTAL,0)) AS IVD_TOTEX,SUM(IF(CCD_TIPIVA="GN",CCD_TOTAL,0)) AS IVD_TOTGN,SUM(IF(CCD_TIPIVA="RD",CCD_TOTAL,0)) AS IVD_TOTRD,SUM(IF(CCD_TIPIVA="S1",CCD_TOTAL,0)) AS IVD_TOTS1,SUM(IF(CCD_TIPIVA="XX",CCD_TOTAL,0)) AS IVD_TOTXX,SUM(IF(CCD_TIPIVA="EX",CCD_MONTO,0)) AS IVD_MTOEX,SUM(IF(CCD_TIPIVA="GN",CCD_MONTO,0)) AS IVD_MTOGN,SUM(IF(CCD_TIPIVA="RD",CCD_MONTO,0)) AS IVD_MTORD,SUM(IF(CCD_TIPIVA="S1",CCD_MONTO,0)) AS IVD_MTOS1,SUM(IF(CCD_TIPIVA="XX",CCD_MONTO,0)) AS IVD_MTOXX ,SUM(CCD_TOTAL) AS IVD_BASE  FROM 
 DPDOCCLICTA  WHERE CCD_ACT=1
 GROUP BY CCD_CODSUC,CCD_TIPDOC,CCD_NUMERO;

-- 334
 CREATE OR REPLACE VIEW  VIEW_DPDIARIO_ANO AS 
SELECT  FCH_ANO, MIN(FCH_DESDE)  AS FCH_DESDE , MAX(FCH_HASTA)  AS FCH_HASTA , MAX(FCH_MAXDIV) AS FCH_MAXDIV, FCH_CODMON      AS FCH_CODMON, IPC_TASA        AS FCH_IPC   , IPC_INPC        AS FCH_INPC  , IPC_MES         AS FCH_IPCMES, HMN_VALOR       AS FCH_VALCAM  FROM 
 VIEW_DPDIARIO_MES  LEFT JOIN dphismon ON FCH_MAXDIV=HMN_FECHA AND HMN_CODIGO="DBC"  LEFT JOIN admconfig51.dpipc ON FCH_ANO=IPC_ANO AND FCH_MES=IPC_MES 
 GROUP BY FCH_ANO 
 ORDER BY FCH_ANO;

-- 335
 CREATE OR REPLACE VIEW  VIEW_DPHISMON_MES_VALOR AS 
SELECT  VIEW_DPHISMON_MES.HMN_CODIGO, VIEW_DPHISMON_MES.HMN_ANO, VIEW_DPHISMON_MES.HMN_MES, VIEW_DPHISMON_MES.HMN_FECHA, DPHISMON.HMN_VALOR AS HMN_VALOR  FROM 
 VIEW_DPHISMON_MES 
 INNER JOIN dphismon ON  VIEW_DPHISMON_MES.HMN_CODIGO=dphismon.HMN_CODIGO AND VIEW_DPHISMON_MES.HMN_FECHA =dphismon.HMN_FECHA
;

-- 336
 CREATE OR REPLACE VIEW  VIEW_DPDIARIOCXP AS 
SELECT  CXD_CODSUC AS CXP_CODSUC,"CXP" AS CXP_TIPDOC,"Cuentas por Pagar" AS CXP_DESCRI,CXD_FCHMAX AS CXP_FECHA,PRO_TIPO AS CXP_REFERE,SUM(CXD_CXPDIV) AS CXP_MTODIV  FROM 
 VIEW_DOCPROCXPDIV   LEFT JOIN dpproveedor ON PRO_CODIGO=CXD_CODIGO 
 GROUP BY CXD_CODSUC,CXD_FCHMAX,PRO_TIPO
 ORDER BY CXD_CODSUC,CXD_FCHMAX;

-- 337
 CREATE OR REPLACE VIEW  VIEW_DPDIARIOCXC AS 
SELECT  CXD_CODSUC AS CXC_CODSUC,"CXC" AS CXC_TIPDOC,"Cuentas por Cobrar" AS CXC_DESCRI,CXD_FCHMAX AS CXC_FECHA,CONCAT(CLC_DESCRI," ",ACT_DESCRI) AS CXC_REFERE,SUM(CXD_CXCDIV) AS CXC_MTODIV  FROM 
 view_docclicxcdiv  LEFT JOIN dpclientes    ON CLI_CODIGO=CXD_CODIGO  LEFT JOIN DPCLICLA      ON CLI_CODCLA=CLC_CODIGO  LEFT JOIN DPACTIVIDAD_E ON CLI_ACTIVI=ACT_CODIGO 
 GROUP BY CXD_CODSUC,CXD_FCHMAX,CONCAT(CLC_DESCRI,ACT_DESCRI)
 ORDER BY CXD_CODSUC,CXD_FCHMAX;

-- 338
 CREATE OR REPLACE VIEW  VIEW_DPDOCPROPROGDIARIO AS 
SELECT   PLP_CODSUC AS PXD_CODSUC, PLP_TIPDOC AS PXD_TIPDOC, PGC_CODIGO AS PXD_CODPRO, TDC_DESCRI AS PXD_DESCRI, PLP_FECHA  AS PXD_FECHA,  PGC_REFERE AS PXD_REFERE, 
 SUM(IF(PLP_VALCAM>1,ROUND(PLP_MONTO/PLP_VALCAM,2),PLP_MTODIV))  AS PXD_MTODIV, 
 SUM(ROUND(PLP_MTOCAL/PLP_VALCAM,2)) AS PXD_MTOCAL,
 SUM(IF(DOC_NETO IS NULL,0,ROUND(DOC_NETO/DOC_VALCAM,2))) AS PXD_MTONET,
 SUM(IF(PAG_NETO IS NULL,0,ROUND(PAG_NETO/PAG_VALCAM,2))) AS PXD_MTOPAG,
 SUM(IF(PLP_MTODIV<>0,PLP_MTODIV,ROUND(PLP_MONTO/PLP_VALCAM,2)))+
 SUM(IF(DOC_NETO IS NULL,(IF(PLP_MTOCAL<>0,ROUND(PLP_MTOCAL/PLP_VALCAM,2),ROUND(PLP_MONTO/PLP_VALCAM,2))),ROUND(DOC_NETO/DOC_VALCAM,2)))-
 SUM(IF(PAG_NETO IS NULL,0,ROUND(PAG_NETO/PAG_VALCAM,2))) AS PXD_MTOCXP,
 SUM(ROUND(PLP_MTOCAL/PLP_VALCAM,2)) AS PXD_CALDIV FROM 
 DPDOCPROPROG 
 INNER JOIN DPTIPDOCPRO      ON PLP_TIPDOC=TDC_TIPO
 INNER JOIN DPPROVEEDORPROG  ON PLP_CODSUC=PGC_CODSUC AND PLP_CODIGO=PGC_CODIGO AND PLP_TIPDOC=PGC_TIPDOC AND PLP_REFERE=PGC_REFERE  LEFT  JOIN dpdocpro         ON PLP_CODSUC=DOC_CODSUC AND PLP_TIPDOC=DOC_TIPDOC AND PLP_CODIGO=DOC_CODIGO AND PLP_NUMREG=DOC_PPLREG AND PLP_NUMDOC=DOC_NUMERO AND DOC_TIPTRA="D" LEFT  JOIN VIEW_DPDOCPROPAG ON DOC_CODSUC=PAG_CODSUC AND DOC_TIPDOC=PAG_TIPDOC AND DOC_CODIGO=PAG_CODIGO AND DOC_NUMERO=PAG_NUMERO  WHERE 1=1 
 GROUP BY PLP_CODSUC,PLP_TIPDOC,PLP_FECHA,PGC_REFERE,PGC_CODIGO 
 ORDER BY PLP_CODSUC,PLP_TIPDOC,PLP_FECHA,PGC_REFERE,PGC_CODIGO;

-- 339
 CREATE OR REPLACE VIEW  VIEW_NMFCHCANTREC AS 
SELECT  FCH_CODSUC AS CRF_CODSUC, FCH_NUMERO AS CRF_NUMERO,
 SUM(IF(NMRECIBOS.REC_FORMAP="C",1,0))        AS CRF_CANCHQ,
 SUM(IF(NMRECIBOS.REC_FORMAP="E",1,0))        AS CRF_CANEFE,
 SUM(IF(NMRECIBOS.REC_FORMAP="T",1,0))        AS CRF_CANTRA,
 SUM(REC_MTOASG)                    AS CRF_MTOASG,
 SUM(REC_MTODED)                    AS CRF_MTODED,
 SUM(REC_NETO  )                    AS CRF_NETO  ,
 SUM(REC_NETO/REC_VALCAM)           AS CRF_MTODIV, AVG(REC_VALCAM)                    AS CRF_VALCAM,
 SUM(IF(NMRECIBOS.REC_FORMAP="C",REC_NETO,0)) AS CRF_MTOCHQ,
 SUM(IF(NMRECIBOS.REC_FORMAP="E",REC_NETO,0)) AS CRF_MTOEFE,
 SUM(IF(NMRECIBOS.REC_FORMAP="T",REC_NETO,0)) AS CRF_MTOTRA, COUNT(*)                                     AS CRF_CANTID  FROM 
 NMFECHAS 
 INNER JOIN NMRECIBOS       ON FCH_CODSUC=REC_CODSUC AND FCH_NUMERO=REC_NUMFCH 
 INNER JOIN VIEW_NMRECIBOS  ON VIEW_NMRECIBOS.REC_CODSUC=NMRECIBOS.REC_CODSUC AND VIEW_NMRECIBOS.REC_NUMERO=NMRECIBOS.REC_NUMERO 
 GROUP BY FCH_CODSUC,FCH_NUMERO 
 ORDER BY FCH_CODSUC,FCH_NUMERO;

-- 340
 CREATE OR REPLACE VIEW  VIEW_DPLIBINVDET_BIM AS 
SELECT                       DLI_CODSUC      AS RII_CODSUC,                      DLI_CODIGO      AS RII_CODIGO,                     
 SUM(DLI_COSVTA) AS RII_COSVTA,             
 SUM(DLI_CANVTA) AS RII_CANVTA,                              MIN(DLI_FECHA)  AS RII_DESDE,                      MAX(DLI_FECHA)  AS RII_HASTA,  FCH_DESDE       AS RII_FCHDES,    FCH_HASTA       AS RII_FCHHAS                          FROM 
                       VIEW_DPDIARIO_BIMEST                      
 INNER JOIN DPLIBINVDET ON DLI_FECHA>=FCH_DESDE AND DLI_FECHA<=FCH_HASTA                    WHERE DLI_COSVTA>0                     
 GROUP BY DLI_CODSUC,DLI_CODIGO
;

-- 341
 CREATE OR REPLACE VIEW  VIEW_DPLIBINVINI_BIM AS 
SELECT                     DLI_CODSUC AS RVI_CODSUC,                    DLI_CODIGO AS RVI_CODIGO,                    DLI_CANANT*DLI_COSANT AS RVI_VALINV,            DLI_CANANT            AS RVI_EXIINI,  RII_FCHDES            AS RVI_FCHDES,      RII_FCHHAS            AS RVI_FCHHAS                        FROM 
                    VIEW_DPLIBINVDET_BIM                    
 INNER JOIN DPLIBINVDET ON RII_CODSUC=DLI_CODSUC AND RII_CODIGO=DLI_CODIGO AND RII_DESDE=DLI_FECHA                              
 GROUP BY DLI_CODSUC,DLI_CODIGO,RII_FCHDES     
 ORDER BY DLI_CODSUC,DLI_CODIGO,RII_FCHHAS
;

-- 342
 CREATE OR REPLACE VIEW  VIEW_DPLIBINVFIN_BIM AS 
SELECT               DLI_CODSUC           AS RVF_CODSUC,              DLI_CODIGO           AS RVF_CODIGO,              DLI_SALDO*DLI_COSPRO AS RVF_VALINV,          DLI_SALDO            AS RVF_EXIFIN,    RII_FCHDES           AS RVF_FCHDES,      RII_FCHHAS           AS RVF_FCHHAS                FROM 
              VIEW_DPLIBINVDET_BIM                
 INNER JOIN DPLIBINVDET ON RII_CODSUC=DLI_CODSUC AND RII_CODIGO=DLI_CODIGO AND RII_HASTA=DLI_FECHA                        
 GROUP BY DLI_CODSUC,DLI_CODIGO,RII_FCHDES     
 ORDER BY DLI_CODSUC,DLI_CODIGO,RII_FCHHAS
;

-- 343
 CREATE OR REPLACE VIEW  VIEW_DPLIBINVDET_CUA AS 
SELECT                             DLI_CODSUC      AS RII_CODSUC,                            DLI_CODIGO      AS RII_CODIGO,                           
 SUM(DLI_COSVTA) AS RII_COSVTA,                   
 SUM(DLI_CANVTA) AS RII_CANVTA,                                    MIN(DLI_FECHA)  AS RII_DESDE,                            MAX(DLI_FECHA)  AS RII_HASTA,        FCH_DESDE       AS RII_FCHDES,          FCH_HASTA       AS RII_FCHHAS                                FROM 
                             VIEW_DPDIARIO_CUATRI                            
 INNER JOIN DPLIBINVDET ON DLI_FECHA>=FCH_DESDE AND DLI_FECHA<=FCH_HASTA                          WHERE DLI_COSVTA>0                           
 GROUP BY DLI_CODSUC,DLI_CODIGO,RII_FCHDES,RII_FCHHAS
;

-- 344
 CREATE OR REPLACE VIEW  VIEW_DPLIBINVINI_CUA AS 
SELECT                           DLI_CODSUC AS RVI_CODSUC,                          DLI_CODIGO AS RVI_CODIGO,                          DLI_CANANT*DLI_COSANT AS RVI_VALINV,                  DLI_CANANT            AS RVI_EXIINI,        RII_FCHDES            AS RVI_FCHDES,        RII_FCHHAS            AS RVI_FCHHAS                           FROM 
                          VIEW_DPLIBINVDET_CUA                          
 INNER JOIN DPLIBINVDET ON RII_CODSUC=DLI_CODSUC AND RII_CODIGO=DLI_CODIGO AND RII_DESDE=DLI_FECHA                                    
 GROUP BY DLI_CODSUC,DLI_CODIGO,RII_FCHDES       
 ORDER BY DLI_CODSUC,DLI_CODIGO,RII_FCHHAS
;

-- 345
 CREATE OR REPLACE VIEW  VIEW_DPLIBINVFIN_CUA AS 
SELECT                     DLI_CODSUC           AS RVF_CODSUC,                    DLI_CODIGO           AS RVF_CODIGO,                    DLI_SALDO*DLI_COSPRO AS RVF_VALINV,                DLI_SALDO            AS RVF_EXIFIN,        RII_FCHDES           AS RVF_FCHDES,          RII_FCHHAS           AS RVF_FCHHAS                       FROM 
                    VIEW_DPLIBINVDET_CUA                    
 INNER JOIN DPLIBINVDET ON RII_CODSUC=DLI_CODSUC AND RII_CODIGO=DLI_CODIGO AND RII_HASTA=DLI_FECHA                              
 GROUP BY DLI_CODSUC,DLI_CODIGO,RII_FCHDES,RII_FCHHAS       
 ORDER BY DLI_CODSUC,DLI_CODIGO        ,RII_FCHDES,RII_FCHHAS
;

-- 346
 CREATE OR REPLACE VIEW  VIEW_DPLIBINVDET_MES AS 
SELECT                           DLI_CODSUC      AS RII_CODSUC,                          DLI_CODIGO      AS RII_CODIGO,                         
 SUM(DLI_COSVTA) AS RII_COSVTA,                 
 SUM(DLI_CANVTA) AS RII_CANVTA,                                  MIN(DLI_FECHA)  AS RII_DESDE,                          MAX(DLI_FECHA)  AS RII_HASTA,      FCH_DESDE       AS RII_FCHDES,        FCH_HASTA       AS RII_FCHHAS                              FROM 
                           VIEW_DPDIARIO_MES                          
 INNER JOIN DPLIBINVDET ON DLI_FECHA>=FCH_DESDE AND DLI_FECHA<=FCH_HASTA                        WHERE DLI_COSVTA>0                         
 GROUP BY DLI_CODSUC,DLI_CODIGO
;

-- 347
 CREATE OR REPLACE VIEW  VIEW_DPLIBINVINI_MES AS 
SELECT                       DLI_CODSUC AS RVI_CODSUC,                      DLI_CODIGO AS RVI_CODIGO,                      DLI_CANANT*DLI_COSANT AS RVI_VALINV,              DLI_CANANT            AS RVI_EXIINI,    RII_FCHDES            AS RVI_FCHDES,        RII_FCHHAS            AS RVI_FCHHAS                        FROM 
                      VIEW_DPLIBINVDET_MES                      
 INNER JOIN DPLIBINVDET ON RII_CODSUC=DLI_CODSUC AND RII_CODIGO=DLI_CODIGO AND RII_DESDE=DLI_FECHA                                
 GROUP BY DLI_CODSUC,DLI_CODIGO,RII_FCHDES       
 ORDER BY DLI_CODSUC,DLI_CODIGO,RII_FCHHAS
;

-- 348
 CREATE OR REPLACE VIEW  VIEW_DPLIBINVFIN_MES AS 
SELECT                       DLI_CODSUC           AS RVF_CODSUC,                      DLI_CODIGO           AS RVF_CODIGO,                      DLI_SALDO*DLI_COSPRO AS RVF_VALINV,                  DLI_SALDO            AS RVF_EXIFIN,          RII_FCHDES           AS RVF_FCHDES,                RII_FCHHAS           AS RVF_FCHHAS                        FROM 
                      VIEW_DPLIBINVDET_MES                        
 INNER JOIN DPLIBINVDET ON RII_CODSUC=DLI_CODSUC AND RII_CODIGO=DLI_CODIGO AND RII_HASTA=DLI_FECHA                                
 GROUP BY DLI_CODSUC,DLI_CODIGO,RII_FCHDES             
 ORDER BY DLI_CODSUC,DLI_CODIGO,RII_FCHHAS
;

-- 349
 CREATE OR REPLACE VIEW  VIEW_DPLIBINVDET_TRI AS 
SELECT                           DLI_CODSUC      AS RII_CODSUC,                          DLI_CODIGO      AS RII_CODIGO,                         
 SUM(DLI_COSVTA) AS RII_COSVTA,                 
 SUM(DLI_CANVTA) AS RII_CANVTA,                                  MIN(DLI_FECHA)  AS RII_DESDE,                          MAX(DLI_FECHA)  AS RII_HASTA,      FCH_DESDE       AS RII_FCHDES,        FCH_HASTA       AS RII_FCHHAS                              FROM 
                           VIEW_DPDIARIO_TRIMES                          
 INNER JOIN DPLIBINVDET ON DLI_FECHA>=FCH_DESDE AND DLI_FECHA<=FCH_HASTA                        WHERE DLI_COSVTA>0                         
 GROUP BY DLI_CODSUC,DLI_CODIGO,RII_FCHDES,RII_FCHHAS
;

-- 350
 CREATE OR REPLACE VIEW  VIEW_DPLIBINVINI_TRI AS 
SELECT                         DLI_CODSUC AS RVI_CODSUC,                        DLI_CODIGO AS RVI_CODIGO,                        DLI_CANANT*DLI_COSANT AS RVI_VALINV,                DLI_CANANT            AS RVI_EXIINI,      RII_FCHDES            AS RVI_FCHDES,      RII_FCHHAS            AS RVI_FCHHAS                         FROM 
                        VIEW_DPLIBINVDET_TRI                        
 INNER JOIN DPLIBINVDET ON RII_CODSUC=DLI_CODSUC AND RII_CODIGO=DLI_CODIGO AND RII_DESDE=DLI_FECHA                                  
 GROUP BY DLI_CODSUC,DLI_CODIGO,RII_FCHDES     
 ORDER BY DLI_CODSUC,DLI_CODIGO,RII_FCHHAS
;

-- 351
 CREATE OR REPLACE VIEW  VIEW_DPLIBINVFIN_TRI AS 
SELECT                 DLI_CODSUC           AS RVF_CODSUC,                DLI_CODIGO           AS RVF_CODIGO,                DLI_SALDO*DLI_COSPRO AS RVF_VALINV,            DLI_SALDO            AS RVF_EXIFIN,    RII_FCHDES           AS RVF_FCHDES,      RII_FCHHAS           AS RVF_FCHHAS                   FROM 
                VIEW_DPLIBINVDET_TRI                  
 INNER JOIN DPLIBINVDET ON RII_CODSUC=DLI_CODSUC AND RII_CODIGO=DLI_CODIGO AND RII_HASTA=DLI_FECHA                          
 GROUP BY DLI_CODSUC,DLI_CODIGO,RII_FCHDES,RII_FCHHAS   
 ORDER BY DLI_CODSUC,DLI_CODIGO    ,RII_FCHDES,RII_FCHHAS
;

-- 352
 CREATE OR REPLACE VIEW  VIEW_DPLIBINVDET_SEM AS 
SELECT                       DLI_CODSUC      AS RII_CODSUC,                      DLI_CODIGO      AS RII_CODIGO,                     
 SUM(DLI_COSVTA) AS RII_COSVTA,             
 SUM(DLI_CANVTA) AS RII_CANVTA,                              MIN(DLI_FECHA)  AS RII_DESDE,                      MAX(DLI_FECHA)  AS RII_HASTA,  FCH_DESDE       AS RII_FCHDES,    FCH_HASTA       AS RII_FCHHAS                         FROM 
                       VIEW_DPDIARIO_SEMEST                      
 INNER JOIN DPLIBINVDET ON DLI_FECHA>=FCH_DESDE AND DLI_FECHA<=FCH_HASTA                    WHERE DLI_COSVTA>0                     
 GROUP BY DLI_CODSUC,DLI_CODIGO
;

-- 353
 CREATE OR REPLACE VIEW  VIEW_DPLIBINVINI_SEM AS 
SELECT                       DLI_CODSUC AS RVI_CODSUC,                      DLI_CODIGO AS RVI_CODIGO,                      DLI_CANANT*DLI_COSANT AS RVI_VALINV,              DLI_CANANT            AS RVI_EXIINI,    RII_FCHDES            AS RVI_FCHDES,        RII_FCHHAS            AS RVI_FCHHAS      FROM 
                      VIEW_DPLIBINVDET_SEM                      
 INNER JOIN DPLIBINVDET ON RII_CODSUC=DLI_CODSUC AND RII_CODIGO=DLI_CODIGO AND RII_DESDE=DLI_FECHA                                
 GROUP BY DLI_CODSUC,DLI_CODIGO,RII_FCHDES       
 ORDER BY DLI_CODSUC,DLI_CODIGO,RII_FCHHAS
;

-- 354
 CREATE OR REPLACE VIEW  VIEW_DPLIBINVFIN_SEM AS 
SELECT               DLI_CODSUC           AS RVF_CODSUC,              DLI_CODIGO           AS RVF_CODIGO,              DLI_SALDO*DLI_COSPRO AS RVF_VALINV,          DLI_SALDO            AS RVF_EXIFIN,  RII_FCHDES           AS RVF_FCHDES,      RII_FCHHAS           AS RVF_FCHHAS  FROM 
              VIEW_DPLIBINVDET_SEM                
 INNER JOIN DPLIBINVDET ON RII_CODSUC=DLI_CODSUC AND RII_CODIGO=DLI_CODIGO AND RII_HASTA=DLI_FECHA                        
 GROUP BY DLI_CODSUC,DLI_CODIGO,RII_FCHDES,RII_FCHHAS   
 ORDER BY DLI_CODSUC,DLI_CODIGO,RII_FCHDES,RII_FCHHAS
;

-- 355
 CREATE OR REPLACE VIEW  VIEW_DPLIBINVDET_ANO AS 
SELECT                       DLI_CODSUC      AS RII_CODSUC,                      DLI_CODIGO      AS RII_CODIGO,                     
 SUM(DLI_COSVTA) AS RII_COSVTA,             
 SUM(DLI_CANVTA) AS RII_CANVTA,                              MIN(DLI_FECHA)  AS RII_DESDE,                      MAX(DLI_FECHA)  AS RII_HASTA,  FCH_DESDE       AS RII_FCHDES,  FCH_HASTA       AS RII_FCHHAS                      FROM 
                       VIEW_DPDIARIO_ANO                      
 INNER JOIN DPLIBINVDET ON DLI_FECHA>=FCH_DESDE AND DLI_FECHA<=FCH_HASTA                    WHERE DLI_COSVTA>0                     
 GROUP BY DLI_CODSUC,DLI_CODIGO
;

-- 356
 CREATE OR REPLACE VIEW  VIEW_DPLIBINVINI_ANO AS 
SELECT                       DLI_CODSUC AS RVI_CODSUC,                      DLI_CODIGO AS RVI_CODIGO,                      DLI_CANANT*DLI_COSANT AS RVI_VALINV,              DLI_CANANT            AS RVI_EXIINI,    RII_FCHDES            AS RVI_FCHDES,        RII_FCHHAS            AS RVI_FCHHAS                          FROM 
                      VIEW_DPLIBINVDET_ANO                      
 INNER JOIN DPLIBINVDET ON RII_CODSUC=DLI_CODSUC AND RII_CODIGO=DLI_CODIGO AND RII_DESDE=DLI_FECHA                                
 GROUP BY DLI_CODSUC,DLI_CODIGO,RII_FCHDES       
 ORDER BY DLI_CODSUC,DLI_CODIGO,RII_FCHHAS
;

-- 357
 CREATE OR REPLACE VIEW  VIEW_DPLIBINVFIN_ANO AS 
SELECT               DLI_CODSUC           AS RVF_CODSUC,              DLI_CODIGO           AS RVF_CODIGO,              DLI_SALDO*DLI_COSPRO AS RVF_VALINV,          DLI_SALDO            AS RVF_EXIFIN,  RII_FCHDES           AS RVI_FCHDES,      RII_FCHHAS           AS RVI_FCHHAS                FROM 
              VIEW_DPLIBINVDET_ANO                
 INNER JOIN DPLIBINVDET ON RII_CODSUC=DLI_CODSUC AND RII_CODIGO=DLI_CODIGO AND RII_HASTA=DLI_FECHA                        
 GROUP BY DLI_CODSUC,DLI_CODIGO,RII_FCHDES,RII_FCHHAS   
 ORDER BY DLI_CODSUC,DLI_CODIGO,RII_FCHDES,RII_FCHHAS
;

-- 358
 CREATE OR REPLACE VIEW  VIEW_HISMONMAXVALOR AS 
SELECT                 HMN_CODIGO AS MAX_CODIGO,                HMN_VALOR  AS MAX_VALOR,                MAX_FECHA,MAX_HORA              FROM 
 VIEW_NMHISMONMAXFCH                 
 INNER JOIN DPHISMON ON MAX_CODIGO=HMN_CODIGO AND MAX_FECHA=HMN_FECHA
;

-- 359
 CREATE OR REPLACE VIEW  VIEW_DOCCLICXCPORCEN AS 
SELECT             CXD_CODSUC AS CCP_CODSUC,             CXD_TIPDOC AS CCP_TIPDOC,             CXD_NUMERO AS CCP_NUMERO,             (CXD_MTOPAG/CXD_MTODOC)*100 AS CCP_PORCEN,  CXD_MTOPAG AS CCP_MTOPAG             FROM 
             VIEW_DOCCLIDOCYPAG                     
 ORDER BY CXD_CODSUC,CXD_TIPDOC,CXD_NUMERO
;

-- 360
 CREATE OR REPLACE VIEW  VIEW_DPACTIVOSCTA AS 
SELECT   ATV_CTAMOD, ATV_CODIGO, ATV_DESCRI, VIEW_ACTCTA_ACT.ACT_CTAACT AS ATV_CTAACT, VIEW_ACTCTA_ACU.ACT_CTAACU AS ATV_CTAACU, VIEW_ACTCTA_DEP.ACT_CTADEP AS ATV_CTADEP, VIEW_ACTCTA_REV.ACT_CTAREV AS ATV_CTAREV  FROM 
 VIEW_DPACTIVOS_CTA  LEFT JOIN VIEW_ACTCTA_ACT ON ATV_CODIGO=VIEW_ACTCTA_ACT.ACT_CODACT LEFT JOIN VIEW_ACTCTA_ACU ON ATV_CODIGO=VIEW_ACTCTA_ACU.ACT_CODACT LEFT JOIN VIEW_ACTCTA_DEP ON ATV_CODIGO=VIEW_ACTCTA_DEP.ACT_CODACT LEFT JOIN VIEW_ACTCTA_REV ON ATV_CODIGO=VIEW_ACTCTA_REV.ACT_CODACT
 GROUP BY ATV_CTAMOD,ATV_CODIGO
 ORDER BY ATV_CTAMOD,ATV_CODIGO;

-- 361
 CREATE OR REPLACE VIEW  VIEW_DPCTAAXI_MENSUAL AS 
SELECT   CTA_CODSUC AS AME_CODSUC, CTA_CODMOD AS AME_CODMOD, CTA_CODIGO AS AME_CUENTA, EJE_DESDE  AS AME_EJEINI, EJE_HASTA  AS AME_EJEFIN, FCH_ANO    AS AME_ANO   , FCH_MES    AS AME_MES   , FCH_FCHANT AS AME_FCHANT, FCH_DESDE  AS AME_FCHINI, FCH_HASTA  AS AME_FCHFIN, FCH_MAXDIV AS AME_FCHDIV, IPC_TASA   AS AME_EJIPC , IPC_INPC   AS AME_EJINPC, HMN_VALOR  AS AME_VALCAM, (SELECT HMN_VALOR      FROM 
 view_dphismon_mes_valor WHERE YEAR(FCH_FCHANT)=HMN_ANO AND MONTH(FCH_FCHANT)=HMN_MES AND HMN_CODIGO="DBC" LIMIT 1  ) AS AME_ANTDIV,  (SELECT
 SUM(MOC_MONTO) FROM 
 dpasientos WHERE MOC_CODSUC=CTA_CODSUC AND CTA_CODMOD=MOC_CTAMOD AND MOC_CUENTA=CTA_CODIGO AND MOC_FECHA< FCH_DESDE) AS AME_MTOANT,  (SELECT
 SUM(MOC_MONTO) FROM 
 dpasientos WHERE MOC_CODSUC=CTA_CODSUC AND CTA_CODMOD=MOC_CTAMOD AND MOC_CUENTA=CTA_CODIGO AND MOC_FECHA<=FCH_HASTA) AS AME_MTOACT   FROM 
 VIEW_DPCTAAXI 
 INNER JOIN dpejercicios      ON CTA_CODSUC=EJE_CODSUC  LEFT  JOIN ADMCONFIG51.dpipc ON YEAR(EJE_DESDE)=IPC_ANO AND MONTH(EJE_DESDE)=IPC_MES 
 INNER JOIN view_dpdiario_mes ON FCH_DESDE>=EJE_DESDE AND FCH_HASTA<=EJE_HASTA  LEFT  JOIN dphismon          ON FCH_CODMON=HMN_CODIGO AND HMN_FECHA=FCH_MAXDIV 
 GROUP BY CTA_CODSUC,CTA_CODMOD,CTA_CODIGO,FCH_ANO,FCH_MES 
 ORDER BY CTA_CODSUC,CTA_CODMOD,CTA_CODIGO,FCH_ANO,FCH_MES;

-- 362
 CREATE OR REPLACE VIEW  VIEW_DPDOCPROANOMES AS 
SELECT  DOC_CODSUC AS RMC_CODSUC, DOC_CENCOS AS RMC_CENCOS, DOC_TIPDOC AS RMC_TIPDOC, FCH_ANO AS RCM_ANO,   FCH_MES AS RCM_MES,  
 SUM(DOC_BASNET*DOC_CXP) AS RMC_BASNET,
 SUM(DOC_MTOIVA*DOC_CXP) AS RMC_MTOIVA,
 SUM(DOC_NETO  *DOC_CXP) AS RMC_NETO  ,
 SUM(DOC_MTODIV*DOC_CXP) AS RMC_MTODIV  FROM 
 VIEW_DPDIARIO_MES 
 INNER JOIN DPDOCPRO ON YEAR(DOC_FCHDEC)=FCH_ANO AND MONTH(DOC_FCHDEC)=FCH_MES AND DOC_TIPTRA="D" AND DOC_ACT=1  
 GROUP BY DOC_CODSUC,DOC_CENCOS,DOC_TIPDOC,FCH_ANO,FCH_MES;

-- 363
 CREATE OR REPLACE VIEW  VIEW_ASIENTOS_BT AS 
SELECT                       BTF_CODSUC AS BTR_CODSUC,                      BTF_NUMEJE AS BTR_NUMEJE,            BTF_NUMCBT AS BTR_NUMCBT,                      BTI_CUENTA AS BTR_CTAORG,       BTF_CUENTA AS BTR_CTADES,          BTF_DESCRI AS BTR_DESCRI                      FROM 
 VIEW_ASIENTOS_TI                         
 INNER JOIN VIEW_ASIENTOS_TF ON  BTI_NUMEJE=BTF_NUMEJE AND BTI_CODSUC=BTF_CODSUC AND BTI_NUMCBT=BTF_NUMCBT AND  BTI_ITEM  =BTF_ITEM                      
 ORDER BY BTF_CODSUC,BTF_NUMCBT
;

-- 364
 CREATE OR REPLACE VIEW  VIEW_DPPROVXINVCANT AS 
SELECT   UCP_CODPRO     AS RPP_CODPRO, MAX(UCP_FECHA) AS RPP_FECHA , COUNT(*)   AS RPP_CANTID  FROM 
 VIEW_DPPROVXINV 
 GROUP BY UCP_CODPRO;

-- 365
 CREATE OR REPLACE VIEW  VIEW_EPED_PRODUCTOS AS 
SELECT INV_CODIGO AS codigo,"SN" AS referencia, GRU_CODIGO AS grupo, "" as subgrupo,  INV_DESCRI AS nombre,  INV_IVA    AS iva,  PRE_PRECIO AS precio1, IF(INV_IVA="GN",PRE_PRECIO*1.16,PRE_PRECIO) AS preciofin1, IME_UNDMED AS unidad,  IME_CANTID AS empaque, MAR_DESCRI AS Y, DEP_DESCRI AS Z, EXL_CANTID AS existencia,  INV_FCHACT AS date, 0 AS poriva,  INV_FCHACT  FROM 
 DPINV 
 INNER JOIN DPGRU          ON INV_GRUPO=GRU_CODIGO AND GRU_EMANAG=1  LEFT  JOIN DPMARCAS       ON INV_CODMAR=MAR_CODIGO  LEFT  JOIN DPDPTO         ON INV_CODDEP=DEP_CODIGO  LEFT  JOIN DPINVMED       ON INV_CODIGO=IME_CODIGO AND IME_VENTA="S" 
 INNER JOIN DPPRECIOS      ON INV_CODIGO=PRE_CODIGO AND IME_UNDMED=PRE_UNDMED AND PRE_LISTA="A"  LEFT  JOIN VIEW_INVEXILOG ON INV_CODIGO=EXL_CODIGO  WHERE LEFT(INV_UTILIZ,1)="V" 
 ORDER BY CODIGO
;

-- 366
 CREATE OR REPLACE VIEW  VIEW_CLICATRGONOW AS 
SELECT      CAT_CODSUC AS CRN_CODSUC,    CAT_TIPDOC AS CRN_TIPDOC,    CAT_CODIGO AS CRN_CODIGO,    DATE_SUB(NOW(), INTERVAL 60 DAY) AS CRN_DESDE,    NOW() AS CRN_HASTA    FROM 
 VIEW_CLICATMAXFCH   
 GROUP BY CAT_CODSUC,CAT_TIPDOC,CAT_CODIGO
;

-- 367
 CREATE OR REPLACE VIEW  VIEW_EPED_CLIENTES AS 
SELECT  CLI_CODVEN AS vendedor,                                            CLI_CODIGO as codigo,                                                                                              CLI_NOMBRE as nombre,                                                                                              CLI_RIF as nrorif,                                                                                              concat(CLI_DIR1, " ",CLI_DIR2)   as direccion,                                                                                              DPCLIENTESPER.PDC_PERSON         as perscont,                                                                                     PDC_CARGO                        as cargo,                                                                                                       concat(CLI_AREA, " ",CLI_TEL1)   as telefonos,                                                                                              concat(CLI_AREA, " ",CLI_TEL1)   as telefono_movil,                                                                                              concat(CLI_PAIS, ",",CLI_ESTADO) as zona,                                                                                               cxc_neto                         as saldo,                                                                                               CLI_EMAIL                        as email,                                                                                              PDC_EMAIL                        as campo5,                                          ""                               as campo3,                                                                                              VEN_RIF    as rifvendedor,                                                                          CLICAT_A( '000000'  ,CLI_CODIGO) AS categoria,                                                          CLI_FCHUPD       as updated ,                                                      0 AS VIS_LUN,                                                      0 AS VIS_MAR,                                                      0 AS VIS_MIE,                                                      0 AS VIS_JUE,                                                      0 AS VIS_VIE,                                                      0 AS VIS_SAB,                                                      0 AS VIS_DOM,                                                      0 AS COB_LUN,                                                      0 AS COB_MAR,                                                      0 AS COB_MIE,                                                      0 AS COB_JUE,                                                      0 AS COB_VIE,                                                      0 AS COB_SAB,                                                      0 AS COB_DOM,                                                      REN_LUN,                                                      REN_MAR,                                                      REN_MIE,                                                      REN_JUE,                                                      REN_VIE,                                                      REN_SAB,                                                      REN_DOM                                         FROM  DPCLIENTES                                                                                              LEFT JOIN VIEW_CXCXCLI  ON CLI_CODIGO=CXC_CODIGO                                                                                            LEFT JOIN DPCLIENTESPER ON CLI_CODIGO=PDC_CODIGO                                                                                  LEFT JOIN DPCARGOS      ON PDC_CARGO =CAR_CODIGO AND CAR_GERCOM=1                                                                              LEFT JOIN DPVENDEDOR    ON CLI_CODVEN=VEN_CODIGO                                                                             LEFT JOIN DPRUTAS       ON CLI_CODRUT=REN_CODIGO                                                    WHERE VEN_EMANAG=1                                                                              GROUP BY CLI_CODIGO;

-- 368
 CREATE OR REPLACE VIEW  VIEW_DPCBTNUMASI AS 
SELECT  CNP_CODSUC      AS CNA_CODSUC, CNP_ACTUAL      AS CNA_ACTUAL, CNP_NUMCBT      AS CNA_NUMCBT, CNP_FECHA       AS CNA_FECHA ,
 SUM(CNP_DEBE )  AS CNA_DEBE  ,
 SUM(CNP_HABER)  AS CNA_HABER ,
 SUM(CNP_MONTO)  AS CNA_MONTO ,
 SUM(CNP_CANTID) AS CNA_CANASI, COUNT(*) AS CNA_CANPAR  FROM 
 VIEW_DPCBTNUMPAR 
 GROUP BY CNP_CODSUC,CNP_ACTUAL,CNP_NUMCBT,CNP_FECHA;

-- 369
 CREATE OR REPLACE VIEW  VIEW_CAJACXC_CXP AS 
SELECT                             CCC_CODSUC AS CAJ_CODSUC,                            CCC_CODCAJ AS CAJ_CODCAJ,                            CCC_RIF    AS CAJ_RIF   ,                            CCC_TIPO   AS CAJ_TIPO  ,                       CCC_NUMERO AS CAJ_NUMERO,                     CCC_MONTO  AS CAJ_MTOREC,                    IF(CCP_MONTO IS NULL,0,CCP_MONTO)  AS CAJ_MTOPAG,                    CCC_MONTO+IF(CCP_MONTO IS NULL,0,CCP_MONTO) AS CAJ_MONTO                         FROM 
 VIEW_CAJACXC                            LEFT JOIN VIEW_CAJACXP ON CCC_CODSUC=CCP_CODSUC AND                                                   CCC_CODCAJ=CCP_CODCAJ AND                                                  CCC_RIF   =CCP_RIF    AND                                                  CCC_TIPO  =CCP_TIPO   AND                                                  CCC_NUMERO=CCP_NUMERO                     HAVING CAJ_MONTO>0                  
 ORDER BY CCC_CODSUC,CCC_CODCAJ,CCC_RIF,CCC_TIPO,CCC_NUMERO
;

-- 370
 CREATE OR REPLACE VIEW  VIEW_CLICXC AS 
SELECT CXD_CODIGO AS CXC_CODIGO,SUM(CXD_NETO) AS CXC_SALDO,COUNT(*) AS CXC_CANDOC   FROM 
 VIEW_DOCCLICXC 
 GROUP BY CXD_CODIGO 
 ORDER BY CXD_CODIGO;

-- 371
 CREATE OR REPLACE VIEW  VIEW_DPDPTO_INV_CTA AS 
SELECT GRU_CTAMOD,GRU_CODIGO,GRU_DESCRI  ,VIEW_DPDPTOINVCTA_ATC.GRU_CTAATC,VIEW_DPDPTOINVCTA_COS.GRU_CTACOS,VIEW_DPDPTOINVCTA_VTA.GRU_CTAVTA,VIEW_DPDPTOINVCTA_DVV.GRU_CTADVV,VIEW_DPDPTOINVCTA_COM.GRU_CTACOM,VIEW_DPDPTOINVCTA_DVC.GRU_CTADVC,VIEW_DPDPTOINVCTA_INI.GRU_CTAINI,VIEW_DPDPTOINVCTA_FIN.GRU_CTAFIN FROM 
 VIEW_DPDPTOINV_CTA  LEFT JOIN VIEW_DPDPTOINVCTA_ATC ON GRU_CODIGO=ATC_CODGRU LEFT JOIN VIEW_DPDPTOINVCTA_COS ON GRU_CODIGO=COS_CODGRU LEFT JOIN VIEW_DPDPTOINVCTA_VTA ON GRU_CODIGO=VTA_CODGRU LEFT JOIN VIEW_DPDPTOINVCTA_DVV ON GRU_CODIGO=DVV_CODGRU LEFT JOIN VIEW_DPDPTOINVCTA_COM ON GRU_CODIGO=COM_CODGRU LEFT JOIN VIEW_DPDPTOINVCTA_DVC ON GRU_CODIGO=DVC_CODGRU LEFT JOIN VIEW_DPDPTOINVCTA_INI ON GRU_CODIGO=INI_CODGRU LEFT JOIN VIEW_DPDPTOINVCTA_FIN ON GRU_CODIGO=FIN_CODGRU
 ORDER BY GRU_CTAMOD,GRU_CODIGO
;

-- 372
 CREATE OR REPLACE VIEW  VIEW_DPGRUCTA AS 
SELECT GRU_CTAMOD,GRU_CODIGO,GRU_DESCRI  ,VIEW_GRUCTA_ACT.GRU_CTAACT,VIEW_GRUCTA_COS.GRU_CTACOS,VIEW_GRUCTA_VTA.GRU_CTAVTA,VIEW_GRUCTA_VTP.GRU_CTAVTP,VIEW_GRUCTA_VTE.GRU_CTAVTE,VIEW_GRUCTA_VTH.GRU_CTAVTH,VIEW_GRUCTA_DVV.GRU_CTADVV,VIEW_GRUCTA_COM.GRU_CTACOM,VIEW_GRUCTA_DVC.GRU_CTADVC,VIEW_GRUCTA_INI.GRU_CTAINI,VIEW_GRUCTA_FIN.GRU_CTAFIN FROM 
 VIEW_DPGRU_CTA  LEFT JOIN VIEW_GRUCTA_ACT ON GRU_CODIGO=ACT_CODGRU LEFT JOIN VIEW_GRUCTA_COS ON GRU_CODIGO=COS_CODGRU LEFT JOIN VIEW_GRUCTA_VTA ON GRU_CODIGO=VTA_CODGRU LEFT JOIN VIEW_GRUCTA_VTP ON GRU_CODIGO=VTP_CODGRU LEFT JOIN VIEW_GRUCTA_VTE ON GRU_CODIGO=VTE_CODGRU LEFT JOIN VIEW_GRUCTA_VTH ON GRU_CODIGO=VTH_CODGRU LEFT JOIN VIEW_GRUCTA_DVV ON GRU_CODIGO=DVV_CODGRU LEFT JOIN VIEW_GRUCTA_COM ON GRU_CODIGO=COM_CODGRU LEFT JOIN VIEW_GRUCTA_DVC ON GRU_CODIGO=DVC_CODGRU LEFT JOIN VIEW_GRUCTA_INI ON GRU_CODIGO=INI_CODGRU LEFT JOIN VIEW_GRUCTA_FIN ON GRU_CODIGO=FIN_CODGRU
 ORDER BY GRU_CTAMOD,GRU_CODIGO
;

-- 373
 CREATE OR REPLACE VIEW  VIEW_DPCXCCXPPNF AS 
SELECT   DIA_FECHA  AS DIA_FECHA, CXP_TIPDOC AS DIA_TIPCXP, CXC_TIPDOC AS DIA_TIPCXC, PXD_TIPDOC AS DIA_TIPPXD, PXD_DESCRI AS DIA_DESPXD, IF(PXD_TIPDOC IS NULL,0,PXD_MTODIV) AS MTO_PXDDIV, IF(CXC_MTODIV IS NULL,0,CXC_MTODIV) AS MTO_CXCDIV, IF(CXP_MTODIV IS NULL,0,CXP_MTODIV) AS MTO_CXPDIV  FROM 
 dpdiario  LEFT JOIN VIEW_DPDIARIOCXP        ON DIA_FECHA=CXP_FECHA LEFT JOIN VIEW_DPDIARIOCXC        ON DIA_FECHA=CXC_FECHA LEFT JOIN VIEW_DPDOCPROPROGDIARIO ON DIA_FECHA=PXD_FECHA HAVING CXP_TIPDOC IS NOT NULL AND CXC_TIPDOC IS NOT NULL AND CXC_TIPDOC IS NOT NULL;

-- 374
 CREATE OR REPLACE VIEW  VIEW_DPDOCPROPROGDIA_PRF AS 
SELECT  PXD_CODSUC   AS PRF_CODSUC, "PRF"        AS PRF_TIPDOC, "PARAFISCAL" AS PRF_DESCRI, PXD_FECHA    AS PRF_FECHA,  "PARAFISCAL" AS PRF_REFERE,
 SUM(IF( PXD_MTODIV IS NULL,0,PXD_MTODIV)) AS PRF_MTODIV,
 SUM(IF( PXD_MTOCXP IS NULL,0,PXD_MTOCXP)) AS PRF_MTOCXP,
 SUM(IF( PXD_MTOCAL IS NULL,0,PXD_MTOCAL)) AS PRF_MTOCAL,
 SUM(PXD_MTOPAG) AS PRF_MTOPAG,
 SUM(PXD_MTONET) AS PRF_MTONET,
 SUM(IF( PXD_CALDIV IS NULL,0,PXD_CALDIV)) AS PRF_CALDIV  FROM 
 view_dpdocproprogdiario 
 INNER JOIN dptipdocpro ON PXD_TIPDOC=TDC_TIPO AND TDC_TRIBUT=1 
 INNER JOIN dpproveedor ON PXD_CODPRO=PRO_CODIGO AND PRO_RIF<>"G200003030" 
 GROUP BY PXD_CODSUC,PXD_FECHA;

-- 375
 CREATE OR REPLACE VIEW  VIEW_DPDOCPROPROGDIA_SENIAT AS 
SELECT  PXD_CODSUC   AS SEN_CODSUC, "SEN"        AS SEN_TIPDOC, "SENIAT"     AS SEN_DESCRI, PXD_FECHA    AS SEN_FECHA,  "SENIAT"     AS SEN_REFERE,
 SUM(IF( PXD_MTODIV IS NULL,0,PXD_MTODIV)) AS SEN_MTODIV,
 SUM(IF( PXD_MTOCXP IS NULL,0,PXD_MTOCXP)) AS SEN_MTOCXP,
 SUM(IF( PXD_MTOCAL IS NULL,0,PXD_MTOCAL)) AS SEN_MTOCAL,
 SUM(PXD_MTOPAG) AS SEN_MTOPAG,
 SUM(PXD_MTONET) AS SEN_MTONET,
 SUM(IF( PXD_CALDIV IS NULL,0,PXD_CALDIV)) AS SEN_CALDIV  FROM 
 view_dpdocproprogdiario 
 INNER JOIN dptipdocpro ON PXD_TIPDOC=TDC_TIPO AND TDC_TRIBUT=1 
 INNER JOIN dpproveedor ON PXD_CODPRO=PRO_CODIGO AND PRO_RIF="G200003030" 
 GROUP BY PXD_CODSUC,PXD_FECHA;

-- 376
 CREATE OR REPLACE VIEW  VIEW_LIBCOMDOCSINLIB AS 
SELECT    DOC_CODSUC          AS NLC_CODSUC,  YEAR(DOC_FCHDEC)    AS NLC_YEAR,                            MONTH(DOC_FCHDEC)   AS NLC_MES,                           
 SUM(DOC_MTOEXE)     AS NLC_MTOEXE,                        
 SUM(IF(DOC_CREFIS=0,DOC_MTOIVA,0)) AS NLC_SINCRE,                          
 SUM(DOC_BASNET)     AS NLC_BASNET,                           
 SUM(IF(DOC_CREFIS=1,DOC_MTOIVA,0)) AS NLC_MTOIVA,                          
 SUM(RTI_MONTO)      AS NLC_MTORTI,                           
 SUM(DOC_NETO)       AS NLC_NETO,                            COUNT(*)            AS NLC_CUANTOS                            FROM 
 DPDOCPRO     
 INNER JOIN DPTIPDOCPRO    ON DOC_TIPDOC=TDC_TIPO AND TDC_LIBCOM=1                            LEFT  JOIN VIEW_DOCPRORTI ON DOC_CODSUC=RTI_CODSUC AND                                                         DOC_TIPDOC=RTI_TIPDOC AND                                                         DOC_CODIGO=RTI_CODIGO AND                                                         DOC_NUMERO=RTI_NUMDOC                            WHERE (DOC_LIBCOM IS NULL OR DOC_LIBCOM="") AND DOC_ACT=1         
 GROUP BY DOC_CODSUC,YEAR(DOC_FCHDEC),MONTH(DOC_FCHDEC)         
 ORDER BY DOC_CODSUC,YEAR(DOC_FCHDEC),MONTH(DOC_FCHDEC)
;

-- 377
 CREATE OR REPLACE VIEW  VIEW_DPASIENTOSDOCCOM AS 
SELECT        MOC_CODSUC AS DCC_CODSUC,        MOC_TIPO   AS DCC_TIPDOC,        MOC_CODAUX AS DCC_CODIGO,        MOC_DOCUME AS DCC_NUMERO,        MOC_CTAMOD AS DCC_CTAMOD,        MOC_NUMPAR AS DCC_NUMPAR,        MOC_CUENTA AS DCC_CUENTA,        MOC_MONTO  AS DCC_MONTO,    MOC_FECHA  AS DCC_FECHA        FROM 
 DPASIENTOS       
 INNER JOIN VIEW_DPCTARESULTADO ON MOC_CTAMOD=CTR_CODMOD AND MOC_CUENTA=CTR_CUENTA        WHERE MOC_ORIGEN="COM" AND  MOC_TIPTRA="D"     
 ORDER BY MOC_CODSUC,MOC_TIPO,MOC_CODAUX,MOC_DOCUME
;

-- 378
 CREATE OR REPLACE VIEW  VIEW_DPCXPSINPLARESDIA AS 
SELECT  CXP_CODSUC,  CXP_TIPDOC,  CXP_FECHA,  
 SUM(CXP_NETO_SP)   AS CXP_NETO_SP,  
 SUM(CXP_PAGADO_SP) AS CXP_PAGADO_SP,
 SUM(CXP_SALDO_SP)  AS CXP_SALDO_SP, 
 SUM(CXP_NETO)      AS CXP_NETO,     
 SUM(CXP_PAGADO)    AS CXP_PAGADO,   
 SUM(CXP_SALDO)     AS CXP_SALDO      FROM 
   view_dpcxpsinpla    
 GROUP BY CXP_FECHA;

-- 379
 CREATE OR REPLACE VIEW  VIEW_NMFECHAMAX AS 
SELECT  FCH_CODSUC     AS NOM_CODSUC, FCH_TIPNOM     AS NOM_TIPNOM, FCH_OTRNOM     AS NOM_OTRNOM, MAX(FCH_HASTA) AS NOM_HASTA   FROM 
 nmfechas 
 INNER JOIN view_nmfchcantrec ON  FCH_CODSUC=CRF_CODSUC AND FCH_NUMERO=CRF_NUMERO 
 GROUP BY FCH_CODSUC,FCH_TIPNOM,FCH_OTRNOM 
 ORDER BY FCH_CODSUC,FCH_TIPNOM,FCH_OTRNOM;

-- 380
 CREATE OR REPLACE VIEW  VIEW_DPLIBINVIRI_BIM AS 
SELECT                 RII_CODSUC AS IRI_CODSUC,                RII_CODIGO AS IRI_CODIGO,                RII_COSVTA AS IRI_COSVTA,                RVI_VALINV AS IRI_VALINI,                RVF_VALINV AS IRI_VALFIN,                (RVI_VALINV+RVF_VALINV)/IF(RVI_VALINV*RVF_VALINV>0,2,1) AS IRI_VALPRO,                RII_COSVTA/((RVI_VALINV+RVF_VALINV)/IF(RVI_VALINV*RVF_VALINV>0,2,1)) AS IRI_INDROT,                RVF_EXIFIN AS IRI_EXIFIN,                RVF_EXIFIN/(RII_COSVTA/((RVI_VALINV+RVF_VALINV)/IF(RVI_VALINV*RVF_VALINV>0,2,1))) AS IRI_DIAS,                RII_FCHDES AS IRI_FCHDES,                RII_FCHHAS AS IRI_FCHHAS,                DATEDIFF(RII_HASTA, RII_DESDE) AS IRI_NDIAS                FROM 
                 VIEW_DPLIBINVDET_BIM                 
 INNER JOIN VIEW_DPLIBINVINI_BIM ON RII_CODSUC=RVI_CODSUC AND RII_CODIGO=RVI_CODIGO               
 INNER JOIN VIEW_DPLIBINVFIN_BIM ON RII_CODSUC=RVF_CODSUC AND RII_CODIGO=RVF_CODIGO
;

-- 381
 CREATE OR REPLACE VIEW  VIEW_DPLIBINVIRI_CUA AS 
SELECT                   RII_CODSUC AS IRI_CODSUC,                  RII_CODIGO AS IRI_CODIGO,                  RII_COSVTA AS IRI_COSVTA,                  RVI_VALINV AS IRI_VALINI,                  RVF_VALINV AS IRI_VALFIN,                  (RVI_VALINV+RVF_VALINV)/IF(RVI_VALINV*RVF_VALINV>0,2,1) AS IRI_VALPRO,                  RII_COSVTA/((RVI_VALINV+RVF_VALINV)/IF(RVI_VALINV*RVF_VALINV>0,2,1)) AS IRI_INDROT,                  RVF_EXIFIN AS IRI_EXIFIN,                  RVF_EXIFIN/(RII_COSVTA/((RVI_VALINV+RVF_VALINV)/IF(RVI_VALINV*RVF_VALINV>0,2,1))) AS IRI_DIAS,                  RII_FCHDES AS IRI_FCHDES,                  RII_FCHHAS AS IRI_FCHHAS,                  DATEDIFF(RII_HASTA, RII_DESDE) AS IRI_NDIAS                  FROM 
                   VIEW_DPLIBINVDET_CUA                   
 INNER JOIN VIEW_DPLIBINVINI_CUA ON RII_CODSUC=RVI_CODSUC AND RII_CODIGO=RVI_CODIGO                 
 INNER JOIN VIEW_DPLIBINVFIN_CUA ON RII_CODSUC=RVF_CODSUC AND RII_CODIGO=RVF_CODIGO
;

-- 382
 CREATE OR REPLACE VIEW  VIEW_DPLIBINVIRI_MES AS 
SELECT               RII_CODSUC AS IRI_CODSUC,              RII_CODIGO AS IRI_CODIGO,              RII_COSVTA AS IRI_COSVTA,              RVI_VALINV AS IRI_VALINI,              RVF_VALINV AS IRI_VALFIN,              (RVI_VALINV+RVF_VALINV)/IF(RVI_VALINV*RVF_VALINV>0,2,1) AS IRI_VALPRO,              RII_COSVTA/((RVI_VALINV+RVF_VALINV)/IF(RVI_VALINV*RVF_VALINV>0,2,1)) AS IRI_INDROT,              RVF_EXIFIN AS IRI_EXIFIN,              RVF_EXIFIN/(RII_COSVTA/((RVI_VALINV+RVF_VALINV)/IF(RVI_VALINV*RVF_VALINV>0,2,1))) AS IRI_DIAS,              RII_FCHDES AS IRI_FCHDES,              RII_FCHHAS AS IRI_FCHHAS,              DATEDIFF(RII_HASTA, RII_DESDE) AS IRI_NDIAS              FROM 
               VIEW_DPLIBINVDET_MES               
 INNER JOIN VIEW_DPLIBINVINI_MES ON RII_CODSUC=RVI_CODSUC AND RII_CODIGO=RVI_CODIGO             
 INNER JOIN VIEW_DPLIBINVFIN_MES ON RII_CODSUC=RVF_CODSUC AND RII_CODIGO=RVF_CODIGO
;

-- 383
 CREATE OR REPLACE VIEW  VIEW_DPLIBINVIRI_TRI AS 
SELECT                     RII_CODSUC AS IRI_CODSUC,                    RII_CODIGO AS IRI_CODIGO,                    RII_COSVTA AS IRI_COSVTA,                    RVI_VALINV AS IRI_VALINI,                    RVF_VALINV AS IRI_VALFIN,                    (RVI_VALINV+RVF_VALINV)/IF(RVI_VALINV*RVF_VALINV>0,2,1) AS IRI_VALPRO,                    RII_COSVTA/((RVI_VALINV+RVF_VALINV)/IF(RVI_VALINV*RVF_VALINV>0,2,1)) AS IRI_INDROT,                    RVF_EXIFIN AS IRI_EXIFIN,                    RVF_EXIFIN/(RII_COSVTA/((RVI_VALINV+RVF_VALINV)/IF(RVI_VALINV*RVF_VALINV>0,2,1))) AS IRI_DIAS,                    RII_DESDE AS IRI_DESDE,                    RII_HASTA AS IRI_HASTA,     RII_FCHDES AS IRI_FCHDES,    RII_FCHHAS AS IRI_FCHHAS,                   DATEDIFF(RII_HASTA, RII_DESDE) AS IRI_NDIAS                    FROM 
                     VIEW_DPLIBINVDET_TRI                     
 INNER JOIN VIEW_DPLIBINVINI_TRI ON RII_CODSUC=RVI_CODSUC AND RII_CODIGO=RVI_CODIGO                   
 INNER JOIN VIEW_DPLIBINVFIN_TRI ON RII_CODSUC=RVF_CODSUC AND RII_CODIGO=RVF_CODIGO       
 ORDER BY RII_CODIGO
;

-- 384
 CREATE OR REPLACE VIEW  VIEW_DPLIBINVIRI_SEM AS 
SELECT               RII_CODSUC AS IRI_CODSUC,              RII_CODIGO AS IRI_CODIGO,              RII_COSVTA AS IRI_COSVTA,              RVI_VALINV AS IRI_VALINI,              RVF_VALINV AS IRI_VALFIN,              (RVI_VALINV+RVF_VALINV)/IF(RVI_VALINV*RVF_VALINV>0,2,1) AS IRI_VALPRO,              RII_COSVTA/((RVI_VALINV+RVF_VALINV)/IF(RVI_VALINV*RVF_VALINV>0,2,1)) AS IRI_INDROT,              RVF_EXIFIN AS IRI_EXIFIN,              RVF_EXIFIN/(RII_COSVTA/((RVI_VALINV+RVF_VALINV)/IF(RVI_VALINV*RVF_VALINV>0,2,1))) AS IRI_DIAS,              RII_FCHDES AS IRI_FCHDES,              RII_FCHHAS AS IRI_FCHHAS,              DATEDIFF(RII_HASTA, RII_DESDE) AS IRI_NDIAS              FROM 
               VIEW_DPLIBINVDET_SEM               
 INNER JOIN VIEW_DPLIBINVINI_SEM ON RII_CODSUC=RVI_CODSUC AND RII_CODIGO=RVI_CODIGO             
 INNER JOIN VIEW_DPLIBINVFIN_SEM ON RII_CODSUC=RVF_CODSUC AND RII_CODIGO=RVF_CODIGO
;

-- 385
 CREATE OR REPLACE VIEW  VIEW_DPLIBINVIRI_ANO AS 
SELECT               RII_CODSUC AS IRI_CODSUC,              RII_CODIGO AS IRI_CODIGO,              RII_COSVTA AS IRI_COSVTA,              RVI_VALINV AS IRI_VALINI,              RVF_VALINV AS IRI_VALFIN,              (RVI_VALINV+RVF_VALINV)/IF(RVI_VALINV*RVF_VALINV>0,2,1) AS IRI_VALPRO,              RII_COSVTA/((RVI_VALINV+RVF_VALINV)/IF(RVI_VALINV*RVF_VALINV>0,2,1)) AS IRI_INDROT,              RVF_EXIFIN AS IRI_EXIFIN,              RVF_EXIFIN/(RII_COSVTA/((RVI_VALINV+RVF_VALINV)/IF(RVI_VALINV*RVF_VALINV>0,2,1))) AS IRI_DIAS,              RII_FCHDES AS IRI_FCHDES,              RII_FCHHAS AS IRI_FCHHAS,              DATEDIFF(RII_HASTA, RII_DESDE) AS IRI_NDIAS              FROM 
               VIEW_DPLIBINVDET_ANO               
 INNER JOIN VIEW_DPLIBINVINI_ANO ON RII_CODSUC=RVI_CODSUC AND RII_CODIGO=RVI_CODIGO             
 INNER JOIN VIEW_DPLIBINVFIN_ANO ON RII_CODSUC=RVF_CODSUC AND RII_CODIGO=RVF_CODIGO
;

-- 386
 CREATE OR REPLACE VIEW  VIEW_LIBCOMPRARES AS 
SELECT     DOC_CODSUC          AS LIB_CODSUC,                    DOC_LIBCOM          AS LIB_NUMERO,                    YEAR(DOC_FCHDEC)    AS LIB_YEAR,                    MONTH(DOC_FCHDEC)   AS LIB_MES,                   
 SUM(DOC_MTOEXE)     AS LIB_MTOEXE,                
 SUM(IF(DOC_CREFIS=0,DOC_MTOIVA,0)) AS LIB_SINCRE,                  
 SUM(DOC_BASNET)     AS LIB_BASNET,                   
 SUM(IF(DOC_CREFIS=1,DOC_MTOIVA,0)) AS LIB_MTOIVA,                  
 SUM(RTI_MONTO)      AS LIB_MTORTI,                   
 SUM(DOC_NETO)       AS LIB_NETO,                    COUNT(*)            AS LIB_CUANTOS                    FROM 
 DPDOCPRO     
 INNER JOIN DPTIPDOCPRO ON DOC_TIPDOC=TDC_TIPO AND TDC_LIBCOM=1                    LEFT JOIN VIEW_DOCPRORTI ON DOC_CODSUC=RTI_CODSUC AND                                                 DOC_TIPDOC=RTI_TIPDOC AND                                                 DOC_CODIGO=RTI_CODIGO AND                                                 DOC_NUMERO=RTI_NUMDOC                    WHERE DOC_LIBCOM<>"" AND DOC_ACT=1 AND DOC_TIPTRA="D"                   
 GROUP BY DOC_CODSUC,DOC_LIBCOM                   
 ORDER BY DOC_CODSUC,DOC_LIBCOM
;

-- 387
 CREATE OR REPLACE VIEW  VIEW_RDDMENSUAL AS 
SELECT   DOC_CODSUC       AS RDD_CODSUC, DOC_SERFIS       AS RDD_SERFIS, DOC_CONDIC       AS RDD_INIFIN, YEAR(DOC_FECHA)  AS RDD_YEAR,   MONTH(DOC_FECHA) AS RDD_MES,    DAY(DOC_FECHA)   AS RDD_DIA,    DOC_NUMERO       AS RDD_DESDE,  DOC_NUMFIS       AS RDD_HASTA,  DOC_GIRNUM       AS RDD_ZETA ,  IVA_MTOGN        AS RDD_MTOGN,  IVA_MTORD        AS RDD_MTORD,  MAX(DOC_FECHA)   AS RDD_FECHA, 
 SUM(DOC_BASNET)  AS RDD_BASE  ,
 SUM(DOC_MTOIVA)  AS RDD_IVA   ,
 SUM(DOC_NETO  )  AS RDD_NETO  ,
 SUM(DOC_MTOEXE)  AS RDD_MTOEXE,
 SUM(DOC_MTODIV)  AS RDD_MTOIGT, COUNT(*)         AS RDD_RECCO   FROM 
 DPDOCCLI   LEFT JOIN VIEW_DOCCLI_MOV_IVA  ON IVA_CODSUC=DOC_CODSUC AND IVA_DOCUME=DOC_NUMERO  WHERE DOC_TIPDOC="RDD" AND DOC_TIPTRA="D" AND DOC_ACT=1
 GROUP BY DOC_CODSUC,DOC_SERFIS,DOC_FECHA 
 ORDER BY DOC_CODSUC,DOC_FECHA ,DOC_SERFIS;

-- 388
 CREATE OR REPLACE VIEW  VIEW_RDVMENSUAL AS 
SELECT   DOC_CODSUC       AS RDV_CODSUC,        DOC_SERFIS       AS RDV_SERFIS,        DOC_CONDIC       AS RDV_INIFIN,        YEAR(DOC_FECHA)  AS RDV_YEAR,          MONTH(DOC_FECHA) AS RDV_MES,           DAY(DOC_FECHA)   AS RDV_DIA,           DOC_NUMERO       AS RDV_DESDE,         DOC_NUMFIS       AS RDV_HASTA,         DOC_GIRNUM       AS RDV_ZETA,          MAX(DOC_FECHA)   AS RDV_FECHA,         IVA_MTOGN        AS RDV_MTOGN, IVA_MTORD        AS RDV_MTORD,
 SUM(DOC_BASNET)  AS RDV_BASE  ,
 SUM(DOC_MTOIVA)  AS RDV_IVA   ,
 SUM(DOC_NETO  )  AS RDV_NETO  ,
 SUM(DOC_MTOEXE)  AS RDV_MTOEXE,
 SUM(DOC_MTODIV)  AS RDV_MTOIGT,
 SUM(DOC_OTROS)   AS RDV_RECCO   FROM 
 DPDOCCLI   LEFT JOIN VIEW_DOCCLI_MOV_IVA  ON IVA_CODSUC=DOC_CODSUC AND IVA_DOCUME=DOC_NUMERO  WHERE DOC_TIPDOC="RDV" AND DOC_TIPTRA="D" AND DOC_ACT=1 
 GROUP BY DOC_CODSUC,DOC_SERFIS,DOC_FECHA 
 ORDER BY DOC_CODSUC,DOC_FECHA ,DOC_SERFIS;

-- 389
 CREATE OR REPLACE VIEW  VIEW_EPEDIDOSLOG AS 
SELECT             INV_CODIGO AS CODE,            INV_DESCRI AS NAME,            INV_IVA    AS TAX,            IME_UNDMED AS MEASURE,            IME_CANTID AS MEASUREXUNIT,            GRU_DESCRI AS X,            MAR_DESCRI AS Y,            DEP_DESCRI AS Z,            EXL_CANTID AS quantity,            PRE_PRECIO AS PRICE,    INV_FCHACT AS DATE            FROM 
 DPINV           
 INNER JOIN DPGRU          ON INV_GRUPO=GRU_CODIGO           
 INNER JOIN DPMARCAS       ON INV_CODMAR=MAR_CODIGO           
 INNER JOIN DPDPTO         ON INV_CODDEP=DEP_CODIGO           
 INNER JOIN DPINVMED       ON INV_CODIGO=IME_CODIGO AND IME_VENTA="S"           
 INNER JOIN DPPRECIOS      ON INV_CODIGO=PRE_CODIGO AND IME_UNDMED=PRE_UNDMED AND PRE_LISTA="A"            LEFT  JOIN VIEW_INVEXILOG ON INV_CODIGO=EXL_CODIGO            WHERE INV_UTILIZ="Venta"           
 ORDER BY GRU_CODIGO,CODE
;

-- 390
 CREATE OR REPLACE VIEW  VIEW_DPPLAFINDET AS 
SELECT  PLP_CODSUC AS PLA_CODSUC, PLP_TIPDOC AS PLA_TIPDOC, PLP_CODIGO AS PLA_CODIGO, PLP_NUMREG AS PLA_NUMREG, TDC_DESCRI AS PLA_DESCRI, PLP_FECHA  AS PLA_FECHA,  PLP_VALCAM AS PLA_VALCAM,  CASE WHEN PLP_MONTO IS NULL THEN 0 ELSE PLP_MONTO/PLP_VALCAM                         END AS PLA_MTOPLA, CASE WHEN DOC_NETO  IS NULL THEN 0 ELSE DOC_NETO /DOC_VALCAM                         END AS PLA_MTOREG, CASE WHEN DOC_NETO  IS NULL THEN 0 ELSE (PLP_MONTO/PLP_VALCAM)-(DOC_NETO/DOC_VALCAM) END AS PLA_MTOPEN, CASE WHEN PAG_NETO  IS NULL THEN 0 ELSE PAG_NETO/PLP_VALCAM                          END AS PLA_MTOPAG  FROM 
 DPTIPDOCPRO 
 INNER JOIN dpdocproprog     ON PLP_TIPDOC=TDC_TIPO   
 INNER JOIN dpproveedorprog  ON PLP_CODSUC=PGC_CODSUC  AND  PLP_CODIGO=PGC_CODIGO AND PLP_TIPDOC=PGC_TIPDOC AND PLP_REFERE=PGC_REFERE   LEFT  JOIN dpdocpro         ON PLP_CODSUC=DOC_CODSUC  AND  PLP_TIPDOC=DOC_TIPDOC AND PLP_CODIGO=DOC_CODIGO AND PLP_NUMREG=DOC_PPLREG  AND PLP_NUMDOC=DOC_NUMERO AND DOC_TIPTRA="D"  LEFT  JOIN VIEW_DPDOCPROPAG ON DOC_CODSUC=PAG_CODSUC  AND  DOC_TIPDOC=PAG_TIPDOC AND DOC_CODIGO=PAG_CODIGO AND DOC_NUMERO=PAG_NUMERO  
 ORDER BY PLP_FECHA
;

-- 391
 CREATE OR REPLACE VIEW  VIEW_DPPLAFINRES AS 
SELECT  PLA_CODSUC,PLA_TIPDOC, PLA_FECHA,
 SUM(PLA_MTOPLA) AS PLA_MTOPLA,
 SUM(PLA_MTOREG) AS PLA_MTOREG,
 SUM(PLA_MTOPEN) AS PLA_MTOPEN,
 SUM(PLA_MTOPAG) AS PLA_MTOPAG,
 SUM(PLA_MTOREG-PLA_MTOPAG) AS PLA_MTOCXP  FROM 
 view_dpplafindet 
 GROUP BY PLA_CODSUC,PLA_TIPDOC,PLA_FECHA ;

-- 392
 CREATE OR REPLACE VIEW  VIEW_DPPLAFINRESDIA AS 
SELECT    PLA_CODSUC,PLA_TIPDOC,   PLA_FECHA,  
 SUM(PLA_MTOPLA) AS PLA_MTOPLA,  
 SUM(PLA_MTOREG) AS PLA_MTOREG,  
 SUM(PLA_MTOPEN) AS PLA_MTOPEN,  
 SUM(PLA_MTOPAG) AS PLA_MTOPAG,  
 SUM(PLA_MTOREG-PLA_MTOPAG) AS PLA_MTOCXP    FROM 
 view_dpplafindet   
 GROUP BY PLA_CODSUC,PLA_TIPDOC,PLA_FECHA
;

-- 393
 CREATE OR REPLACE VIEW  VIEW_DPINVPRECIOS AS 
SELECT PRE_CODIGO, PRE_UNDMED,  PRE_PRECIO,  PRE_LISTA,   PRE_CODMON,  PRE_FECHA,   IF(MAX_VALOR IS NULL,0,MAX_VALOR) AS PRE_DIVISA, PRE_PRECIO*MAX_VALOR AS PRE_MONNAC  FROM 
 VIEW_INVMEDPRESENTACION 
 INNER JOIN dpprecios          ON PRE_CODIGO =IME_CODIGO AND PRE_UNDMED=IME_UNDMED 
 INNER JOIN dppreciotip        ON PRE_LISTA  =TPP_CODIGO   LEFT  JOIN VIEW_HISMONMAXVALOR ON PRE_CODMON=MAX_CODIGO   WHERE PRE_PRECIO>0  
 GROUP BY PRE_CODIGO,PRE_UNDMED 
 ORDER BY PRE_CODIGO;

-- 394
 CREATE OR REPLACE VIEW  VIEW_DPINVMULTIPROV AS 
SELECT   UCP_CODSUC AS PMP_CODSUC,  UCP_CODIGO AS PMP_CODIGO,  COUNT(*) AS PMP_CANTID  FROM 
  VIEW_DPPROVXINV   
 GROUP BY UCP_CODSUC,UCP_CODIGO  HAVING PMP_CANTID>1
;

-- 395
 CREATE OR REPLACE VIEW  VIEW_EPDPINV AS 
SELECT       INV_CODIGO,      LEFT(INV_DESCRI,120) AS INV_DESCRI,      INV_IVA,      PRE_UNDMED AS INV_UNDMED,      IME_CANTID AS INV_CANMED,      PRE_LISTA  AS INV_LISTA,      PRE_CODMON AS INV_CODMON,      PRE_PRECIO AS INV_PRECIO,      SLD_CONTAB AS INV_EXICON,      SLD_FISICO AS INV_EXIFIS,      SLD_LOGICO AS INV_EXILOG,      INV_UTILIZ AS INV_UTILIZ,      GRU_DESCRI AS INV_GRUDES,      MAR_DESCRI AS INV_MARDES    FROM 
 DPINV       
 INNER JOIN VIEW_INVMEDPRESENTACION ON IME_CODIGO=INV_CODIGO       LEFT JOIN DPPRECIOS ON DPINV.INV_CODIGO=PRE_CODIGO AND IME_UNDMED=PRE_UNDMED      LEFT JOIN DPGRU ON INV_GRUPO=GRU_CODIGO        LEFT JOIN DPMARCAS ON INV_CODMAR=MAR_CODIGO       LEFT JOIN DPINVSLD ON SLD_CODSUC="000001" AND SLD_CODIGO=INV_CODIGO             WHERE INV_ESTADO="A" AND (INV_APLICA="V" OR INV_APLICA="T") AND (INV_UTILIZ="Venta")       
 GROUP BY  INV_CODIGO,INV_DESCRI,INV_IVA,PRE_UNDMED,PRE_LISTA,PRE_CODMON         
 ORDER BY INV_CODIGO
;

-- 396
 CREATE OR REPLACE VIEW  VIEW_DPINVCOMANDAS AS 
SELECT                     PRE_CODIGO AS INV_CODIGO,                    INV_DESCRI AS INV_DESCRI,                    PRE_UNDMED AS INV_UNDMED,                    PRE_PRECIO AS INV_PRECIO,                    PRE_LISTA  AS INV_LISTA                    FROM 
 VIEW_INVMEDPRESENTACION                    
 INNER JOIN DPPRECIOS ON PRE_CODIGO=IME_CODIGO AND PRE_UNDMED=IME_UNDMED                    
 INNER JOIN DPINV     ON PRE_CODIGO=INV_CODIGO AND (LEFT(INV_UTILIZ,1)="V" OR LEFT(INV_UTILIZ,1)="F")                  WHERE PRE_PRECIO>0                       
 GROUP BY PRE_CODIGO,PRE_UNDMED           
 ORDER BY PRE_CODIGO
;

-- 397
 CREATE OR REPLACE VIEW  VIEW_QUINCELIBCOM AS 
SELECT    DOC_CODSUC AS RLC_CODSUC,  FCH_DESDE  AS RLC_DESDE,   FCH_HASTA  AS RLC_HASTA,   MIN(DOC_FECHA)        AS RLC_FCHINI, MAX(DOC_FECHA)        AS RLC_FCHFIN,
 SUM(DOC_NETO*DOC_CXP) AS RLC_NETO,   COUNT(*)              AS RLC_CANTID  FROM 
 VIEW_DPDIARIO_QUINCE  
 INNER JOIN DPDOCPRO   ON DOC_FECHA>=FCH_DESDE AND DOC_FECHA<=FCH_HASTA AND DOC_TIPTRA="D" AND DOC_ACT=1 AND DOC_CXP<>0 
 GROUP BY DOC_CODSUC,FCH_DESDE,FCH_HASTA  
 ORDER BY DOC_CODSUC,FCH_DESDE,FCH_HASTA;

-- 398
 CREATE OR REPLACE VIEW  VIEW_QUINCELIBVTA AS 
SELECT    DOC_CODSUC AS RLV_CODSUC,  FCH_DESDE  AS RLV_DESDE,   FCH_HASTA  AS RLV_HASTA,   MIN(DOC_FECHA)        AS RLV_FCHINI,  MAX(DOC_FECHA)        AS RLV_FCHFIN, 
 SUM(DOC_NETO*DOC_CXC) AS RLV_NETO,    COUNT(*)              AS RLV_CANTID   FROM 
 VIEW_DPDIARIO_QUINCE 
 INNER JOIN DPDOCCLI    ON DOC_FECHA>=FCH_DESDE AND DOC_FECHA<=FCH_HASTA AND DOC_TIPTRA="D" AND DOC_ACT=1 AND DOC_CXC<>0 
 INNER JOIN DPTIPDOCCLI ON DOC_TIPDOC=TDC_TIPO AND TDC_LIBVTA=1 
 GROUP BY DOC_CODSUC,FCH_DESDE,FCH_HASTA 
 ORDER BY DOC_CODSUC,FCH_DESDE,FCH_HASTA;

-- 399
 CREATE OR REPLACE VIEW  VIEW_RDVXSERIEFISCAL AS 
SELECT     RDV_CODSUC     AS RDM_CODSUC,    RDV_SERFIS     AS RDM_SERFIS,    MAX(RDV_FECHA) AS RDM_FECHA     FROM 
 VIEW_RDVMENSUAL   
 GROUP BY RDV_SERFIS   
 ORDER BY RDV_SERFIS,RDV_FECHA DESC
;

-- 400
 CREATE OR REPLACE VIEW  VIEW_RESUMENSEMANAL AS 
SELECT PER_CODIGO AS RES_CODIGO,                                     PER_NOMBRE AS RES_NOMBRE,                             CMI_FCHDIA AS RES_FECHA,                             IF(((dayofweek(CMI_FCHDIA) = "2") and (dayofweek(CMI_FCHMOV) > 0)),concat(min(CMI_HORA)," ",max(CMI_HORA)," (",COUNT(*),")"),"Disponible") AS Lunes,      if(((dayofweek(CMI_FCHDIA) = "3") and (dayofweek(CMI_FCHMOV) > 0)),concat(min(CMI_HORA)," ",max(CMI_HORA)," (",COUNT(*),")"),"Disponible") AS `Martes`,                              if(((dayofweek(CMI_FCHDIA) = "4") and (dayofweek(CMI_FCHMOV) > 0)),concat(min(CMI_HORA)," ",max(CMI_HORA)," (",COUNT(*),")"),"Disponible") AS Miercoles,                              if(((dayofweek(CMI_FCHDIA) = "5") and (dayofweek(CMI_FCHMOV) > 0)),concat(min(CMI_HORA)," ",max(CMI_HORA)," (",COUNT(*),")"),"Disponible") AS Jueves,                              if(((dayofweek(CMI_FCHDIA) = "6") and (dayofweek(CMI_FCHMOV) > 0)),concat(min(CMI_HORA)," ",max(CMI_HORA)," (",COUNT(*),")"),"Disponible") AS Viernes,                              if(((dayofweek(CMI_FCHDIA) = "7") and (dayofweek(CMI_FCHMOV) > 0)),concat(min(CMI_HORA)," ",max(CMI_HORA)," (",COUNT(*),")"),"Disponible") AS Sabado,                              if(((dayofweek(CMI_FCHDIA) = "1") and (dayofweek(CMI_FCHMOV) > 0)),concat(min(CMI_HORA)," ",max(CMI_HORA)," (",COUNT(*),")"),"Disponible") AS Domingo,                               CMI_FCHDIA AS CMI_FCHDIA                                       FROM 
         DPPERSONAL                              
 INNER JOIN VIEW_CALMOVINV  ON  DPPERSONAL.PER_CODIGO = VIEW_CALMOVINV.CMI_CODIGO                                                         OR  ISNULL(VIEW_CALMOVINV.CMI_CODIGO)                        WHERE PER_ACTIVO = 1 and PER_SEMANA = 1           
 GROUP BY PER_CODIGO,PER_NOMBRE,CMI_FCHDIA                              
 ORDER BY PER_CODIGO,CMI_DOW
;

-- 401
 CREATE OR REPLACE VIEW  VIEW_SEMSEMLIBVTA AS 
SELECT             DOC_CODSUC AS RLV_CODSUC,            SEM_DESDE  AS RLV_DESDE,            SEM_HASTA  AS RLV_HASTA,            MIN(DOC_FECHA)        AS RLV_FCHINI,            MAX(DOC_FECHA)        AS RLV_FCHFIN,           
 SUM(DOC_NETO*DOC_CXC) AS RLV_NETO,            COUNT(*)              AS RLV_CANTID            FROM 
 VIEW_DPDIARIO_SEMLUN           
 INNER JOIN DPDOCCLI    ON DOC_FECHA>=SEM_DESDE AND DOC_FECHA<=SEM_HASTA AND DOC_TIPTRA="D" AND DOC_ACT=1 AND DOC_CXC<>0         
 INNER JOIN DPTIPDOCCLI ON DOC_TIPDOC=TDC_TIPO AND TDC_LIBVTA=1        
 GROUP BY DOC_CODSUC,SEM_DESDE,SEM_HASTA           
 ORDER BY DOC_CODSUC,SEM_DESDE,SEM_HASTA
;

-- 402
 CREATE OR REPLACE VIEW  VIEW_ZDFMENSUAL AS 
SELECT   DOC_CODSUC       AS ZDF_CODSUC, DOC_SERFIS       AS ZDF_SERFIS, DOC_CONDIC       AS ZDF_INIFIN, YEAR(DOC_FECHA)  AS ZDF_YEAR,   MONTH(DOC_FECHA) AS ZDF_MES,    DAY(DOC_FECHA)   AS ZDF_DIA,    DOC_NUMERO       AS ZDF_NUMERO, DOC_PLAEXP       AS ZDF_DESDE,  DOC_NUMFIS       AS ZDF_HASTA,  DOC_GIRNUM       AS ZDF_ZETA,   MAX(DOC_FECHA)   AS ZDF_FECHA, 
 SUM(DOC_BASNET)  AS ZDF_BASE  ,
 SUM(DOC_MTOIVA)  AS ZDF_IVA   ,
 SUM(DOC_NETO  )  AS ZDF_NETO  ,
 SUM(DOC_MTOEXE)  AS ZDF_MTOEXE,
 SUM(DOC_OTROS )  AS ZDF_MTOIGT,
 SUM(DOC_MTODIV)  AS ZDF_RECCO , IVD_MTOEX AS  ZDF_MTOEX, IVD_MTOGN AS  ZDF_MTOGN, IVD_MTORD AS  ZDF_MTORD, IVD_MTOS1 AS  ZDF_MTOS1, IVD_MTOXX AS  ZDF_MTOXX, IVD_TOTEX AS  ZDF_TOTEX, IVD_TOTGN AS  ZDF_TOTGN, IVD_TOTRD AS  ZDF_TOTRD, IVD_TOTS1 AS  ZDF_TOTS1, IVD_TOTXX AS  ZDF_TOTXX FROM 
 DPDOCCLI   LEFT JOIN VIEW_DOCCLI_CTA_IVA  ON IVD_CODSUC=DOC_CODSUC AND IVD_TIPDOC=DOC_TIPDOC AND IVD_DOCUME=DOC_NUMERO  WHERE DOC_TIPDOC="ZDF" AND DOC_TIPTRA="D" AND DOC_ACT=1 
 GROUP BY DOC_CODSUC,DOC_SERFIS,DOC_GIRNUM,DOC_FECHA 
 ORDER BY DOC_CODSUC,DOC_SERFIS,DOC_GIRNUM,DOC_FECHA;

-- 403
 CREATE OR REPLACE VIEW  VIEW_ZFFMENSUAL AS 
SELECT   DOC_CODSUC       AS ZFF_CODSUC, DOC_SERFIS       AS ZFF_SERFIS, DOC_CONDIC       AS ZFF_INIFIN, YEAR(DOC_FECHA)  AS ZFF_YEAR,   MONTH(DOC_FECHA) AS ZFF_MES,    DAY(DOC_FECHA)   AS ZFF_DIA,    DOC_NUMERO       AS ZFF_NUMERO, DOC_PLAEXP       AS ZFF_DESDE,  DOC_NUMFIS       AS ZFF_HASTA,  DOC_GIRNUM       AS ZFF_ZETA,   MAX(DOC_FECHA)   AS ZFF_FECHA, 
 SUM(DOC_BASNET)  AS ZFF_BASE  ,
 SUM(DOC_MTOIVA)  AS ZFF_IVA   ,
 SUM(DOC_NETO  )  AS ZFF_NETO  ,
 SUM(DOC_MTOEXE)  AS ZFF_MTOEXE,
 SUM(DOC_OTROS )  AS ZFF_MTOIGT,
 SUM(DOC_MTODIV)  AS ZFF_RECCO  , IVD_MTOEX AS  ZFF_MTOEX, IVD_MTOGN AS  ZFF_MTOGN, IVD_MTORD AS  ZFF_MTORD, IVD_MTOS1 AS  ZFF_MTOS1, IVD_MTOXX AS  ZFF_MTOXX, IVD_TOTEX AS  ZFF_TOTEX, IVD_TOTGN AS  ZFF_TOTGN, IVD_TOTRD AS  ZFF_TOTRD, IVD_TOTS1 AS  ZFF_TOTS1, IVD_TOTXX AS  ZFF_TOTXX FROM 
 DPDOCCLI   LEFT JOIN VIEW_DOCCLI_CTA_IVA  ON IVD_CODSUC=DOC_CODSUC AND IVD_TIPDOC=DOC_TIPDOC AND IVD_DOCUME=DOC_NUMERO  WHERE DOC_TIPDOC="ZFF" AND DOC_TIPTRA="D" AND DOC_ACT=1 
 GROUP BY DOC_CODSUC,DOC_SERFIS,DOC_GIRNUM,DOC_FECHA 
 ORDER BY DOC_CODSUC,DOC_SERFIS,DOC_GIRNUM,DOC_FECHA;

-- 404
 CREATE OR REPLACE VIEW  VIEW_DPDOCCLI_AAMM AS 
SELECT  DOC_CODSUC       AS DOC_CODSUC, DOC_TIPDOC       AS DOC_TIPDOC, DOC_TIPTRA       AS DOC_TIPTRA, LPAD(YEAR(DOC_FECHA),4,"0")  AS DOC_ANO,  LPAD(MONTH(DOC_FECHA),2,"0") AS DOC_MES, 
 SUM(DOC_NETO)    AS DOC_NETO  ,
 SUM(DOC_MTODIV)  AS DOC_MTODIV, COUNT(*)         AS DOC_CANTID,
 SUM(IF(PAG_NETO   IS NULL,0,PAG_NETO  ))  AS PAG_NETO,  
 SUM(IF(PAG_MTODIV IS NULL,0,PAG_MTODIV))  AS PAG_MTODIV  FROM 
 DPDOCCLI   LEFT JOIN view_dpdocclipagdet ON DOC_CODSUC=PAG_CODSUC AND DOC_TIPDOC=PAG_TIPDOC AND DOC_NUMERO=PAG_NUMERO  WHERE DOC_ACT=1
 GROUP BY DOC_CODSUC,DOC_TIPDOC,DOC_TIPTRA,DOC_ANO,DOC_MES 
 ORDER BY DOC_CODSUC,DOC_TIPDOC,DOC_TIPTRA,DOC_ANO,DOC_MES;

-- 405
 CREATE OR REPLACE VIEW  VIEW_DPASIENTOSCTAEJE AS 
SELECT     RMA_NUMEJE AS RME_NUMEJE,   RMA_CUENTA AS RME_CUENTA,   RMA_MTOANT AS RME_MTOANT,   RMA_MTOANT+SUM(IF(RMA_MES=01,RMA_MONTO,0)) AS RME_ENE,   RMA_MTOANT+SUM(IF(RMA_MES<=02,RMA_MONTO,0)) AS RME_FEB,   RMA_MTOANT+SUM(IF(RMA_MES<=03,RMA_MONTO,0)) AS RME_MAR,   RMA_MTOANT+SUM(IF(RMA_MES<=04,RMA_MONTO,0)) AS RME_ABR,   RMA_MTOANT+SUM(IF(RMA_MES<=05,RMA_MONTO,0)) AS RME_MAY,   RMA_MTOANT+SUM(IF(RMA_MES<=06,RMA_MONTO,0)) AS RME_JUN,   RMA_MTOANT+SUM(IF(RMA_MES<=07,RMA_MONTO,0)) AS RME_JUL,   RMA_MTOANT+SUM(IF(RMA_MES<=08,RMA_MONTO,0)) AS RME_AGO,   RMA_MTOANT+SUM(IF(RMA_MES<=09,RMA_MONTO,0)) AS RME_SEP,   RMA_MTOANT+SUM(IF(RMA_MES<=10,RMA_MONTO,0)) AS RME_OCT,   RMA_MTOANT+SUM(IF(RMA_MES<=11,RMA_MONTO,0)) AS RME_NOV,   RMA_MTOANT+SUM(IF(RMA_MES<=12,RMA_MONTO,0)) AS RME_DIC   FROM 
 VIEW_DPASIENTOSCTAEJEMES   
 GROUP BY RMA_NUMEJE,RMA_CUENTA   
 ORDER BY RMA_NUMEJE,RMA_CUENTA
;

-- 406
 CREATE OR REPLACE VIEW  VIEW_DPED_RUTAS AS 
SELECT              CLI_CODVEN AS DRT_CODVEN,             DRT_DIASEM,             RPAD(DAYNAME(DIA_FECHA),15," ") AS DRT_DIA,              DRT_CODRUT,              REN_DESCRI,              DRT_DIADES,              DRT_DIAPED,              DRT_CANTID            FROM 
 DPDIARIO              LEFT JOIN VIEW_DPRUTADIA ON DAYOFWEEK(DIA_FECHA)=DRT_DIASEM              
 INNER JOIN DPRUTAS ON DRT_CODRUT=REN_CODIGO               LEFT  JOIN DPCLIENTES ON CLI_CODRUT=DRT_CODRUT              WHERE REN_ACTIVO=1  AND CLI_CODVEN<>""                        
 GROUP BY CLI_CODVEN,DRT_DIASEM,DRT_CODRUT
;

-- 407
 CREATE OR REPLACE VIEW  VIEW_SEMSEMLIBCOM AS 
SELECT   DOC_CODSUC AS RLC_CODSUC,  SEM_DESDE  AS RLC_DESDE,  SEM_HASTA  AS RLC_HASTA,  MIN(DOC_FECHA)        AS RLC_FCHINI,  MAX(DOC_FECHA)        AS RLC_FCHFIN, 
 SUM(DOC_NETO*DOC_CXP) AS RLC_NETO,  COUNT(*)              AS RLC_CANTID  FROM 
 VIEW_DPDIARIO_SEMLUN 
 INNER JOIN DPDOCPRO   ON DOC_FECHA>=SEM_DESDE AND DOC_FECHA<=SEM_HASTA AND DOC_TIPTRA="D" AND DOC_ACT=1 AND DOC_CXP<>0 
 GROUP BY DOC_CODSUC,SEM_DESDE,SEM_HASTA 
 ORDER BY DOC_CODSUC,SEM_DESDE,SEM_HASTA
;

-- 408
 CREATE OR REPLACE VIEW  VIEW_INVULTCOSTO AS 
SELECT                                 ULT_CODIGO AS ULT_CODIGO,                                MOV_FECHA  AS ULT_FECHA,                                MOV_HORA   AS ULT_HORA,                                MOV_UNDMED AS ULT_UNDMED,                                MOV_CXUND  AS ULT_CXUND,                                MOV_COSTO  AS ULT_COSTO,                                MONTH(MOV_FECHA) AS ULT_MES,                                YEAR(MOV_FECHA)  AS ULT_ANO                                FROM 
                                VIEW_INVULTCOMPRASUC                 
 INNER JOIN DPMOVINV ON ULT_CODIGO=MOV_CODIGO AND ULT_FECHA=MOV_FECHA             
 ORDER BY ULT_CODIGO
;

-- 409
 CREATE OR REPLACE VIEW  VIEW_INVULTCOSTOUSD AS 
SELECT       MOV_CODSUC AS CDV_CODSUC,      MOV_CODIGO AS CDV_CODIGO,       MOV_FECHA  AS CDV_FECHA,      MOV_COSTO  AS CDV_COSTO,      MOV_UNDMED AS CDV_UNDMED,      MOV_CXUND  AS CDV_CXUND,      HMN_VALOR  AS CDV_VALOR,      MOV_COSTO/HMN_VALOR AS CDV_COSUSD,      (MOV_COSTO/HMN_VALOR)*MAX_VALOR AS CDV_COSACT ,      HMN_CODIGO AS CDV_CODMON     FROM 
 VIEW_INVULTCOMPRASUC        
 INNER JOIN DPMOVINV ON ULT_CODSUC=MOV_CODSUC AND MOV_CODIGO=ULT_CODIGO AND MOV_CONTAB=1 AND MOV_INVACT=1 AND ULT_FECHA=MOV_FECHA       
 INNER JOIN DPHISMON ON HMN_CODIGO="DBC" AND HMN_FECHA=MOV_FECHA         
 INNER JOIN VIEW_HISMONMAXVALOR ON HMN_CODIGO=MAX_CODIGO            
 GROUP BY MOV_CODSUC,MOV_CODIGO    
 ORDER BY MOV_CODSUC,MOV_CODIGO
;

-- 410
 CREATE OR REPLACE VIEW  VIEW_INVULTCOSTXSUC AS 
SELECT                 ULT_CODSUC AS ULT_CODSUC,                ULT_CODIGO AS ULT_CODIGO,                MOV_FECHA  AS ULT_FECHA,                MOV_HORA   AS ULT_HORA,                MOV_UNDMED AS ULT_UNDMED,                MOV_CXUND  AS ULT_CXUND,                MOV_COSTO  AS ULT_COSTO,                MONTH(MOV_FECHA) AS ULT_MES,                YEAR(MOV_FECHA)  AS ULT_ANO                FROM 
                VIEW_INVULTCOMPRASUC 
 INNER JOIN DPMOVINV ON ULT_CODSUC=MOV_CODSUC AND ULT_CODIGO=MOV_CODIGO AND CONCAT(MOV_FECHA,MOV_HORA)=ULT_FCHHOR          
 ORDER BY ULT_CODSUC,ULT_CODIGO
;

-- 411
 CREATE OR REPLACE VIEW  VIEW_DPINVCTA AS 
SELECT INV_CTAMOD,INV_CODIGO,INV_DESCRI  ,VIEW_INVCTA_ACT.INV_CTAACT,VIEW_INVCTA_COS.INV_CTACOS,VIEW_INVCTA_VTA.INV_CTAVTA,VIEW_INVCTA_VTP.INV_CTAVTP,VIEW_INVCTA_VTE.INV_CTAVTE,VIEW_INVCTA_VTH.INV_CTAVTH,VIEW_INVCTA_DVV.INV_CTADVV,VIEW_INVCTA_COM.INV_CTACOM,VIEW_INVCTA_DVC.INV_CTADVC,VIEW_INVCTA_INI.INV_CTAINI,VIEW_INVCTA_FIN.INV_CTAFIN FROM 
 VIEW_DPINV_CTA  LEFT JOIN VIEW_INVCTA_ACT ON INV_CODIGO=ACT_CODINV LEFT JOIN VIEW_INVCTA_COS ON INV_CODIGO=COS_CODINV LEFT JOIN VIEW_INVCTA_VTA ON INV_CODIGO=VTA_CODINV LEFT JOIN VIEW_INVCTA_VTP ON INV_CODIGO=VTP_CODINV LEFT JOIN VIEW_INVCTA_VTE ON INV_CODIGO=VTE_CODINV LEFT JOIN VIEW_INVCTA_VTH ON INV_CODIGO=VTH_CODINV LEFT JOIN VIEW_INVCTA_DVV ON INV_CODIGO=DVV_CODINV LEFT JOIN VIEW_INVCTA_COM ON INV_CODIGO=COM_CODINV LEFT JOIN VIEW_INVCTA_DVC ON INV_CODIGO=DVC_CODINV LEFT JOIN VIEW_INVCTA_INI ON INV_CODIGO=INI_CODINV LEFT JOIN VIEW_INVCTA_FIN ON INV_CODIGO=FIN_CODINV
 ORDER BY INV_CTAMOD,INV_CODIGO
;

-- 412
 CREATE OR REPLACE VIEW  VIEW_DOCPRO_IVA AS 
SELECT DOC_CODSUC AS IVA_CODSUC,DOC_TIPDOC AS IVA_TIPDOC,DOC_CODIGO AS IVA_CODCTA,DOC_NUMERO AS IVA_NUMERO,IF(IVA_MTOEX IS NULL, IVD_MTOEX,IVA_MTOEX) AS IVA_MTOEX,IF(IVA_MTOGN IS NULL, IVD_MTOGN,IVA_MTOGN) AS IVA_MTOGN,IF(IVA_MTORD IS NULL, IVD_MTORD,IVA_MTORD) AS IVA_MTORD,IF(IVA_MTOS1 IS NULL, IVD_MTOS1,IVA_MTOS1) AS IVA_MTOS1,IF(IVA_MTOXX IS NULL, IVD_MTOXX,IVA_MTOXX) AS IVA_MTOXX,IF(IVA_TOTEX IS NULL, IVD_TOTEX,IVA_TOTEX) AS IVA_TOTEX,IF(IVA_TOTGN IS NULL, IVD_TOTGN,IVA_TOTGN) AS IVA_TOTGN,IF(IVA_TOTRD IS NULL, IVD_TOTRD,IVA_TOTRD) AS IVA_TOTRD,IF(IVA_TOTS1 IS NULL, IVD_TOTS1,IVA_TOTS1) AS IVA_TOTS1,IF(IVA_TOTXX IS NULL, IVD_TOTXX,IVA_TOTXX) AS IVA_TOTXX,IF(IVA_BASE IS NULL , IVD_BASE, IVA_BASE ) AS IVA_BASE  FROM 
 DPDOCPRO  LEFT JOIN VIEW_DOCPRO_MOV_IVA ON DOC_CODSUC=IVA_CODSUC AND DOC_TIPDOC=IVA_TIPDOC AND DOC_CODIGO=IVA_CODCTA AND DOC_NUMERO=IVA_DOCUME  LEFT JOIN VIEW_DOCPRO_CTA_IVA ON DOC_CODSUC=IVD_CODSUC AND DOC_TIPDOC=IVD_TIPDOC AND DOC_CODIGO=IVD_CODCTA AND DOC_NUMERO=IVD_DOCUME  WHERE DOC_TIPTRA="D"
 GROUP BY DOC_CODSUC,DOC_TIPDOC,DOC_CODIGO,DOC_NUMERO;

-- 413
 CREATE OR REPLACE VIEW  VIEW_DOCCLI_IVA AS 
SELECT DOC_CODSUC AS IVA_CODSUC,DOC_TIPDOC AS IVA_TIPDOC,DOC_NUMERO AS IVA_NUMERO,IF(IVA_MTOEX IS NULL, IVD_MTOEX,IVA_MTOEX) AS IVA_MTOEX,IF(IVA_MTOGN IS NULL, IVD_MTOGN,IVA_MTOGN) AS IVA_MTOGN,IF(IVA_MTORD IS NULL, IVD_MTORD,IVA_MTORD) AS IVA_MTORD,IF(IVA_MTOS1 IS NULL, IVD_MTOS1,IVA_MTOS1) AS IVA_MTOS1,IF(IVA_MTOXX IS NULL, IVD_MTOXX,IVA_MTOXX) AS IVA_MTOXX,IF(IVA_TOTEX IS NULL, IVD_TOTEX,IVA_MTOEX) AS IVA_TOTEX,IF(IVA_TOTGN IS NULL, IVD_TOTGN,IVA_MTOGN) AS IVA_TOTGN,IF(IVA_TOTRD IS NULL, IVD_TOTRD,IVA_MTORD) AS IVA_TOTRD,IF(IVA_TOTS1 IS NULL, IVD_TOTS1,IVA_MTOS1) AS IVA_TOTS1,IF(IVA_TOTXX IS NULL, IVD_TOTXX,IVA_MTOXX) AS IVA_TOTXX,IF(IVA_BASE IS NULL , IVD_BASE, IVA_BASE ) AS IVA_BASE  FROM 
 DPDOCCLI  LEFT JOIN VIEW_DOCCLI_MOV_IVA ON DOC_CODSUC=IVA_CODSUC AND DOC_TIPDOC=IVA_TIPDOC AND DOC_NUMERO=IVA_DOCUME  LEFT JOIN VIEW_DOCCLI_CTA_IVA ON DOC_CODSUC=IVD_CODSUC AND DOC_TIPDOC=IVD_TIPDOC AND DOC_NUMERO=IVD_DOCUME  WHERE DOC_TIPTRA="D"
 ORDER BY DOC_CODSUC,DOC_TIPDOC,DOC_NUMERO;

